package com.runeassist.flip.model;

import com.runeassist.flip.controller.FlipHistorySyncService;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class FlipManagerMissedFlipsTest {

    @Test
    public void missedFlipsTrackedSeparatelyFromPortfolio() {
        FlipManager fm = new FlipManager(null);
        fm.setPluginUserId(FlipHistorySyncService.PLUGIN_USER_ID);
        FlipV2 ghost = new FlipV2();
        ghost.setId(UUID.fromString("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"));
        ghost.setAccountId(7);
        ghost.setItemId(4151);
        ghost.setOpenedTime(100);
        ghost.setOpenedQuantity(5);
        ghost.setSpent(500);
        ghost.setStatus(FlipStatus.SELLING);
        ghost.setPortfolioId(PortfolioId.GHOST);
        ghost.setDeleted(false);
        ghost.setSeqNo(1);
        ghost.setUpdatedTime(100);
        ghost.setUserId(FlipHistorySyncService.PLUGIN_USER_ID);
        List<FlipV2> batch = new ArrayList<>();
        batch.add(ghost);
        fm.mergeFlips(batch, FlipHistorySyncService.PLUGIN_USER_ID);
        List<FlipV2> missed = fm.getMissedFlipsForAccount(7);
        assertEquals(1, missed.size());
        assertTrue(fm.isGhostFlip(7, ghost.getId()));
    }
}

package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class RealizedStatsScopeTest {
    @Test void accountAndCloseTimeFilterProfitAndOpenCapitalDoesNotDiluteRoi() {
        FlipManager manager = new FlipManager(null);
        manager.mergeFlips(new ArrayList<>(Arrays.asList(
                flip(1, 100, 200, 100, 20), flip(2, 100, 200, 200, 40),
                flip(1, 180, 0, 100_000, 0), flip(1, 100, 120, 100, 30))), 0);
        manager.setIntervalStartTime(150);
        manager.setIntervalAccount(1);
        Stats stats = manager.getRealizedIntervalStats();
        assertEquals(1, stats.flipsMade);
        assertEquals(20, stats.profit);
        assertEquals(100, stats.gross);
        assertEquals(0.2, stats.calculateRoi(), 0.0001);
        manager.setIntervalAccount(null);
        assertEquals(60, manager.getRealizedIntervalStats().profit);
    }

    private FlipV2 flip(int account, int opened, int closed, long spent, long profit) {
        FlipV2 flip = new FlipV2();
        flip.setId(UUID.randomUUID()); flip.setItemId(4151); flip.setAccountId(account);
        flip.setOpenedTime(opened); flip.setClosedTime(closed); flip.setSpent(spent); flip.setProfit(profit);
        flip.setOpenedQuantity(1); flip.setClosedQuantity(closed == 0 ? 0 : 1);
        flip.setStatus(closed == 0 ? FlipStatus.BUYING : FlipStatus.FINISHED);
        flip.setPortfolioId(1); flip.setUpdatedTime(200); flip.setSeqNo(1);
        return flip;
    }
}

package com.runeassist.flip.model;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;

public class VisualizeFlipResponseTest {

    private final Gson gson = new Gson();

    @Test
    public void fromJsonReadsLotsAndGraph() {
        String raw = "{"
                + "\"buyTimes\":[100,110],"
                + "\"buyVolumes\":[5,5],"
                + "\"buyPrices\":[1000,1010],"
                + "\"sellTimes\":[200],"
                + "\"sellVolumes\":[10],"
                + "\"sellPrices\":[1200],"
                + "\"graphData\":{\"itemId\":4151,\"high1hTimes\":[1],\"high1hPrices\":[10]}"
                + "}";
        JsonObject o = JsonParser.parseString(raw).getAsJsonObject();
        VisualizeFlipResponse r = VisualizeFlipResponse.fromJson(o, gson);
        assertArrayEquals(new int[]{100, 110}, r.buyTimes);
        assertArrayEquals(new int[]{5, 5}, r.buyVolumes);
        assertArrayEquals(new long[]{1000, 1010}, r.buyPrices);
        assertArrayEquals(new int[]{200}, r.sellTimes);
        assertArrayEquals(new int[]{10}, r.sellVolumes);
        assertArrayEquals(new long[]{1200}, r.sellPrices);
        assertNotNull(r.graphData);
        assertEquals(4151, r.graphData.itemId);
        assertNull(r.message);
    }

    @Test
    public void fromJsonReadsMessageWhenNoGraph() {
        JsonObject o = JsonParser.parseString(
                "{\"buyTimes\":[],\"sellTimes\":[],\"message\":\"No price data available for this item.\"}"
        ).getAsJsonObject();
        VisualizeFlipResponse r = VisualizeFlipResponse.fromJson(o, gson);
        assertEquals("No price data available for this item.", r.message);
        assertNull(r.graphData);
        assertEquals(0, r.buyTimes.length);
    }

    @Test
    public void fromLocalLotsFallsBackToFlipAggregates() {
        FlipV2 flip = new FlipV2();
        flip.setId(UUID.randomUUID());
        flip.setOpenedTime(50);
        flip.setOpenedQuantity(3);
        flip.setSpent(300);
        flip.setClosedTime(90);
        flip.setClosedQuantity(3);
        flip.setReceivedPostTax(280);
        flip.setTaxPaid(20);
        VisualizeFlipResponse r = VisualizeFlipResponse.fromLocalLots(null, flip, Collections.emptyList());
        assertArrayEquals(new int[]{50}, r.buyTimes);
        assertArrayEquals(new int[]{3}, r.buyVolumes);
        assertArrayEquals(new long[]{100}, r.buyPrices);
        assertArrayEquals(new int[]{90}, r.sellTimes);
        assertArrayEquals(new int[]{3}, r.sellVolumes);
        assertArrayEquals(new long[]{100}, r.sellPrices);
    }
}

package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

public class SuggestionManagerLifecycleTest
{
    @Test
    public void submittedSuggestionMatchesOnlyTheSameOfferForFiveTicks()
    {
        Suggestion suggestion = new Suggestion();
        suggestion.setType(SuggestionType.BUY);
        suggestion.setItemId(4151);
        suggestion.setServerSuggestionId("11111111-1111-1111-1111-111111111111");
        SuggestionManager manager = new SuggestionManager();

        manager.recordOfferSubmission(suggestion, 100);

        assertEquals(suggestion.getServerSuggestionId(),
                manager.matchingSubmittedSuggestion(4151, OfferStatus.BUY, 105));
        assertNull(manager.matchingSubmittedSuggestion(4151, OfferStatus.SELL, 105));
        assertNull(manager.matchingSubmittedSuggestion(4151, OfferStatus.BUY, 106));
    }
}

package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * WAIT with a full GE board and a finished box must prompt Collect so a slot
 * frees for selling held stock. Reserved-slots=0 used to skip that prompt.
 */
public class AccountStatusCollectTest {

    @Test
    public void waitOnFullBoardWithFinishedOfferAsksCollect() {
        AccountStatus status = memberStatus();
        StatusOfferList offers = status.getOffers();
        for (int i = 0; i < 7; i++) {
            offers.set(i, fillingBuy(i, 1000 + i));
        }
        offers.set(7, finishedSell(7, 2199));

        assertTrue(status.isCollectNeeded(waitSuggestion(), false));
    }

    @Test
    public void waitOnFullBoardAllFillingDoesNotAskCollect() {
        AccountStatus status = memberStatus();
        StatusOfferList offers = status.getOffers();
        for (int i = 0; i < 8; i++) {
            offers.set(i, fillingBuy(i, 1000 + i));
        }

        assertFalse(status.isCollectNeeded(waitSuggestion(), false));
    }

    @Test
    public void waitWithEmptySlotDoesNotAskCollectForFinishedOffer() {
        AccountStatus status = memberStatus();
        StatusOfferList offers = status.getOffers();
        offers.set(0, finishedSell(0, 2199));
        // remaining slots stay EMPTY from the constructor

        assertFalse(status.isCollectNeeded(waitSuggestion(), false));
    }

    private static AccountStatus memberStatus() {
        AccountStatus status = new AccountStatus();
        status.setWorldMember(true);
        status.setAccountMember(true);
        status.setReservedSlots(0);
        return status;
    }

    private static Suggestion waitSuggestion() {
        Suggestion s = new Suggestion();
        s.setType(SuggestionType.WAIT);
        return s;
    }

    private static Offer fillingBuy(int slot, int itemId) {
        return new Offer(OfferStatus.BUY, itemId, 1000L, 100, 50_000L, 50, slot, true);
    }

    private static Offer finishedSell(int slot, int itemId) {
        return new Offer(OfferStatus.SELL, itemId, 2025L, 10, 20_250L, 10, slot, false);
    }
}

package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TradingContextTest {
    @Test void awayDoesNotPollAndReopeningInvalidatesEarlierResponses() {
        TradingContext context = new TradingContext();
        assertTrue(context.update(1L, true, true, false));
        long before = context.generation();
        assertTrue(context.accepts(before));
        assertFalse(context.update(1L, true, true, false));
        assertTrue(context.update(1L, true, false, false));
        assertFalse(context.canRequest());
        assertFalse(context.accepts(before));
        for (int i = 0; i < 100; i++) assertFalse(context.update(1L, true, false, false));
        assertTrue(context.update(1L, true, true, false));
        assertTrue(context.canRequest());
        assertFalse(context.accepts(before));
    }

    @Test void manualPauseIsNotReleasedByOpeningGe() {
        TradingContext context = new TradingContext();
        context.update(1L, true, true, false);
        long beforePause = context.generation();
        context.update(1L, true, true, true);
        context.update(1L, true, false, true);
        context.update(1L, true, true, true);
        assertFalse(context.canRequest());
        assertFalse(context.accepts(beforePause));
        context.update(1L, true, true, false);
        assertTrue(context.canRequest());
        assertFalse(context.accepts(beforePause));
    }

    @Test void accountSwitchHasIndependentPauseAndNeverAcceptsTheOtherAccountsReply() {
        TradingContext context = new TradingContext();
        context.update(1L, true, true, false);
        long firstAccount = context.generation();
        context.update(2L, true, true, true);
        assertFalse(context.canRequest());
        assertFalse(context.accepts(firstAccount));
        assertFalse(context.sameAccount(1L));
        context.update(1L, true, true, false);
        assertTrue(context.canRequest());
        assertFalse(context.accepts(firstAccount));
    }

    @Test void logoutAndReloginSameAccountStillRejectsInFlightReply() {
        TradingContext context = new TradingContext();
        context.update(1L, true, true, false);
        long previousSession = context.generation();
        context.invalidate();
        assertFalse(context.canRequest());
        assertFalse(context.sameAccount(1L));
        context.update(1L, true, true, false);
        assertFalse(context.accepts(previousSession));
        assertTrue(context.canRequest());
    }

    @Test void invalidLoginNeverRequestsEvenWithLeftoverGeWidgets() {
        TradingContext context = new TradingContext();
        context.update(1L, false, true, false);
        assertFalse(context.canRequest());
        context.update(null, true, true, false);
        assertFalse(context.canRequest());
    }
}

