package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Cancel-then-relist empties the GE slot while Set up offer is still showing
 * the item. Ghost detection must keep that modify so the side panel and price
 * highlight can reuse the buy/sell setup path.
 */
public class ModifyStepTest {

    private static final int DARK_CRAB = 11934;

    @Test
    public void editorMatchesByCurrentItemWhenSlotAlreadyCancelled() {
        int openSlot = 3;
        int staleBoxId = 0;
        assertTrue(ModifyStep.editorMatches(openSlot, DARK_CRAB, DARK_CRAB, staleBoxId));
    }

    @Test
    public void editorMatchesByOpenSlotWhenCurrentItemNotYetSet() {
        assertTrue(ModifyStep.editorMatches(3, -1, DARK_CRAB, 3));
    }

    @Test
    public void editorDoesNotMatchADifferentItemOrSlot() {
        assertFalse(ModifyStep.editorMatches(3, 4151, DARK_CRAB, 0));
        assertFalse(ModifyStep.editorMatches(-1, -1, DARK_CRAB, 3));
        assertFalse(ModifyStep.editorMatches(3, -1, 0, 3));
    }

    @Test
    public void cancelledRelistIsNotGhostWhileEditorIsOpen() {
        assertFalse(ModifyStep.isGhost(true, DARK_CRAB, true, false));
    }

    @Test
    public void modifyWithFillingOfferIsNotGhost() {
        assertFalse(ModifyStep.isGhost(true, DARK_CRAB, false, true));
    }

    @Test
    public void leftoverModifyWithEditorClosedIsGhost() {
        assertTrue(ModifyStep.isGhost(true, DARK_CRAB, false, false));
    }

    @Test
    public void buySellWaitAreNeverGhost() {
        assertFalse(ModifyStep.isGhost(false, DARK_CRAB, false, false));
        assertFalse(ModifyStep.isGhost(true, 0, false, false));
    }
}

package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;
import java.time.Instant;
import static org.junit.jupiter.api.Assertions.*;

class SuggestionRefreshCadenceTest {
    @Test void routineRefreshIsFiveSecondsWithoutClearingTheVisibleCard() {
        SuggestionManager manager = new SuggestionManager();
        Suggestion wait = new Suggestion();
        wait.setType(SuggestionType.WAIT);
        manager.setSuggestion(wait);
        Instant received = manager.getSuggestionReceivedAt();
        assertFalse(manager.suggestionOutOfDate(received.plusMillis(4999)));
        assertTrue(manager.suggestionOutOfDate(received.plusSeconds(5)));
        assertSame(wait, manager.getSuggestion());
    }

    @Test void failuresKeepTenSecondCooldown() {
        SuggestionManager manager = new SuggestionManager();
        Instant now = Instant.parse("2026-09-13T12:00:00Z");
        manager.setSuggestionReceivedAt(now);
        manager.setLastFailureAt(now);
        assertFalse(manager.suggestionOutOfDate(now.plusSeconds(9)));
        assertTrue(manager.suggestionOutOfDate(now.plusSeconds(10)));
    }
}

package com.runeassist.flip.model;

import org.junit.jupiter.api.Test;

import java.time.Instant;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Dump alerts must stay unactioned until Confirm or Skip — not only for 10s —
 * so clicking Back from a sell setup cannot replace them with a SELL of inventory.
 */
public class SuggestionDumpAlertTest {

    @Test
    public void unactionedDumpStaysActiveAfterTenSeconds() {
        Suggestion s = new Suggestion();
        s.setType(SuggestionType.BUY);
        s.setDumpAlert(true);
        s.setDumpAlertReceived(Instant.now().minusSeconds(30));
        s.actionedTick = -1;

        assertTrue(s.isRecentUnActionedDumpAlert());
    }

    @Test
    public void actionedDumpIsNotHeld() {
        Suggestion s = new Suggestion();
        s.setType(SuggestionType.BUY);
        s.setDumpAlert(true);
        s.actionedTick = 0;

        assertFalse(s.isRecentUnActionedDumpAlert());
    }

    @Test
    public void skipMarksDumpActioned() {
        Suggestion s = new Suggestion();
        s.setType(SuggestionType.BUY);
        s.setDumpAlert(true);
        s.actionedTick = -1;
        s.actionedTick = 0; // skipCurrentSuggestion

        assertFalse(s.isRecentUnActionedDumpAlert());
    }

    @Test
    public void buyDumpSuggestionRequiresBuyType() {
        Suggestion buy = new Suggestion();
        buy.setType(SuggestionType.BUY);
        buy.setDumpAlert(true);
        assertTrue(buy.isBuyDumpSuggestion());

        Suggestion sell = new Suggestion();
        sell.setType(SuggestionType.SELL);
        sell.setDumpAlert(true);
        assertFalse(sell.isBuyDumpSuggestion());
    }
}

package com.runeassist.flip.model;

import com.google.gson.Gson;
import org.junit.jupiter.api.Test;

import java.util.Collections;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class ComposeSuggestionMapperTest
{
    private final Gson gson = new Gson();

    @Test public void preservesForecastBasisAndOriginalExitWithoutInventingLegacyFields() {
        String json = "{\"ok\":true,\"suggestion\":{\"type\":\"buy\",\"expectedProfit\":21000,"
                + "\"profitEstimateBasis\":\"heuristic_net\",\"potentialProfitGp\":24000,"
                + "\"targetSellPrice\":1234,\"targetSellTaxGp\":24,\"profitModelVersion\":\"quote-net-v1\"}}";
        Suggestion suggestion = ComposeSuggestionMapper.toSuggestion(gson.fromJson(json, ComposeSuggestionResponse.class));
        assertEquals("heuristic_net", suggestion.getProfitEstimateBasis());
        assertEquals(24000.0, suggestion.getPotentialProfitGp());
        assertEquals(1234L, suggestion.getTargetSellPrice());
        assertEquals(24L, suggestion.getTargetSellTaxGp());
        assertEquals("quote-net-v1", suggestion.getProfitModelVersion());
        Suggestion legacy = ComposeSuggestionMapper.toSuggestion(gson.fromJson(
                "{\"ok\":true,\"suggestion\":{\"type\":\"buy\"}}", ComposeSuggestionResponse.class));
        assertNull(legacy.getTargetSellPrice());
        assertNull(legacy.getProfitEstimateBasis());
    }

    @Test
    public void mapsBuySuggestionFromJson()
    {
        String json = "{"
            + "\"ok\":true,"
            + "\"source\":\"ares\","
            + "\"suggestionId\":\"11111111-1111-1111-1111-111111111111\","
            + "\"suggestion\":{"
            + "\"type\":\"buy\","
            + "\"boxId\":2,"
            + "\"itemId\":4151,"
            + "\"price\":12000000,"
            + "\"quantity\":1,"
            + "\"name\":\"Abyssal whip\","
            + "\"why\":\"Buy 1 Abyssal whip at 12m\","
            + "\"expectedProfit\":50000.0,"
            + "\"expectedDuration\":600.0,"
            + "\"geLimit\":70,"
            + "\"remainingLimit\":69,"
            + "\"limitKnown\":true,"
            + "\"flags\":[\"thin\"]"
            + "}}";
        ComposeSuggestionResponse parsed = gson.fromJson(json, ComposeSuggestionResponse.class);
        Suggestion s = ComposeSuggestionMapper.toSuggestion(parsed);
        assertNotNull(s);
        assertEquals(SuggestionType.BUY, s.getType());
        assertEquals(2, s.getBoxId());
        assertEquals(4151, s.getItemId());
        assertEquals(4151, s.getId());
        assertEquals(12_000_000L, s.getPrice());
        assertEquals(1, s.getQuantity());
        assertEquals("Abyssal whip", s.getName());
        assertEquals(50_000.0, s.getExpectedProfit(), 0.01);
        assertEquals(600.0, s.getExpectedDuration(), 0.01);
        assertEquals(70, s.getGeLimit());
        assertEquals(69, s.getRemainingLimit());
        assertTrue(s.isLimitKnown());
        assertEquals(Collections.singletonList("thin"), s.getFlags());
        assertEquals("ares", s.getPickSource());
        assertEquals("11111111-1111-1111-1111-111111111111", s.getServerSuggestionId());
        assertNull(s.getGraphData());
    }

    @Test
    public void mapsBundledGraphOntoSuggestion()
    {
        String json = "{"
            + "\"ok\":true,"
            + "\"source\":\"ares\","
            + "\"suggestion\":{"
            + "\"type\":\"buy\","
            + "\"boxId\":0,"
            + "\"itemId\":4151,"
            + "\"price\":100,"
            + "\"quantity\":1,"
            + "\"name\":\"Abyssal whip\""
            + "},"
            + "\"graph\":{"
            + "\"itemId\":4151,"
            + "\"buyPrice\":90,"
            + "\"sellPrice\":110,"
            + "\"lowLatestTimes\":[1,2],"
            + "\"lowLatestPrices\":[90,91]"
            + "}"
            + "}";
        ComposeSuggestionResponse parsed = gson.fromJson(json, ComposeSuggestionResponse.class);
        Suggestion s = ComposeSuggestionMapper.toSuggestion(parsed);
        assertNotNull(s);
        assertNotNull(s.getGraphData());
        assertEquals(4151, s.getGraphData().itemId);
        assertEquals(90L, s.getGraphData().buyPrice);
        assertEquals(110L, s.getGraphData().sellPrice);
        assertNotNull(s.getGraphData().lowLatestTimes);
        assertEquals(2, s.getGraphData().lowLatestTimes.length);
    }

    @Test
    public void requestSerializesIncludeGraph()
    {
        ComposeSuggestionRequest req = new ComposeSuggestionRequest();
        req.setCapital(1_000_000L);
        req.setIncludeGraph(false);
        String json = gson.toJson(req);
        assertTrue(json.contains("\"includeGraph\":false"));
        ComposeSuggestionRequest roundTrip = gson.fromJson(json, ComposeSuggestionRequest.class);
        assertFalse(roundTrip.isIncludeGraph());
    }

    @Test
    public void requestRequiresExplicitContributionAndSerializesLinkedAccountWhenEnabled()
    {
        ComposeSuggestionRequest req = new ComposeSuggestionRequest();
        assertFalse(req.isContributeTrainingData());
        req.setContributeTrainingData(true);
        req.setOsrsAccountId("22222222-2222-2222-2222-222222222222");
        ComposeSuggestionRequest roundTrip = gson.fromJson(gson.toJson(req), ComposeSuggestionRequest.class);
        assertTrue(roundTrip.isContributeTrainingData());
        assertEquals("22222222-2222-2222-2222-222222222222", roundTrip.getOsrsAccountId());
    }

    @Test
    public void offerSnapshotSerializesSuggestionOrigin()
    {
        ComposeSuggestionRequest req = new ComposeSuggestionRequest();
        ComposeSuggestionRequest.OfferSnapshot offer = new ComposeSuggestionRequest.OfferSnapshot();
        offer.setSlot(1);
        offer.setItemId(4151);
        offer.setSuggestionId("11111111-1111-1111-1111-111111111111");
        offer.setOrigin("runeassist");
        req.getOffers().add(offer);
        String json = gson.toJson(req);
        assertTrue(json.contains("\"origin\":\"runeassist\""));
        assertTrue(json.contains("\"suggestionId\":\"11111111-1111-1111-1111-111111111111\""));
    }

    @Test
    public void acceptsModifyBuySnakeAndWait()
    {
        assertEquals(SuggestionType.MODIFY_BUY, ComposeSuggestionMapper.parseType("modify_buy"));
        assertEquals(SuggestionType.MODIFY_BUY, ComposeSuggestionMapper.parseType("MODIFY_BUY"));
        assertEquals(SuggestionType.WAIT, ComposeSuggestionMapper.parseType("wait"));
        assertNull(ComposeSuggestionMapper.parseType("nope"));
    }

    @Test
    public void rejectsUnusableResponses()
    {
        assertNull(ComposeSuggestionMapper.toSuggestion((ComposeSuggestionResponse) null));
        ComposeSuggestionResponse bad = new ComposeSuggestionResponse();
        bad.setOk(false);
        assertNull(ComposeSuggestionMapper.toSuggestion(bad));
        bad.setOk(true);
        assertNull(ComposeSuggestionMapper.toSuggestion(bad));
    }

    @Test
    public void requestSerializesDeviceIdAndTimeBasedAbortPrefs()
    {
        ComposeSuggestionRequest req = new ComposeSuggestionRequest();
        req.setClientDeviceId("dev-token-abc");
        req.setTimeBasedAbortEnabled(true);
        req.setTimeBasedAbortMinutes(30);
        String json = gson.toJson(req);
        assertTrue(json.contains("\"clientDeviceId\":\"dev-token-abc\""));
        assertTrue(json.contains("\"timeBasedAbortEnabled\":true"));
        assertTrue(json.contains("\"timeBasedAbortMinutes\":30"));
        ComposeSuggestionRequest roundTrip = gson.fromJson(json, ComposeSuggestionRequest.class);
        assertEquals("dev-token-abc", roundTrip.getClientDeviceId());
        assertTrue(roundTrip.isTimeBasedAbortEnabled());
        assertEquals(30, roundTrip.getTimeBasedAbortMinutes());
        // Defaults stay conservative.
        ComposeSuggestionRequest defaults = new ComposeSuggestionRequest();
        assertFalse(defaults.isTimeBasedAbortEnabled());
        assertEquals(15, defaults.getTimeBasedAbortMinutes());
        assertEquals("", defaults.getClientDeviceId());
    }

