package com.runeassist.flip.model;

import com.google.gson.Gson;
import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class InventoryAvailabilitySnapshotTest
{
    @Test
    void missingAndUnvalidatedInventoryAreUnknown()
    {
        Map<Integer, long[]> held = Map.of(11943, new long[]{670, 5500});
        assertFalse(InventoryAvailabilitySnapshot.from(held, null, true).isInventorySnapshotKnown());
        InventoryAvailabilitySnapshot invalid = InventoryAvailabilitySnapshot.from(held, Map.of(11943, 670L), false);
        assertFalse(invalid.isInventorySnapshotKnown());
        assertTrue(invalid.getAvailableInventory().isEmpty());
    }

    @Test
    void observedEmptyInventoryIsKnownAndDoesNotUseHistoricalStock()
    {
        InventoryAvailabilitySnapshot snapshot = InventoryAvailabilitySnapshot.from(
                Map.of(11943, new long[]{3525, 5500}), Collections.emptyMap(), true);
        assertTrue(snapshot.isInventorySnapshotKnown());
        assertTrue(snapshot.getAvailableInventory().isEmpty());
    }

    @Test
    void includesOnlyTrackedIdsAndRealPhysicalQuantities()
    {
        InventoryAvailabilitySnapshot snapshot = InventoryAvailabilitySnapshot.from(
                Map.of(11943, new long[]{3525, 5500}, 561, new long[]{100, 200}),
                Map.of(11943, 36L, 561, 500L, 995, 100000000L, 560, 900L), true);
        assertEquals(2, snapshot.getAvailableInventory().size());
        assertEquals(561, snapshot.getAvailableInventory().get(0).getItemId());
        assertEquals(500, snapshot.getAvailableInventory().get(0).getQuantity());
        assertEquals(11943, snapshot.getAvailableInventory().get(1).getItemId());
        assertEquals(36, snapshot.getAvailableInventory().get(1).getQuantity());
    }

    @Test
    void bankIsASeparateWeakerProofAndUnknownUntilSeen()
    {
        Map<Integer, long[]> held = Map.of(11943, new long[]{670, 5500}, 561, new long[]{100, 200});
        InventoryAvailabilitySnapshot unseen = InventoryAvailabilitySnapshot.from(held, Map.of(561, 100L), true, null, true);
        assertTrue(unseen.isInventorySnapshotKnown());
        assertFalse(unseen.isBankSnapshotKnown());
        assertTrue(unseen.getAvailableBank().isEmpty());
        InventoryAvailabilitySnapshot seen = InventoryAvailabilitySnapshot.from(held, Collections.emptyMap(), true,
                Map.of(11943, 670L, 995, 5000000L), true);
        assertTrue(seen.isInventorySnapshotKnown());
        assertTrue(seen.getAvailableInventory().isEmpty());
        assertTrue(seen.isBankSnapshotKnown());
        assertEquals(1, seen.getAvailableBank().size());
        assertEquals(11943, seen.getAvailableBank().get(0).getItemId());
        assertEquals(670, seen.getAvailableBank().get(0).getQuantity());
        // A bad login state hides both proofs; the three-argument form never claims a bank.
        InventoryAvailabilitySnapshot none = InventoryAvailabilitySnapshot.from(held, Map.of(561, 100L), false, Map.of(11943, 670L), false);
        assertFalse(none.isInventorySnapshotKnown());
        assertFalse(none.isBankSnapshotKnown());
        assertFalse(InventoryAvailabilitySnapshot.from(held, Map.of(561, 100L), true).isBankSnapshotKnown());
    }

    @Test
    void invalidRowsAndUntrackedStockAreExcluded()
    {
        Map<Integer, long[]> held = new HashMap<>();
        held.put(1, new long[]{1, 2});
        held.put(2, new long[]{1, 2});
        held.put(3, new long[]{0, 2});
        held.put(4, null);
        held.put(5, new long[]{});
        held.put(null, new long[]{1, 2});
        held.put(-1, new long[]{1, 2});
        InventoryAvailabilitySnapshot snapshot = InventoryAvailabilitySnapshot.from(held,
                Map.of(1, -1L, 2, (long) Integer.MAX_VALUE + 1, 3, 30L, 4, 20L, 5, 10L), true);
        assertTrue(snapshot.getAvailableInventory().isEmpty());
    }

    @Test
    void snapshotDoesNotFollowLaterInventoryMutationOrExposeUntrackedItems()
    {
        Map<Integer, Long> inventory = new HashMap<>();
        inventory.put(561, 20L);
        inventory.put(995, 1000L);
        InventoryAvailabilitySnapshot snapshot = InventoryAvailabilitySnapshot.from(
                Map.of(561, new long[]{100, 200}), inventory, true);
        inventory.put(561, 0L);
        assertEquals(20, snapshot.getAvailableInventory().get(0).getQuantity());
        assertThrows(UnsupportedOperationException.class, () -> snapshot.getAvailableInventory().clear());
        assertEquals("{\"inventorySnapshotKnown\":true,\"availableInventory\":[{\"itemId\":561,\"quantity\":20}],"
                + "\"bankSnapshotKnown\":false,\"availableBank\":[]}",
                new Gson().toJson(snapshot));
    }
}

package com.runeassist.flip;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Portfolio-panel removal via HeldCostTracker. Persistence is a no-op here (no ConfigManager),
 * so assertions cover in-memory lot state only.
 */
public class HeldCostTrackerRemoveTest {

    private static final String ACC = "Bof118";
    private static final int ANTIFIRE_4 = 2452;
    private static final int WHIP = 4151;

    @Test
    public void removeAllDropsEveryLotForThatItemOnly() {
        HeldCostTracker t = new HeldCostTracker();
        t.addManualLot(ACC, ANTIFIRE_4, 2000, 837);
        t.addManualLot(ACC, WHIP, 3, 1_500_000);

        assertEquals(2000, t.removeLots(ACC, ANTIFIRE_4, 0));

        Map<Integer, long[]> held = t.held(ACC);
        assertFalse(held.containsKey(ANTIFIRE_4));
        assertEquals(3, held.get(WHIP)[0]);
    }

    @Test
    public void removeXTakesTheOldestLotsFirstAndKeepsTheRest() {
        HeldCostTracker t = new HeldCostTracker();
        t.addManualLot(ACC, ANTIFIRE_4, 500, 800);   // oldest
        t.addManualLot(ACC, ANTIFIRE_4, 500, 900);

        assertEquals(600, t.removeLots(ACC, ANTIFIRE_4, 600));

        long[] left = t.held(ACC).get(ANTIFIRE_4);
        assertEquals(400, left[0]);
        assertEquals(900, left[1]); // the 800 lot went first, so only the 900 basis survives
    }

    @Test
    public void removingMoreThanHeldRemovesWhatIsThereAndReportsIt() {
        HeldCostTracker t = new HeldCostTracker();
        t.addManualLot(ACC, ANTIFIRE_4, 10, 800);

        assertEquals(10, t.removeLots(ACC, ANTIFIRE_4, 999));
        assertTrue(t.held(ACC).isEmpty());
        // Nothing left to remove -- must report 0 rather than a negative or stale count.
        assertEquals(0, t.removeLots(ACC, ANTIFIRE_4, 5));
    }

    @Test
    public void clearEmptiesOnlyTheCallingAccount() {
        HeldCostTracker t = new HeldCostTracker();
        t.addManualLot(ACC, ANTIFIRE_4, 2000, 837);
        t.addManualLot(ACC, WHIP, 3, 1_500_000);
        t.addManualLot("ColdTyres", WHIP, 7, 1_400_000);

        assertEquals(2003, t.clearLots(ACC));

        assertTrue(t.held(ACC).isEmpty());
        assertEquals(7, t.held("ColdTyres").get(WHIP)[0]);
    }
}

