package com.runeassist.flip.config;

import com.runeassist.flip.controller.RuneAssistPlugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.jupiter.api.Test;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class PrivacyPackagingTest {

    /**
     * Same text the hub-side descriptor ({@code plugin-hub/plugins/runeassist-flipping}) shows
     * before install. Deliberately NOT read from {@code runelite-plugin.properties} — the hub
     * packager rejects any key in that file other than displayName, author, description, tags,
     * plugins, version, build, support (see {@code Plugin.java} in plugin-hub-tooling).
     */
    // Coin stack + held cost-basis are listed because /v1/suggestion (and /v1/flips) send
    // capital and held rows on suggestion cycles with no opt-in gate -- not covered by
    // "offers" or "transactions" alone, and they reflect wealth, so they belong in the
    // text shown before install.
    private static final String HUB_WARNING_TEXT =
            "This plugin submits your coin stack size, held Grand Exchange stock with cost basis, "
                    + "grand exchange offers, grand exchange transactions, and IP address to a 3rd "
                    + "party server not controlled or verified by the RuneLite Developers.";

    private static final Set<String> ALLOWED_PROPERTIES_KEYS = new HashSet<>(Arrays.asList(
            "displayName", "author", "description", "tags", "plugins", "version", "build", "support"));

    @Test
    public void trainingContributionDefaultsOnAndCanBeDisabled() {
        RuneAssistConfig config = new RuneAssistConfig() { };
        assertTrue(config.contributeTrainingData());
    }

    @Test
    public void pluginDescriptorAndPropertiesUseStandardBuild() throws Exception {
        PluginDescriptor descriptor = RuneAssistPlugin.class.getAnnotation(PluginDescriptor.class);
        assertNotNull(descriptor);
        assertFalse(descriptor.description().toLowerCase().contains("on by default"));

        Properties properties = loadPropertiesAsPackagerWould();
        assertEquals("standard", properties.getProperty("build"));
        assertEquals("com.runeassist.flip.controller.RuneAssistPlugin", properties.getProperty("plugins"));
        assertTrue(descriptor.description().toLowerCase().contains("held-cost"));
        assertEquals(descriptor.description(), properties.getProperty("description"));
    }

    /**
     * The hub packager (plugin-hub-tooling {@code Plugin.java}) only allows displayName,
     * author, description, tags, plugins, version, build, support in this file — any other
     * key (e.g. a leftover {@code warning=}) fails the hub build.
     */
    @Test
    public void propertiesFileHasNoWarningKeyAndOnlyAllowedKeys() throws Exception {
        Properties properties = loadPropertiesAsPackagerWould();
        assertNull(properties.getProperty("warning"));
        for (String key : properties.stringPropertyNames()) {
            assertTrue(ALLOWED_PROPERTIES_KEYS.contains(key), "disallowed hub properties key: " + key);
        }
    }

    /**
     * The packager loads this file with {@code Properties.load(InputStream)}, which is
     * ISO-8859-1, not UTF-8 — any non-ASCII character (e.g. a UTF-8 "→" arrow) renders as
     * mojibake on the hub. Every value must be pure ASCII.
     */
    @Test
    public void propertiesValuesArePureAsciiForIso88591Loader() throws Exception {
        Properties properties = loadPropertiesAsPackagerWould();
        for (String key : properties.stringPropertyNames()) {
            String value = properties.getProperty(key);
            assertTrue(isPureAscii(value), key + " contains non-ASCII characters: " + value);
        }
    }

    @Test
    public void hubManifestWarningMatchesExpectedText() throws Exception {
        List<String> lines = Files.readAllLines(Paths.get("plugin-hub/plugins/runeassist-flipping"));
        String warningLine = lines.stream().filter(l -> l.startsWith("warning=")).findFirst().orElse(null);
        assertNotNull(warningLine);
        assertEquals("warning=" + HUB_WARNING_TEXT, warningLine);
        assertTrue(lines.stream().anyMatch(l -> l.startsWith("repository=https://github.com/RuneAssist/runeassist.git")));
        assertTrue(lines.stream().anyMatch(l -> l.equals("authors=RuneAssist")));
        assertTrue(lines.stream().anyMatch(l -> l.startsWith("commit=")));
    }

    private static Properties loadPropertiesAsPackagerWould() throws Exception {
        Properties properties = new Properties();
        try (java.io.InputStream in = Files.newInputStream(Paths.get("runelite-plugin.properties"))) {
            properties.load(in);
        }
        return properties;
    }

    private static boolean isPureAscii(String value) {
        return value != null && value.chars().allMatch(c -> c < 128);
    }

    @Test
    public void bsdAttributionFilesRemain() throws Exception {
        String license = Files.readString(Paths.get("LICENSE"), StandardCharsets.UTF_8);
        String third = Files.readString(Paths.get("THIRD_PARTY_LICENSES.md"), StandardCharsets.UTF_8);
        assertTrue(license.contains("BSD 2-Clause"));
        assertTrue(third.contains("Flipping Copilot"));
        assertTrue(third.contains("cbrewitt/flipping-copilot"));
    }

    @Test
    public void leftoverUpstreamHostIsAbsentFromSources() throws Exception {
        Path root = Paths.get("src");
        try (Stream<Path> files = Files.walk(root)) {
            files.filter(p -> p.toString().endsWith(".java") || p.toString().endsWith(".properties"))
                    .forEach(p -> {
                        try {
                            String text = Files.readString(p, StandardCharsets.UTF_8);
                            String host = "api.flipping" + "copilot.com";
                            assertFalse(text.contains(host),
                                    "leftover host in " + p);
                        } catch (Exception e) {
                            throw new RuntimeException(e);
                        }
                    });
        }
    }
}

package com.runeassist.flip;

import com.runeassist.flip.model.OsrsLoginManager;
import com.runeassist.flip.model.Suggestion;
import com.runeassist.flip.model.SuggestionType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import static org.junit.jupiter.api.Assertions.*;

class RuneAssistSaleInventoryTest {
    private final RuneAssistSuggestionSource source = new RuneAssistSuggestionSource();
    private final HeldCostTracker held = new HeldCostTracker();
    private Item[] items = {new Item(537, 10)};
    private boolean known = true;
    private boolean valid = true;
    private boolean loginBurst;

    @BeforeEach void setUp() throws Exception {
        ItemContainer container = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
                new Class<?>[]{ItemContainer.class}, (proxy, method, args) -> {
                    if (method.getName().equals("getItems")) return items;
                    throw new AssertionError(method.getName());
                });
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
                new Class<?>[]{Client.class}, (proxy, method, args) -> {
                    if (method.getName().equals("getItemContainer")) return known ? container : null;
                    if (method.getName().equals("getItemDefinition")) {
                        int id = (int) args[0];
                        return Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
                                new Class<?>[]{ItemComposition.class}, (definition, member, values) -> {
                                    if (member.getName().equals("getNote")) return id == 537 ? 799 : -1;
                                    if (member.getName().equals("getLinkedNoteId")) return 536;
                                    throw new AssertionError(member.getName());
                                });
                    }
                    throw new AssertionError(method.getName());
                });
        OsrsLoginManager login = new OsrsLoginManager(client) {
            @Override public boolean isValidLoginState() { return valid; }
            @Override public boolean hasJustLoggedIn() { return loginBurst; }
            @Override public String getPlayerDisplayName() { return "Account"; }
        };
        inject("client", client);
        inject("osrsLoginManager", login);
        inject("heldCostTracker", held);
        held.addManualLot("Account", 536, 10, 100);
    }

    @Test void notesAreNormalizedAndFreshPhysicalQuantityCapsTheSale() {
        assertTrue(source.hasInventoryForSale(sale(10)));
        items = new Item[]{new Item(537, 4), new Item(536, 1)};
        assertTrue(source.hasInventoryForSale(sale(5)));
        assertFalse(source.hasInventoryForSale(sale(6)));
        items = new Item[0];
        assertFalse(source.hasInventoryForSale(sale(1)), "Historical lots are not physical inventory");
    }

    @Test void unknownInventoryAndUnsettledLoginFailClosed() {
        known = false;
        assertFalse(source.hasInventoryForSale(sale(10)));
        known = true;
        loginBurst = true;
        assertFalse(source.hasInventoryForSale(sale(10)));
        loginBurst = false;
        valid = false;
        assertFalse(source.hasInventoryForSale(sale(10)));
    }

    @Test void removingTrackedStockDuringTheRequestInvalidatesTheSale() {
        assertTrue(source.hasInventoryForSale(sale(10)));
        held.removeLots("Account", 536, 6);
        assertFalse(source.hasInventoryForSale(sale(10)));
        assertTrue(source.hasInventoryForSale(sale(4)));
    }

    private Suggestion sale(int quantity) {
        Suggestion suggestion = new Suggestion();
        suggestion.setType(SuggestionType.SELL);
        suggestion.setItemId(536);
        suggestion.setQuantity(quantity);
        return suggestion;
    }

    private void inject(String name, Object value) throws Exception {
        Field field = RuneAssistSuggestionSource.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(source, value);
    }
}

package com.runeassist.flip;

import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.OsrsLoginRS;
import com.runeassist.flip.rs.PortfolioStateRS;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import org.junit.jupiter.api.Test;
import java.lang.reflect.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;
import static org.junit.jupiter.api.Assertions.*;

class SuggestionEnrichmentTest {
    @Test void coldLimitCacheNeverDownloadsAndUnknownRemainsUnknown() {
        assertEquals(0, new AresMarketClient(null, null).cachedGeLimit(536));
    }

    @Test void finalLimitStampPreservesServerEvidenceWithoutFetchingMapping() throws Exception {
        RuneAssistSuggestionSource source = new RuneAssistSuggestionSource();
        int[] localRemaining = {-1};
        set(source, "market", new AresMarketClient(null,null));
        set(source, "heldCostTracker", new HeldCostTracker() {
            @Override public synchronized int remainingLimitOrUnknown(String name, int id, int limit) { return localRemaining[0]; }
        });
        Suggestion s = new Suggestion(); s.setItemId(536); s.setGeLimit(100); s.setRemainingLimit(75); s.setLimitKnown(true);
        Method stamp = RuneAssistSuggestionSource.class.getDeclaredMethod("stampLimitFields", String.class, Suggestion.class, long[][].class);
        stamp.setAccessible(true);
        stamp.invoke(source,"synthetic",s,new long[8][]);
        assertEquals(100,s.getGeLimit()); assertEquals(75,s.getRemainingLimit()); assertTrue(s.isLimitKnown());
        localRemaining[0] = 90;
        stamp.invoke(source,"synthetic",s,new long[8][]);
        assertEquals(75,s.getRemainingLimit(),"Local observations must not widen server-known remaining limits");
        localRemaining[0] = -1;
        s.setGeLimit(0); s.setRemainingLimit(-1); s.setLimitKnown(false);
        stamp.invoke(source,"synthetic",s,new long[8][]);
        assertEquals(0,s.getGeLimit()); assertEquals(-1,s.getRemainingLimit()); assertFalse(s.isLimitKnown());
    }

    @Test void changedHoldingsOrOfferFillRejectsSlowValuationSnapshot() {
        Map<Integer,long[]> held = Map.of(536,new long[]{10,100});
        assertTrue(RuneAssistSuggestionSource.samePortfolioSnapshot(held,Map.of(536,new long[]{10,100}),new long[8][],new long[8][]));
        assertFalse(RuneAssistSuggestionSource.samePortfolioSnapshot(held,Map.of(536,new long[]{8,100}),new long[8][],new long[8][]));
        long[][] before = {{536,1,100,2,10,1}};
        long[][] after = {{536,1,100,3,10,1}};
        assertFalse(RuneAssistSuggestionSource.samePortfolioSnapshot(held,held,before,after));
    }

    @Test void optionalPortfolioIsSingleFlightSnapshotTimedAndDoesNotRunBeforeWorker() throws Exception {
        Fixture f = new Fixture();
        List<Instant> received = new ArrayList<>();
        f.source.getPortfolioItemsAsync((items,at)->received.add(at));
        Instant afterSnapshot = Instant.now();
        f.source.getPortfolioItemsAsync((items,at)->received.add(at));
        assertEquals(1,f.work.size()); assertEquals(0,f.quoteCalls); assertTrue(received.isEmpty());
        f.work.remove().run();
        assertEquals(1,f.quoteCalls); assertTrue(received.isEmpty());
        f.callbacks.remove().run();
        assertEquals(1,received.size()); assertFalse(received.get(0).isAfter(afterSnapshot));
    }

    @Test void snapshotFailureReleasesSingleFlightAndNextAttemptCanRecover() throws Exception {
        Fixture f = new Fixture(); f.throwSnapshot = true;
        f.source.getPortfolioItemsAsync((items,at)->fail("snapshot failed"));
        assertTrue(f.work.isEmpty());
        f.throwSnapshot = false;
        f.source.getPortfolioItemsAsync((items,at)->{});
        assertEquals(1,f.work.size());
    }

    @Test void changedQuantityAndDifferentAccountDiscardLatePortfolio() throws Exception {
        Fixture f = new Fixture();
        f.source.getPortfolioItemsAsync((items,at)->fail("stale quantity"));
        f.work.remove().run(); f.quantity = 9; f.callbacks.remove().run();
        set(f.source,"lastPortfolioRequestAt",0L);
        f.source.getPortfolioItemsAsync((items,at)->fail("other account"));
        f.work.remove().run(); f.account = 2; f.callbacks.remove().run();
    }

    @Test void olderPortfolioSnapshotCannotOverwriteNewerValuationAndGuardRunsWhenQueued() throws Exception {
        Queue<BooleanSupplier> callbacks = new ArrayDeque<>();
        ClientThread thread = new ClientThread() {
            @Override public void invokeLater(BooleanSupplier action) { callbacks.add(action); }
        };
        PortfolioStateRS state = new PortfolioStateRS(new OsrsLoginRS(),null,null,thread,null);
        Instant newer = Instant.now();
        set(state,"portfolioItemsServerTime",newer);
        // Null dependencies are deliberate: a rejected update must not reach state-building.
        state.updatePortfolioState(null,Collections.emptyList(),null,null,newer.minusSeconds(12),()->true);
        assertTrue(callbacks.remove().getAsBoolean());
        boolean[] current = {true};
        state.updatePortfolioState(null,Collections.emptyList(),null,null,newer.plusSeconds(1),()->current[0]);
        current[0] = false;
        assertTrue(callbacks.remove().getAsBoolean());
    }

    private static void set(Object object,String name,Object value) throws Exception {
        Field field = object.getClass().getDeclaredField(name); field.setAccessible(true); field.set(object,value);
    }

    private static class Fixture {
        final RuneAssistSuggestionSource source = new RuneAssistSuggestionSource();
        final Queue<Runnable> work = new ArrayDeque<>(), callbacks = new ArrayDeque<>();
        int quoteCalls, quantity = 10;
        long account = 1;
        boolean throwSnapshot;
        Fixture() throws Exception {
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),new Class<?>[]{Client.class},(p,m,a)->{
                if (m.getName().equals("getAccountHash")) return account;
                if (m.getName().equals("getGrandExchangeOffers")) return null;
                throw new AssertionError(m.getName());
            });
            set(source,"client",client);
            set(source,"osrsLoginManager",new OsrsLoginManager(client) {
                @Override public boolean isValidLoginState() { return true; }
                @Override public String getPlayerDisplayName() { return "synthetic"; }
            });
            set(source,"heldCostTracker",new HeldCostTracker() {
                @Override public synchronized Map<Integer,long[]> held(String name) {
                    if (throwSnapshot) throw new IllegalStateException("synthetic snapshot failure");
                    return Map.of(536,new long[]{quantity,100});
                }
            });
            set(source,"market",new AresMarketClient(null,null) {
                @Override public Map<Integer,Map<String,Object>> quotes(Collection<Integer> ids) {
                    quoteCalls++; return Map.of(536,Map.of("sell_at",120,"tax_at_sell",2));
                }
            });
            set(source,"clientThread",new ClientThread() {
