package com.runeassist.flip.controller;

import com.runeassist.flip.model.OfferStatus;
import com.runeassist.flip.model.SavedOffer;
import com.runeassist.flip.model.Transaction;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Instant same-tick sells often report quantitySold without spent (GE tax item
 * sink / client lag). The fill inferrer must still book the flip.
 */
public class GrandExchangeOfferEventHandlerTest {

    @Test
    public void emptyToSoldWithZeroSpentUsesPriceTimesQty() {
        SavedOffer prev = offer(GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
        SavedOffer sold = offer(GrandExchangeOfferState.SOLD, 4151, 100, 100, 1200, 0);

        Transaction t = GrandExchangeOfferEventHandler.inferFill(3, sold, prev, true, false);

        assertNotNull(t);
        assertEquals(OfferStatus.SELL, t.getType());
        assertEquals(4151, t.getItemId());
        assertEquals(100, t.getQuantity());
        assertEquals(1200L * 100, t.getAmountSpent());
        assertEquals(3, t.getBoxId());
    }

    @Test
    public void sellingToSoldWithZeroSpentStillRecords() {
        SavedOffer prev = offer(GrandExchangeOfferState.SELLING, 4151, 0, 100, 1200, 0);
        SavedOffer sold = offer(GrandExchangeOfferState.SOLD, 4151, 100, 100, 1200, 0);

        Transaction t = GrandExchangeOfferEventHandler.inferFill(0, sold, prev, true, false);

        assertNotNull(t);
        assertEquals(100, t.getQuantity());
        assertEquals(1200L * 100, t.getAmountSpent());
    }

    @Test
    public void partialFillUsesActualSpentDelta() {
        SavedOffer prev = offer(GrandExchangeOfferState.SELLING, 4151, 10, 100, 1200, 11_760);
        SavedOffer next = offer(GrandExchangeOfferState.SELLING, 4151, 20, 100, 1200, 23_520);

        Transaction t = GrandExchangeOfferEventHandler.inferFill(1, next, prev, true, false);

        assertNotNull(t);
        assertEquals(10, t.getQuantity());
        assertEquals(11_760L, t.getAmountSpent());
    }

    @Test
    public void fillKeepsServerSuggestionAttribution() {
        SavedOffer prev = offer(GrandExchangeOfferState.BUYING, 4151, 0, 1, 100, 0);
        prev.setRuneAssistSuggestion(true);
        prev.setSuggestionId("11111111-1111-1111-1111-111111111111");
        SavedOffer bought = offer(GrandExchangeOfferState.BOUGHT, 4151, 1, 1, 100, 100);
        bought.setRuneAssistSuggestion(true);
        bought.setSuggestionId(prev.getSuggestionId());

        Transaction t = GrandExchangeOfferEventHandler.inferFill(0, bought, prev, true, false);
        assertNotNull(t);
        assertTrue(t.isRuneAssistSuggestion());
        assertEquals(prev.getSuggestionId(), t.getSuggestionId());
    }

    @Test
    public void noQuantityIncreaseIsNotAFill() {
        SavedOffer prev = offer(GrandExchangeOfferState.SELLING, 4151, 50, 100, 1200, 60_000);
        SavedOffer next = offer(GrandExchangeOfferState.SELLING, 4151, 50, 100, 1200, 60_000);

        assertNull(GrandExchangeOfferEventHandler.inferFill(1, next, prev, true, false));
    }

    private static SavedOffer offer(GrandExchangeOfferState state, int itemId, int sold, int total,
                                    long price, long spent) {
        SavedOffer o = new SavedOffer();
        o.setState(state);
        o.setItemId(itemId);
        o.setQuantitySold(sold);
        o.setTotalQuantity(total);
        o.setPrice(price);
        o.setSpent(spent);
        return o;
    }
}

package com.runeassist.flip.controller;

import com.google.gson.*;
import com.runeassist.flip.HeldCostTracker;
import com.runeassist.flip.controller.history.AccountHttp;
import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.AccountLoginRS;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class LinkedHistoryLoadingTest {
    static class Api extends AccountHttp {
        List<String> requests = new ArrayList<>();
        boolean failSecond;
        String user = "owner-one";
        Api() { super(null, null, null); }
        @Override public String userId() { return user; }
        @Override public JsonObject get(String path, boolean authed) {
            assertTrue(authed);
            requests.add(path);
            if (path.equals("/v1/account/me")) return JsonParser.parseString(
                    "{\"osrsAccounts\":[{\"id\":\"one\",\"displayName\":\"Test Alpha\"},{\"id\":\"two\",\"displayName\":\"Test Beta\"}]}").getAsJsonObject();
            boolean second = path.contains("osrsAccountId=two");
            if (second && failSecond) return null;
            JsonObject body = new JsonObject();
            body.addProperty("time", 200);
            JsonArray flips = new JsonArray();
            if (!path.contains("sinceUpdatedTime")) {
                JsonObject flip = JsonParser.parseString("{\"id\":\"00000000-0000-0000-0000-00000000000" + (second ? "2" : "1")
                        + "\",\"itemId\":4151,\"openedTime\":100,\"closedTime\":200,\"openedQuantity\":1,\"closedQuantity\":1,\"spent\":100,\"profit\":20,\"status\":\"FINISHED\",\"portfolioId\":1,\"updatedTime\":200}").getAsJsonObject();
                flips.add(flip);
            }
            body.add("flips", flips);
            return body;
        }
    }

    private FlipHistorySyncService service(Api api, FlipManager manager, AccountLoginRS accounts) throws Exception {
        FlipHistorySyncService service = new FlipHistorySyncService(api, null, manager,
                new OsrsLoginManager(null) { @Override public String getPlayerDisplayName() { return null; } },
                new HeldCostTracker(), new SuggestionManager(), null, null) {
            @Override public List<Transaction> listUnacked(String name) { return Collections.emptyList(); }
        };
        java.lang.reflect.Field field = FlipHistorySyncService.class.getDeclaredField("accountLoginRS");
        field.setAccessible(true);
        field.set(service, accounts);
        return service;
    }

    @Test void startupLoadsEveryAccountThenUsesDeltasAndRestartReloadsHistory() throws Exception {
        Api api = new Api();
        FlipManager manager = new FlipManager(null);
        AccountLoginRS accounts = new AccountLoginRS();
        FlipHistorySyncService service = service(api, manager, accounts);
        service.syncLinkedAccounts();
        assertEquals(2, accounts.get().displayNameToAccountId.size());
        assertEquals(2, manager.getRealizedIntervalStats().flipsMade);
        assertTrue(service.isHistoryReady(null));
        assertEquals("Test Beta", service.displayNameForAccount(FlipHistorySyncService.accountIdFor("Test Beta")));
        assertFalse(api.requests.stream().anyMatch(p -> p.contains("sinceUpdatedTime")));
        api.requests.clear();
        service.syncLinkedAccounts();
        assertEquals(2, api.requests.size());
        assertTrue(api.requests.stream().allMatch(p -> p.contains("sinceUpdatedTime=200")));
        assertEquals(2, manager.getRealizedIntervalStats().flipsMade, "Deltas must not duplicate history");
        api.requests.clear();
        FlipManager restarted = new FlipManager(null);
        service(api, restarted, new AccountLoginRS()).syncLinkedAccounts();
        assertFalse(api.requests.stream().anyMatch(p -> p.contains("sinceUpdatedTime")));
        assertEquals(2, restarted.getRealizedIntervalStats().flipsMade);
    }

    @Test void failedAccountDoesNotBecomeAFalseZeroOrAdvanceItsCursor() throws Exception {
        Api api = new Api();
        api.failSecond = true;
        FlipManager manager = new FlipManager(null);
        FlipHistorySyncService service = service(api, manager, new AccountLoginRS());
        service.syncLinkedAccounts();
        assertFalse(service.isHistoryReady(null));
        assertTrue(service.isHistoryReady(FlipHistorySyncService.accountIdFor("Test Alpha")));
        assertFalse(service.isHistoryReady(FlipHistorySyncService.accountIdFor("Test Beta")));
        api.failSecond = false;
        api.requests.clear();
        service.syncLinkedAccounts();
        assertTrue(api.requests.contains("/v1/account/client-flips-delta?osrsAccountId=two"));
        assertTrue(service.isHistoryReady(null));
    }

    @Test void pairingToAnotherUserDiscardsOldCursorsAndHistory() throws Exception {
        Api api = new Api();
        FlipManager manager = new FlipManager(null);
        FlipHistorySyncService service = service(api, manager, new AccountLoginRS());
        service.syncLinkedAccounts();
        api.user = "owner-two";
        api.requests.clear();
        service.syncLinkedAccounts();
        assertFalse(api.requests.stream().anyMatch(p -> p.contains("sinceUpdatedTime")));
        assertEquals(2, manager.getRealizedIntervalStats().flipsMade);
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.HeldCostTracker;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class HeldOfferObservationContextTest {
    @Test void teardownAndLoginBurstEmptyCannotEraseCountersOrReplayFilledQuantity() {
        HeldCostTracker tracker = new HeldCostTracker();
        tracker.onOffer("Account", 0, GrandExchangeOfferState.BOUGHT, 536, 100, 10, 10, 1000);
        for (GameState state : new GameState[]{GameState.HOPPING, GameState.LOGIN_SCREEN,
                GameState.LOGGING_IN, GameState.CONNECTION_LOST}) {
            boolean observe = RuneAssistPlugin.shouldObserveHeldOffer("Account", state,
                    GrandExchangeOfferState.EMPTY, false, true);
            assertFalse(observe);
            if (observe) tracker.onOffer("Account", 0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
            tracker.onOffer("Account", 0, GrandExchangeOfferState.BOUGHT, 536, 100, 10, 10, 1000);
            assertEquals(10, tracker.held("Account").get(536)[0]);
        }
        assertFalse(RuneAssistPlugin.shouldObserveHeldOffer("Account", GameState.LOGGED_IN,
                GrandExchangeOfferState.EMPTY, true, true));
        assertTrue(RuneAssistPlugin.shouldObserveHeldOffer("Account", GameState.LOGGED_IN,
                GrandExchangeOfferState.EMPTY, true, false));
    }

    @Test void realLoginFillsRemainEligibleButAnonymousStateDoesNot() {
        assertTrue(RuneAssistPlugin.shouldObserveHeldOffer("Account", GameState.LOGGED_IN,
                GrandExchangeOfferState.BOUGHT, true, true));
        assertTrue(RuneAssistPlugin.shouldObserveHeldOffer("Account", GameState.LOGGING_IN,
                GrandExchangeOfferState.BUYING, false, true));
        assertFalse(RuneAssistPlugin.shouldObserveHeldOffer(null, GameState.LOGGED_IN,
                GrandExchangeOfferState.BOUGHT, true, false));
        assertFalse(RuneAssistPlugin.shouldObserveHeldOffer(" ", GameState.LOGGED_IN,
                GrandExchangeOfferState.BOUGHT, true, false));
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.BankState;
