import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Local Bank Tags portfolio membership — items that are both in the portfolio bank
 * quantity and present in the observed bank snapshot.
 */
public class PortfolioBankTagControllerTest {

    private static final int WHIP = 4151;
    private static final int ANTIFIRE = 2452;

    @Test
    public void selectsOnlyBankedPortfolioItems() {
        Map<Integer, PortfolioItemCardData> cards = new HashMap<>();
        // portfolio qty 10, none on GE/inv, suggestion bank 10 → banked
        cards.put(WHIP, card(WHIP, /*ge*/0, /*inv*/0, /*sugBank*/10, /*portfolio*/10));
        // portfolio qty all on GE → not banked
        cards.put(ANTIFIRE, card(ANTIFIRE, /*ge*/50, /*inv*/0, /*sugBank*/0, /*portfolio*/50));

        Map<Integer, Integer> bank = new HashMap<>();
        bank.put(WHIP, 10);
        bank.put(ANTIFIRE, 50);

        Set<Integer> selected = PortfolioBankTagController.selectBankedPortfolioItemIds(
                new PortfolioState(true, cards, emptySummary()),
                new BankState(true, bank, 1L),
                id -> id);

        assertEquals(Collections.singleton(WHIP), selected);
    }

    @Test
    public void emptyWhenBankOrPortfolioNotLoaded() {
        assertTrue(PortfolioBankTagController.selectBankedPortfolioItemIds(
                PortfolioState.empty(),
                new BankState(true, Collections.singletonMap(WHIP, 1), 1L),
                id -> id).isEmpty());

        assertTrue(PortfolioBankTagController.selectBankedPortfolioItemIds(
                new PortfolioState(true, Collections.emptyMap(), emptySummary()),
                BankState.empty(),
                id -> id).isEmpty());
    }

    @Test
    public void excludesPortfolioItemMissingFromBankSnapshot() {
        Map<Integer, PortfolioItemCardData> cards = new HashMap<>();
        cards.put(WHIP, card(WHIP, 0, 0, 5, 5));

        Set<Integer> selected = PortfolioBankTagController.selectBankedPortfolioItemIds(
                new PortfolioState(true, cards, emptySummary()),
                new BankState(true, Collections.emptyMap(), 1L),
                id -> id);

        assertTrue(selected.isEmpty());
    }

    private static PortfolioItemCardData card(int itemId, int ge, int inv, int sugBank, int portfolio) {
        return new PortfolioItemCardData(
                itemId,
                "item-" + itemId,
                ge,
                inv,
                sugBank,
                /*openFlips*/0,
                /*postTaxSell*/100,
                /*unitBuy*/90,
                /*unrealized*/10L,
                /*heldMinutes*/0,
                portfolio);
    }

    private static PortfolioSummaryData emptySummary() {
        return new PortfolioSummaryData(0L, 0L, 0L, 0L, 0L);
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.*;
import com.runeassist.flip.ui.flipsdialog.FlipsDialogController;
import com.runeassist.flip.ui.graph.model.Data;
import com.runeassist.flip.rs.OsrsLoginRS;
import com.runeassist.flip.rs.PortfolioStateRS;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import javax.swing.SwingUtilities;
import java.lang.reflect.Proxy;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.util.function.BooleanSupplier;
import java.time.Instant;
import static org.junit.jupiter.api.Assertions.*;

class SuggestionLatencyTest {
    private final SuggestionManager manager = new SuggestionManager();
    private final List<GraphRequest> graphs = new ArrayList<>();
    private final Queue<Runnable> clientCallbacks = new ArrayDeque<>();
    private SuggestionController controller;
    private long account = 1L;
    private boolean geOpen = true;
    private int requests;
    private int portfolioUpdates;
    private Instant portfolioSnapshotAt;

    @BeforeEach void setUp() {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (p,m,a) -> {
                if (m.getName().equals("getAccountHash")) return account;
                if (m.getName().equals("getTickCount")) return 100;
                if (m.getName().equals("getGrandExchangeOffers")) return new GrandExchangeOffer[8];
                throw new AssertionError(m.getName());
            });
        OsrsLoginManager login = new OsrsLoginManager(client) {
            @Override public boolean isValidLoginState() { return true; }
            @Override public boolean hasJustLoggedIn() { return false; }
        };
        GrandExchange ge = new GrandExchange(client) {
            @Override public boolean isOpen() { return geOpen; }
            @Override public boolean isSlotOpen() { return false; }
            @Override boolean isHomeScreenOpen() { return false; }
        };
        AccountStatusManager status = new AccountStatusManager(null,null,null,null,null,null,null,null,null,null,null,null) {
            @Override public AccountStatus getAccountStatus() { return new AccountStatus(); }
        };
        PausedManager paused = new PausedManager(login, null) {
            @Override public boolean isPaused() { return false; }
        };
        HighlightController highlights = new HighlightController(null,null,null,null,null,null,null,null,null,null,null,null) {
            @Override public void removeAll() { }
        };
        ApiRequestHandler api = new ApiRequestHandler(null, null) {
            @Override public Call asyncGetRuneAssistGraph(int itemId, Consumer<Data> onData, Consumer<Throwable> onError) {
                GraphRequest request = new GraphRequest(onData);
                graphs.add(request);
                return request.call;
            }
        };
        ClientThread thread = new ClientThread() {
            @Override public void invokeLater(Runnable runnable) { clientCallbacks.add(runnable); }
        };
        FlipsDialogController dialogs = new FlipsDialogController(null,null,null,null,null,null,null,null,null,null,null,null);
        PortfolioStateRS portfolio = new PortfolioStateRS(new OsrsLoginRS(),null,null,thread,status) {
            @Override public void updatePortfolioState(Map<Integer,Integer> bank, List<Suggestion.PortfolioItem> items,
                    StatusOfferList offers, Map<Integer,Long> uncollected, Instant at, BooleanSupplier stillCurrent) {
                if (stillCurrent.getAsBoolean()) { portfolioUpdates++; portfolioSnapshotAt = at; }
            }
        };
        controller = new SuggestionController(paused,client,null,login,highlights,ge,null,null,null,thread,null,manager,
                status,new GrandExchangeUncollectedManager(client),portfolio,dialogs,null,null,api,null) {
            @Override public void getSuggestionAsync() {
                requests++;
                manager.setSuggestionNeeded(false);
                manager.setSuggestionRequestInProgress(true);
            }
        };
        controller.syncTradingContext();
    }

    @Test void pendingGraphDoesNotBlockRefreshOrAllowOverlappingComposeRequests() {
        manager.setGraphDataReadingInProgress(true);
        manager.setSuggestionNeeded(true);
        for (int i=0; i<100; i++) controller.onGameTick();
        assertEquals(1, requests);
        assertTrue(manager.isSuggestionRequestInProgress());
    }

    @Test void repeatedSameItemRefreshSharesPendingGraphAndCachesCompletion() throws Exception {
        Suggestion first = suggestion(536);
        manager.setSuggestion(first);
        controller.feedSuggestionGraph(first, true);
        Suggestion refreshed = suggestion(536);
        manager.setSuggestion(refreshed);
        controller.feedSuggestionGraph(refreshed, true);
        assertEquals(1, graphs.size());
        assertFalse(graphs.get(0).cancelled);
        graphs.get(0).complete.accept(new Data());
        drain();
        assertFalse(manager.isGraphDataReadingInProgress());
        controller.feedSuggestionGraph(refreshed, true);
        assertEquals(1, graphs.size());
    }

    @Test void changedItemCancelsOldGraphAndLateCallbackCannotReleaseNewGraph() throws Exception {
        manager.setSuggestion(suggestion(536));
        controller.feedSuggestionGraph(manager.getSuggestion(), true);
        manager.setSuggestion(suggestion(397));
        controller.feedSuggestionGraph(manager.getSuggestion(), true);
        assertTrue(graphs.get(0).cancelled);
        graphs.get(0).complete.accept(new Data());
        drain();
        assertTrue(manager.isGraphDataReadingInProgress());
        graphs.get(1).complete.accept(new Data());
        drain();
        assertFalse(manager.isGraphDataReadingInProgress());
    }

    @Test void contextChangeCancelsGraphAndRejectsPortfolioCallbackBeforeStateAccess() throws Exception {
        Suggestion old = suggestion(536);
        manager.setSuggestion(old);
        controller.feedSuggestionGraph(old, true);
        long generation = controller.getTradingContext().generation();
        account = 2L;
        controller.syncTradingContext();
        assertTrue(graphs.get(0).cancelled);
        graphs.get(0).complete.accept(new Data());
        controller.receivePortfolioForContext(generation, old, Collections.emptyList(), Instant.now());
        drain();
        assertNull(manager.getSuggestion());
        assertFalse(manager.isGraphDataReadingInProgress());
        assertEquals(0, portfolioUpdates);
    }

    @Test void slowPortfolioSurvivesRoutineSameAccountCardRefreshAndKeepsSnapshotTime() {
        Suggestion old = suggestion(536);
        Instant snapshotAt = Instant.now().minusSeconds(12);
        manager.setSuggestion(suggestion(397));
        controller.receivePortfolioForContext(controller.getTradingContext().generation(), old, Collections.emptyList(), snapshotAt);
        assertEquals(397, manager.getSuggestion().getItemId());
        assertEquals(1, portfolioUpdates);
        assertEquals(snapshotAt, portfolioSnapshotAt);
    }

    @Test void lowDataModeNeverFetchesGraphAndCancelsOptionalPendingWork() {
        manager.setSuggestion(suggestion(536));
        controller.feedSuggestionGraph(manager.getSuggestion(), true);
        controller.feedSuggestionGraph(manager.getSuggestion(), false);
        assertTrue(graphs.get(0).cancelled);
        assertFalse(manager.isGraphDataReadingInProgress());
        assertEquals(1, graphs.size());
    }

    @Test void dedicatedComposeWorkerIsSerialAndQueueIsBounded() throws Exception {
        ExecutorService executor = new RuneAssistPlugin().provideSuggestionExecutor();
        CountDownLatch started = new CountDownLatch(1), release = new CountDownLatch(1), queued = new CountDownLatch(1);
        try {
            executor.execute(() -> {
                started.countDown();
                try { release.await(5, TimeUnit.SECONDS); } catch (InterruptedException e) { throw new IllegalStateException(e); }
            });
            assertTrue(started.await(2, TimeUnit.SECONDS));
            executor.execute(queued::countDown);
            assertThrows(RejectedExecutionException.class, () -> executor.execute(() -> {}));
            assertEquals(1L, queued.getCount());
            release.countDown();
            assertTrue(queued.await(2, TimeUnit.SECONDS));
        } finally { release.countDown(); executor.shutdown(); }
    }

    @Test void sameSingletonWorkerCanBeDisabledAndReenabled() throws Exception {
        com.runeassist.flip.SuggestionTaskExecutor executor = new RuneAssistPlugin().provideSuggestionExecutor();
        try {
            executor.submit(() -> {}).get(2, TimeUnit.SECONDS);
            executor.shutdown();
            assertThrows(RejectedExecutionException.class, () -> executor.execute(() -> {}));
            assertTrue(executor.awaitTermination(2, TimeUnit.SECONDS));
            executor.start();
            executor.submit(() -> {}).get(2, TimeUnit.SECONDS);
            assertFalse(executor.isShutdown());
        } finally { executor.shutdown(); }
    }

    @Test void quickReenableDoesNotOverlapAnOldRequestStillFinishing() throws Exception {
        com.runeassist.flip.SuggestionTaskExecutor executor = new RuneAssistPlugin().provideSuggestionExecutor();
        CountDownLatch started = new CountDownLatch(1), release = new CountDownLatch(1), next = new CountDownLatch(1);
        try {
            executor.execute(() -> {
                started.countDown();
                boolean done = false;
                while (!done) {
                    try { done = release.await(2, TimeUnit.SECONDS); }
                    catch (InterruptedException ignored) { /* Model a call completing after cancellation. */ }
                }
            });
            assertTrue(started.await(2, TimeUnit.SECONDS));
            executor.shutdown();
            executor.start();
            executor.execute(next::countDown);
            assertFalse(next.await(50, TimeUnit.MILLISECONDS));
            release.countDown();
            assertTrue(next.await(2, TimeUnit.SECONDS));
        } finally { release.countDown(); executor.shutdown(); }
    }

    private void drain() throws Exception {
        while (!clientCallbacks.isEmpty()) clientCallbacks.remove().run();
        SwingUtilities.invokeAndWait(() -> {});
    }
    private static Suggestion suggestion(int itemId) {
        Suggestion s = new Suggestion(); s.setType(SuggestionType.BUY); s.setItemId(itemId); return s;
    }
    private static class GraphRequest {
        final Consumer<Data> complete;
        final Call call;
        boolean cancelled;
        GraphRequest(Consumer<Data> complete) {
            this.complete = complete;
            call = (Call) Proxy.newProxyInstance(Call.class.getClassLoader(), new Class<?>[]{Call.class}, (p,m,a) -> {
                if (m.getName().equals("cancel")) { cancelled = true; return null; }
                if (m.getName().equals("isCanceled")) return cancelled;
                throw new AssertionError(m.getName());
            });
        }
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.RuneAssistSuggestionSource;
import com.runeassist.flip.model.*;
import net.runelite.api.Client;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class SuggestionTradingContextTest {
    private long account = 1L;
    private boolean loggedIn = true;
    private boolean geOpen = true;
    private int clearHighlights;
    private boolean physicalStock = true;
    private boolean fillingSell;
    private boolean setupOpen;
    private final Map<Integer, Long> uncollectedStock = new HashMap<>();
    private final Map<Long, Boolean> pauses = new HashMap<>();
    private final SuggestionManager suggestions = new SuggestionManager();
    private SuggestionController controller;

    @BeforeEach void setUp() {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
                new Class<?>[]{Client.class}, (proxy, method, args) -> {
                    if (method.getName().equals("getAccountHash")) return account;
                    throw new AssertionError("Unexpected client call: " + method.getName());
                });
        OsrsLoginManager login = new OsrsLoginManager(client) {
            @Override public boolean isValidLoginState() { return loggedIn; }
        };
        GrandExchange ge = new GrandExchange(client) {
            @Override public boolean isOpen() { return geOpen; }
            @Override boolean hasFillingSellOffer(int itemId) { return fillingSell; }
            @Override public boolean isSetupOfferOpen() { return setupOpen; }
        };
        GrandExchangeUncollectedManager uncollected = new GrandExchangeUncollectedManager(client) {
            @Override public synchronized Map<Integer, Long> loadAllUncollected(Long accountHash) {
                return uncollectedStock;
            }
        };
        PausedManager paused = new PausedManager(login, null) {
            @Override public boolean isPaused() { return pauses.getOrDefault(account, false); }
        };
        HighlightController highlights = new HighlightController(null, null, null, null,
                null, null, null, null, null, null, null, null) {
            @Override public void removeAll() { clearHighlights++; }
        };
        RuneAssistSuggestionSource source = new RuneAssistSuggestionSource() {
            @Override public boolean hasInventoryForSale(Suggestion suggestion) { return physicalStock; }
        };
        controller = new SuggestionController(paused, client, null, login, highlights, ge,
                null, null, null, null, null, suggestions, null, uncollected,
                null, null, null, source, null, null);
        controller.syncTradingContext();
        clearHighlights = 0;
    }

    @Test void leavingGeClearsActionAndPollingFlagsWithoutRepeatedUiChurn() {
        suggestions.setSuggestion(suggestion(SuggestionType.ABORT));
        suggestions.setSuggestionRequestInProgress(true);
        suggestions.setGraphDataReadingInProgress(true);
        suggestions.setSuggestionRefreshPending(true);
        geOpen = false;
        for (int i = 0; i < 100; i++) controller.onGameTick();
        assertNull(suggestions.getSuggestion());
        assertFalse(suggestions.isSuggestionRequestInProgress());
        assertFalse(suggestions.isGraphDataReadingInProgress());
        assertFalse(suggestions.isSuggestionRefreshPending());
        assertFalse(suggestions.isSuggestionNeeded());
        assertEquals(1, clearHighlights);
        // Direct refreshes (preferences/skip/plugin changes) must also stay quiet.
        controller.getSuggestionAsync();
        assertFalse(suggestions.isSuggestionRequestInProgress());
    }

    @Test void returningStartsFreshAndLateResponseCannotReleaseTheNewRequest() {
        long oldGeneration = controller.getTradingContext().generation();
        geOpen = false;
        controller.syncTradingContext();
        geOpen = true;
        assertTrue(controller.syncTradingContext());
        assertTrue(suggestions.isSuggestionNeeded());
        Suggestion current = suggestion(SuggestionType.WAIT);
        suggestions.setSuggestion(current);
        suggestions.setSuggestionRequestInProgress(true);
        controller.receiveForContext(oldGeneration, null, suggestion(SuggestionType.ABORT), null, true);
        assertSame(current, suggestions.getSuggestion());
        assertTrue(suggestions.isSuggestionRequestInProgress());
    }

    @Test void lateOldAccountResponseDoesNotTouchTheNewAccountsState() {
        long oldGeneration = controller.getTradingContext().generation();
        account = 2L;
        controller.syncTradingContext();
        Suggestion current = suggestion(SuggestionType.WAIT);
        suggestions.setSuggestion(current);
        suggestions.setSuggestionRequestInProgress(true);
        controller.receiveForContext(oldGeneration, null, suggestion(SuggestionType.ABORT), null, false);
        assertSame(current, suggestions.getSuggestion());
        assertTrue(suggestions.isSuggestionRequestInProgress());
    }

    @Test void logoutInvalidatesRequestsEvenWhenSameAccountReturns() {
        long oldGeneration = controller.getTradingContext().generation();
        suggestions.setSuggestionRequestInProgress(true);
        controller.onSessionEnded();
        assertFalse(suggestions.isSuggestionRequestInProgress());
        controller.syncTradingContext();
        controller.receiveForContext(oldGeneration, null, suggestion(SuggestionType.ABORT), null, false);
        assertNull(suggestions.getSuggestion());
    }

    @Test void pausedAccountStaysPausedOnGeReopenAndOtherAccountCanTrade() {
        pauses.put(1L, true);
        assertFalse(controller.syncTradingContext());
        geOpen = false;
        controller.syncTradingContext();
        geOpen = true;
        assertFalse(controller.syncTradingContext());
        account = 2L;
        assertTrue(controller.syncTradingContext());
        account = 1L;
        assertFalse(controller.syncTradingContext());
        assertTrue(pauses.get(1L));
    }

    @Test void manualPauseDiscardsPendingRepliesAndDumpAlerts() {
        long oldGeneration = controller.getTradingContext().generation();
        suggestions.setSuggestionRequestInProgress(true);
        pauses.put(1L, true);
        controller.receiveForContext(oldGeneration, null, suggestion(SuggestionType.BUY), null, true);
        Suggestion dump = suggestion(SuggestionType.BUY);
        dump.isDumpAlert = true;
        controller.handleDumpSuggestion(dump);
        assertNull(suggestions.getSuggestion());
        assertFalse(suggestions.isSuggestionRequestInProgress());
    }

    @Test void missingPhysicalSellStockNeverReachesUiOrNotificationSideEffects() {
        physicalStock = false;
        suggestions.setSuggestionRequestInProgress(true);
        controller.receiveForContext(controller.getTradingContext().generation(), null,
                suggestion(SuggestionType.SELL), null, true);
        assertTrue(suggestions.getSuggestion().isWaitSuggestion());
        assertFalse(suggestions.isSuggestionRequestInProgress());
        assertFalse(suggestions.isGraphDataReadingInProgress());
        assertFalse(suggestions.isSuggestionNeeded(), "Use normal refresh cadence instead of retrying every tick");
    }

    @Test void queuedDumpFromOldStreamCannotCrossAccountsOrReopenedGe() {
        long generation = controller.getTradingContext().generation();
        account = 2L;
        controller.handleDumpSuggestion(suggestion(SuggestionType.BUY), generation);
        assertNull(suggestions.getSuggestion());
        assertTrue(suggestions.isSuggestionNeeded());
        generation = controller.getTradingContext().generation();
        geOpen = false;
        controller.syncTradingContext();
        geOpen = true;
        controller.handleDumpSuggestion(suggestion(SuggestionType.BUY), generation);
        assertNull(suggestions.getSuggestion());
    }

    @Test void localDecantInstructionSurvivesLeavingGeButNotSwitchingAccounts() {
        Suggestion decant = suggestion(SuggestionType.DECANT);
        suggestions.setSuggestion(decant);
        geOpen = false;
        assertFalse(controller.syncTradingContext());
        assertSame(decant, suggestions.getSuggestion());
        assertFalse(suggestions.isSuggestionNeeded());
        account = 2L;
        controller.syncTradingContext();
        assertNull(suggestions.getSuggestion());
    }

    @Test void modifySellMayCancelAndCollectButCannotRelistMissingStock() {
        Suggestion modify = suggestion(SuggestionType.MODIFY_SELL);
        physicalStock = false;
        fillingSell = true;
        assertTrue(controller.isSellAvailableNow(modify));
        fillingSell = false;
        uncollectedStock.put(536, 10L);
        assertTrue(controller.isSellAvailableNow(modify));
        setupOpen = true;
        assertFalse(controller.isSellAvailableNow(modify));
        uncollectedStock.clear();
        assertFalse(controller.isSellAvailableNow(modify));
        physicalStock = true;
        assertTrue(controller.isSellAvailableNow(modify));
        physicalStock = false;
        fillingSell = true;
        assertFalse(controller.isSellAvailableNow(suggestion(SuggestionType.SELL)),
                "An ordinary new sale cannot reuse stock already listed elsewhere");
    }

    private static Suggestion suggestion(SuggestionType type) {
        Suggestion suggestion = new Suggestion();
        suggestion.setType(type);
        suggestion.setItemId(536);
        suggestion.setQuantity(10);
        return suggestion;
    }
}

package com.runeassist.flip.controller;

import com.google.gson.JsonObject;
import com.runeassist.flip.model.FlipStatus;
import com.runeassist.flip.model.FlipV2;
import com.runeassist.flip.model.OfferStatus;
import com.runeassist.flip.model.SavedOffer;
import com.runeassist.flip.model.Transaction;
import com.runeassist.flip.ui.FlipRepairMenus;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class FlipHistorySyncServiceTest {

    @Test
    public void flipFromJsonReadsDeletedAndPortfolioId() {
        JsonObject o = new JsonObject();
        o.addProperty("id", "11111111-1111-1111-1111-111111111111");
        o.addProperty("itemId", 4151);
        o.addProperty("openedTime", 100);
        o.addProperty("openedQuantity", 10);
        o.addProperty("spent", 1000);
        o.addProperty("status", "BUYING");
        o.addProperty("deleted", true);
        o.addProperty("portfolioId", -4);
        o.addProperty("seqNo", 3);
        o.addProperty("updatedTime", 200);
        FlipV2 f = FlipHistorySyncService.flipFromJson(o, 7);
        assertNotNull(f);
        assertTrue(f.isDeleted());
        assertEquals(-4, f.getPortfolioId());
        assertEquals(FlipStatus.BUYING, f.getStatus());
        assertEquals(7, f.getAccountId());
    }

    @Test
    public void txToJsonRoundTripsCoreFields() {
        Transaction t = new Transaction();
        t.setId(UUID.fromString("22222222-2222-2222-2222-222222222222"));
        t.setType(OfferStatus.BUY);
        t.setItemId(4151);
        t.setPrice(100);
        t.setQuantity(2);
        t.setBoxId(1);
        t.setAmountSpent(200);
        t.setTimestamp(Instant.parse("2024-01-01T00:00:00Z"));
        t.setRuneAssistSuggestion(true);
        t.setSuggestionId("11111111-1111-1111-1111-111111111111");
        JsonObject o = FlipHistorySyncService.txToJson(t);
        assertEquals("BUY", o.get("type").getAsString());
        assertEquals(4151, o.get("itemId").getAsInt());
        assertEquals(200, o.get("amountSpent").getAsLong());
        assertFalse(o.get("id").getAsString().isEmpty());
        assertTrue(o.get("runeAssistSuggestion").getAsBoolean());
        assertEquals(t.getSuggestionId(), o.get("suggestionId").getAsString());
    }

    @Test
    public void txFromJsonParsesSell() {
        JsonObject o = new JsonObject();
        o.addProperty("id", "33333333-3333-3333-3333-333333333333");
        o.addProperty("type", "SELL");
        o.addProperty("itemId", 4151);
        o.addProperty("price", 500);
        o.addProperty("quantity", 3);
        o.addProperty("boxId", 2);
        o.addProperty("amountSpent", 1500);
        o.addProperty("timestamp", "2024-02-01T00:00:00Z");
        Transaction t = FlipHistorySyncService.txFromJson(o);
        assertNotNull(t);
        assertEquals(OfferStatus.SELL, t.getType());
        assertEquals(4151, t.getItemId());
        assertEquals(1500, t.getAmountSpent());
        assertEquals(UUID.fromString("33333333-3333-3333-3333-333333333333"), t.getId());
    }

    @Test
    public void offerEventJsonKeepsPriorAttributionWhenSlotBecomesEmpty() {
        SavedOffer previous = new SavedOffer();
        previous.setState(GrandExchangeOfferState.BUYING);
        previous.setRuneAssistSuggestion(true);
        previous.setSuggestionId("11111111-1111-1111-1111-111111111111");
        SavedOffer empty = new SavedOffer();
        empty.setState(GrandExchangeOfferState.EMPTY);
        JsonObject body = FlipHistorySyncService.offerEventJson(
                "22222222-2222-2222-2222-222222222222",
                "33333333-3333-3333-3333-333333333333", 2, empty, previous, 123L);
        assertEquals("EMPTY", body.get("state").getAsString());
        assertEquals("runeassist", body.get("origin").getAsString());
        assertEquals(previous.getSuggestionId(), body.get("suggestionId").getAsString());
        assertEquals(123L, body.get("ts").getAsLong());
    }

    @Test
    public void canMissedSaleRequiresOpenQty() {
        FlipV2 open = new FlipV2();
        open.setStatus(FlipStatus.SELLING);
        open.setOpenedQuantity(10);
        open.setClosedQuantity(4);
        assertTrue(FlipRepairMenus.canMissedSale(open));
        open.setClosedQuantity(10);
        open.setStatus(FlipStatus.FINISHED);
        assertFalse(FlipRepairMenus.canMissedSale(open));
    }

    @Test
    public void websiteLoginWithCodeUrlEncodesPairingCode() {
        String code = "AB CD";
        String encoded = java.net.URLEncoder.encode(code, java.nio.charset.StandardCharsets.UTF_8);
        assertEquals("AB+CD", encoded);
        assertTrue(encoded.indexOf(' ') < 0);
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.*;
import com.runeassist.flip.ui.PauseButton;
import com.runeassist.flip.ui.SuggestionPanel;
import com.runeassist.flip.ui.flipsdialog.FlipsDialogController;
import net.runelite.api.Client;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import javax.swing.SwingUtilities;
import java.lang.reflect.Proxy;

import static org.junit.jupiter.api.Assertions.*;

class SuggestionCollectReconciliationTest {
    private int tick = 100;
    private boolean homeOpen = true;
    private boolean collectVisible;
    private int clears;
    private SuggestionPanel panel;
    private SuggestionController controller;
    private GrandExchangeUncollectedManager uncollected;
    private final SuggestionManager suggestions = new SuggestionManager();

    @BeforeEach void setUp() throws Exception {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
                new Class<?>[]{Client.class}, (proxy, method, args) -> {
                    switch (method.getName()) {
                        case "getTickCount": return tick;
                        case "getAccountHash": return 1L;
                        default: throw new AssertionError("Unexpected client call: " + method.getName());
                    }
                });
        OsrsLoginManager login = new OsrsLoginManager(client);
        GrandExchange ge = new GrandExchange(client) {
            @Override boolean isHomeScreenOpen() { return homeOpen; }
            @Override boolean isCollectButtonVisible() { return collectVisible; }
        };
        uncollected = new GrandExchangeUncollectedManager(client) {
            @Override public synchronized void clearAllUncollected(Long accountHash) {
                clears++;
                super.clearAllUncollected(accountHash);
            }
        };
        controller = new SuggestionController(null, client, null, login, null, ge,
                null, null, null, null, null, suggestions, null, uncollected,
                null, null, null, null, null, null);
        SwingUtilities.invokeAndWait(() -> {
            FlipsDialogController dialogs = new FlipsDialogController(null, null, null, null,
                    null, null, null, null, null, null, null, null);
            panel = new SuggestionPanel(null, suggestions, null, null, new PauseButton(null, null),
                    login, client, null, uncollected, null, null, null, ge, dialogs, null, controller);
            controller.setSuggestionPanel(panel);
        });
    }

    @Test void collectToWaitClearsTheHiddenCollectMessage() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            panel.suggestCollect();
            assertTrue(panel.isCollectItemsSuggested());
            panel.updateSuggestion(waitSuggestion());
            assertFalse(panel.isCollectItemsSuggested());
        });
        controller.reconcileUncollected();
        assertFalse(suggestions.isSuggestionNeeded());
        assertEquals(0, clears);
    }

    @Test void collectToLoadingClearsTheHiddenCollectMessage() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            panel.suggestCollect();
            panel.showLoading();
            assertFalse(panel.isCollectItemsSuggested());
        });
        controller.reconcileUncollected();
        assertFalse(suggestions.isSuggestionNeeded());
        assertEquals(0, clears);
    }

    @Test void staleCardIsConsumedOnceEvenBeforeTheEdtCanRepaint() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            panel.setMessage(new String("Collect items"));
            controller.reconcileUncollected();
            assertFalse(panel.isCollectItemsSuggested());
            assertTrue(suggestions.isSuggestionNeeded());
            suggestions.setSuggestionNeeded(false);
            for (int i = 0; i < 100; i++) {
                tick++;
                controller.reconcileUncollected();
            }
            assertFalse(suggestions.isSuggestionNeeded());
            assertEquals(0, clears, "A stale card must not clear collection bookkeeping");
        });
        SwingUtilities.invokeAndWait(() -> assertFalse(panel.isCollectItemsSuggested()));
    }

    @Test void realStaleItemsAreClearedOnceAndNewFillsCanBeReconciledLater() {
        uncollected.addUncollected(1L, 0, 4151, 1, 0);
        tick += 3;
        controller.reconcileUncollected();
        assertEquals(1, clears);
        assertFalse(uncollected.HasUncollected(1L));
        assertTrue(suggestions.isSuggestionNeeded());
        suggestions.setSuggestionNeeded(false);
        tick++;
        controller.reconcileUncollected();
        assertEquals(1, clears);
        assertFalse(suggestions.isSuggestionNeeded());
        uncollected.addUncollected(1L, 1, 4151, 2, 0);
        tick += 3;
        controller.reconcileUncollected();
        assertEquals(2, clears);
        assertTrue(suggestions.isSuggestionNeeded());
    }

    @Test void gracePeriodProtectsFreshFillsAndCollectCard() throws Exception {
        uncollected.addUncollected(1L, 0, 4151, 1, 0);
        SwingUtilities.invokeAndWait(panel::suggestCollect);
        for (int i = 0; i <= 2; i++) {
            controller.reconcileUncollected();
            assertTrue(panel.isCollectItemsSuggested());
            assertTrue(uncollected.HasUncollected(1L));
            assertEquals(0, clears);
            tick++;
        }
        controller.reconcileUncollected();
        assertFalse(panel.isCollectItemsSuggested());
        assertEquals(1, clears);
    }

    @Test void visibleCollectButtonOrClosedHomeNeverClearsCollectionState() throws Exception {
        uncollected.addUncollected(1L, 0, 4151, 1, 0);
        tick += 3;
        SwingUtilities.invokeAndWait(panel::suggestCollect);
        collectVisible = true;
        controller.reconcileUncollected();
        collectVisible = false;
        homeOpen = false;
        controller.reconcileUncollected();
        assertTrue(panel.isCollectItemsSuggested());
        assertTrue(uncollected.HasUncollected(1L));
        assertFalse(suggestions.isSuggestionNeeded());
        assertEquals(0, clears);
    }

    @Test void delayedDismissalDoesNotOverwriteANewerCollectCard() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            panel.suggestCollect();
            panel.clearCollectSuggestion();
            panel.suggestCollect();
        });
        SwingUtilities.invokeAndWait(() -> assertTrue(panel.isCollectItemsSuggested()));
    }

    @Test void pauseReplacesCollectState() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            panel.suggestCollect();
            panel.setIsPausedMessage();
            assertFalse(panel.isCollectItemsSuggested());
        });
    }

    private Suggestion waitSuggestion() {
        Suggestion suggestion = new Suggestion();
        suggestion.setType(SuggestionType.WAIT);
        suggestion.setMessage("Waiting for offers to fill");
        suggestion.setWhy("Offers are active");
        return suggestion;
    }

    @Test void compactWaitAndLoadingHaveReadableStatesAndIgnoreLateTimeouts() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            try {
                panel.updateSuggestion(waitSuggestion());
                assertEquals(96, panel.getPreferredSize().height);
                panel.showLoading();
                java.lang.reflect.Field textField = SuggestionPanel.class.getDeclaredField("suggestionText");
                textField.setAccessible(true);
                javax.swing.JLabel text = (javax.swing.JLabel) textField.get(panel);
                assertTrue(text.getText().contains("Getting the next flip"));
                java.lang.reflect.Field timerField = SuggestionPanel.class.getDeclaredField("loadingStatusTimer");
                timerField.setAccessible(true);
                javax.swing.Timer timer = (javax.swing.Timer) timerField.get(panel);
                timer.getActionListeners()[0].actionPerformed(null);
                assertTrue(text.getText().contains("Server slow"));
                panel.showLoading();
                assertTrue(text.getText().contains("Server slow"), "Polling must not reset the slow state");
                panel.suggestCollect();
                timer.getActionListeners()[0].actionPerformed(null);
                assertTrue(text.getText().contains("Collect items"));
                assertFalse(timer.isRunning());
            } catch (ReflectiveOperationException e) { throw new RuntimeException(e); }
        });
    }
}

package com.runeassist.flip.controller;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Proxy;
import static org.junit.jupiter.api.Assertions.*;

class GrandExchangeVisibilityTest {
    @Test void homeOrEditorCanKeepTheGeOpenButHiddenLeftoversCannot() {
        boolean[] visible = {true, false};
        Widget home = widget(visible, 0);
        Widget editor = widget(visible, 1);
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
                new Class<?>[]{Client.class}, (proxy, method, args) -> {
                    if (method.getName().equals("getWidget")) return (int) args[1] == 7 ? home : editor;
                    throw new AssertionError("Unexpected client call: " + method.getName());
                });
        GrandExchange ge = new GrandExchange(client);
        assertTrue(ge.isOpen());
        visible[0] = false;
        visible[1] = true;
        assertTrue(ge.isOpen(), "Opening the offer editor must not enter Away");
        visible[1] = false;
        assertFalse(ge.isOpen());
    }

    private static Widget widget(boolean[] visible, int index) {
        return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
                new Class<?>[]{Widget.class}, (proxy, method, args) -> {
                    if (method.getName().equals("isHidden")) return !visible[index];
                    throw new AssertionError("Unexpected widget call: " + method.getName());
                });
    }
}

