package com.runeassist.flip.model;

import java.util.ArrayList;
import java.util.Locale;

/**
 * Maps Ares compose JSON onto the local {@link Suggestion} used by GE UI / overlays.
 */
public final class ComposeSuggestionMapper
{
    private ComposeSuggestionMapper()
    {
    }

    /**
     * @return mapped suggestion, or null if the response is missing / has an unknown type.
     * Copies an optional bundled {@code graph} onto {@link Suggestion#setGraphData}.
     */
    public static Suggestion toSuggestion(ComposeSuggestionResponse response)
    {
        if (response == null || !response.isOk() || response.getSuggestion() == null)
        {
            return null;
        }
        Suggestion s = toSuggestion(response.getSuggestion(), response.getSource());
        if (s != null && response.getSuggestionId() != null)
        {
            s.setServerSuggestionId(response.getSuggestionId());
        }
        if (s != null && response.getGraph() != null)
        {
            s.setGraphData(response.getGraph());
        }
        return s;
    }

    public static Suggestion toSuggestion(ComposeSuggestionResponse.SuggestionDto dto, String source)
    {
        if (dto == null)
        {
            return null;
        }
        SuggestionType type = parseType(dto.getType());
        if (type == null)
        {
            return null;
        }
        Suggestion s = new Suggestion();
        s.setType(type);
        s.setBoxId(dto.getBoxId());
        s.setItemId(dto.getItemId());
        s.setId(dto.getItemId());
        s.setPrice(dto.getPrice());
        s.setQuantity(dto.getQuantity());
        s.setName(dto.getName() != null ? dto.getName() : "");
        s.setMessage(dto.getMessage() != null ? dto.getMessage() : "");
        s.setWhy(dto.getWhy() != null ? dto.getWhy() : "");
        s.setProfitEstimateBasis(dto.getProfitEstimateBasis());
        s.setPotentialProfitGp(dto.getPotentialProfitGp());
        s.setTargetSellPrice(dto.getTargetSellPrice());
        s.setTargetSellTaxGp(dto.getTargetSellTaxGp());
        s.setProfitModelVersion(dto.getProfitModelVersion());
        if (dto.getExpectedProfit() != null)
        {
            s.setExpectedProfit(dto.getExpectedProfit());
        }
        if (dto.getExpectedDuration() != null)
        {
            s.setExpectedDuration(dto.getExpectedDuration());
        }
        s.setGeLimit(dto.getGeLimit());
        s.setRemainingLimit(dto.getRemainingLimit());
        s.setLimitKnown(dto.isLimitKnown());
        if (dto.getFlags() != null && !dto.getFlags().isEmpty())
        {
            s.setFlags(new ArrayList<>(dto.getFlags()));
        }
        if (source != null && !source.isEmpty())
        {
            s.setPickSource(source);
        }
        else
        {
            s.setPickSource("ares-compose");
        }
        return s;
    }

    static SuggestionType parseType(String raw)
    {
        if (raw == null || raw.isEmpty())
        {
            return null;
        }
        String key = raw.trim().toLowerCase(Locale.ROOT).replace('-', '_');
        for (SuggestionType t : SuggestionType.values())
        {
            if (t.apiValue().equals(key) || t.name().equalsIgnoreCase(raw.trim()))
            {
                return t;
            }
        }
        return null;
    }
}

package com.runeassist.flip.model;

import lombok.Data;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

import java.util.Objects;

@Data
public class SavedOffer
{
	private int itemId;
	private int quantitySold;
	private int totalQuantity;
	private long price;
	private long spent;
	private GrandExchangeOfferState state;
	private boolean runeAssistSuggestion;
	private String suggestionId;
	// Observation metadata is session-local; never restore it as placement proof.
	private transient long observedAt;
	private transient long placedAt;
	private transient String offerInstanceId;
	private transient String observationSessionId;
	private transient boolean loginObservation;

	public static SavedOffer fromGrandExchangeOffer(GrandExchangeOffer offer) {
		SavedOffer o =  new SavedOffer();
		o.setItemId(offer.getItemId());
		o.setQuantitySold(offer.getQuantitySold());
		o.setTotalQuantity(offer.getTotalQuantity());
		o.setPrice(offer.getPrice());
		o.setSpent(offer.getSpent());
		o.setState(offer.getState());
		return o;
	}

	public OfferStatus getOfferStatus() {
		switch (state) {
			case SELLING:
			case CANCELLED_SELL:
			case SOLD:
				return OfferStatus.SELL;
			case BUYING:
			case CANCELLED_BUY:
			case BOUGHT:
				return OfferStatus.BUY;
			default:
				return OfferStatus.EMPTY;
		}
	}

	@Override
	public boolean equals(Object o) {
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		SavedOffer that = (SavedOffer) o;
		return itemId == that.itemId && quantitySold == that.quantitySold && totalQuantity == that.totalQuantity && price == that.price && spent == that.spent && state == that.state;
	}

	@Override
	public int hashCode() {
		return Objects.hash(itemId, quantitySold, totalQuantity, price, spent, state);
	}
}

