import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.controller.InventorySlotTooltipDataProvider;
import com.runeassist.flip.controller.PlayerLocationController;
import com.runeassist.flip.model.InventorySlotTooltipData;
import com.runeassist.flip.model.TooltipHoverSource;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class InventorySlotTooltipOverlay extends Overlay {

    private static final int INVENTORY_WIDGET_GROUP = 149;
    private static final int INVENTORY_WIDGET_CHILD = 0;
    private static final int GE_INVENTORY_WIDGET_GROUP = 467;
    private static final int GE_INVENTORY_WIDGET_CHILD = 0;
    private static final int BANK_WIDGET_GROUP = 12;
    private static final int[] BANK_ITEM_CONTAINER_CHILDREN = {12, 13, 89};
    private static final int BANK_INVENTORY_WIDGET_GROUP = 15;
    private static final int BANK_INVENTORY_WIDGET_CHILD = 3;

    private static final String UNREALISED_PROFIT_PREFIX = "Unrealized Profit: ";
    private static final String UNREALISED_ROI_PREFIX = "Unrealized ROI: ";
    private static final String POSITIVE_COLOR = "<col=50dc78>";
    private static final String NEGATIVE_COLOR = "<col=e65a5a>";
    private static final String COLOR_END = "</col>";

    private final Client client;
    private final InventorySlotTooltipDataProvider tooltipDataProvider;
    private final TooltipManager tooltipManager;
    private final PlayerLocationController playerLocationController;
    private final RuneAssistConfig config;

    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.portfolioTooltips()) {
            return null;
        }
        if (!playerLocationController.isNearGE()) {
            return null;
        }

        InventorySlotTooltipData tooltipData = findHoveredSlotTooltipData();
        if (tooltipData == null) {
            return null;
        }

        String tooltipText = buildTooltipText(tooltipData.getLines());
        if (tooltipText != null && !tooltipText.isEmpty()) {
            tooltipManager.add(new Tooltip(tooltipText));
        }
        return null;
    }

    private InventorySlotTooltipData findHoveredSlotTooltipData() {
        Point mousePos = client.getMouseCanvasPosition();
        if (mousePos == null) {
            return null;
        }

        for (SourcedWidget sourcedWidget : getVisibleItemWidgets()) {
            Widget[] children = sourcedWidget.widget.getDynamicChildren();
            if (children == null) {
                continue;
            }

            for (Widget child : children) {
                if (child == null || child.isHidden()) {
                    continue;
                }

                int itemId = child.getItemId();
                int quantity = child.getItemQuantity();
                if (itemId <= 0 || quantity <= 0) {
                    continue;
                }

                Rectangle bounds = child.getBounds();
                if (bounds == null || !bounds.contains(mousePos.getX(), mousePos.getY())) {
                    continue;
                }

                return tooltipDataProvider.getTooltipData(itemId, quantity, sourcedWidget.source);
            }
        }

        return null;
    }

    private List<SourcedWidget> getVisibleItemWidgets() {
        List<SourcedWidget> widgets = new ArrayList<>(3);
        Widget geInventory = client.getWidget(GE_INVENTORY_WIDGET_GROUP, GE_INVENTORY_WIDGET_CHILD);
        if (geInventory != null && !geInventory.isHidden()) {
            widgets.add(new SourcedWidget(geInventory, TooltipHoverSource.INVENTORY));
        }

        Widget inventory = client.getWidget(INVENTORY_WIDGET_GROUP, INVENTORY_WIDGET_CHILD);
        if (inventory != null && !inventory.isHidden()) {
            widgets.add(new SourcedWidget(inventory, TooltipHoverSource.INVENTORY));
        }

        for (int childId : BANK_ITEM_CONTAINER_CHILDREN) {
            Widget bankItems = client.getWidget(BANK_WIDGET_GROUP, childId);
            if (bankItems != null && !bankItems.isHidden()) {
                widgets.add(new SourcedWidget(bankItems, TooltipHoverSource.BANK));
            }
        }

        Widget bankInventory = client.getWidget(BANK_INVENTORY_WIDGET_GROUP, BANK_INVENTORY_WIDGET_CHILD);
        if (bankInventory != null && !bankInventory.isHidden()) {
            widgets.add(new SourcedWidget(bankInventory, TooltipHoverSource.INVENTORY));
        }

        return widgets;
    }

    private String buildTooltipText(List<String> lines) {
        if (lines == null || lines.isEmpty()) {
            return "";
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < lines.size(); i++) {
            if (i > 0) {
                sb.append("<br>");
            }
            sb.append(formatTooltipLine(lines.get(i)));
        }
        return sb.toString();
    }

    private String formatTooltipLine(String line) {
        for (String prefix : new String[]{UNREALISED_PROFIT_PREFIX, UNREALISED_ROI_PREFIX}) {
            String formatted = formatSignedValueLine(line, prefix);
            if (formatted != null) {
                return formatted;
            }
        }

        return line == null ? "" : line;
    }

    private String formatSignedValueLine(String line, String prefix) {
        if (line == null || !line.startsWith(prefix)) {
            return null;
        }

        String value = line.substring(prefix.length());
        if ("Unknown".equals(value)) {
            return line;
        }

        String color = value.startsWith("-") ? NEGATIVE_COLOR : POSITIVE_COLOR;
        return prefix + color + value + COLOR_END;
    }

    @RequiredArgsConstructor
    private static class SourcedWidget {
        private final Widget widget;
        private final TooltipHoverSource source;
    }
}

package com.runeassist.flip.ui;

import com.runeassist.flip.controller.OfferHandler;
import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.OfferManager;
import com.runeassist.flip.model.Suggestion;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.widgets.*;
import net.runelite.client.config.Keybind;

import java.util.Objects;

import static net.runelite.api.VarPlayer.CURRENT_GE_ITEM;

@Slf4j
public class OfferEditor {
    private final OfferManager offerManager;
    private final OfferHandler offerHandler;
    private final Client client;
    private final RuneAssistConfig config;

    private Widget text;
    private static final int MOUSE_OFF_TEXT_COLOR = 0x0040FF;
    private static final int MOUSE_OFF_ERROR_TEXT_COLOR = 0xAA2222;

    public OfferEditor(OfferManager offerManager, Widget parent, OfferHandler offerHandler, Client client, RuneAssistConfig config) {
        this.offerManager = offerManager;
        this.offerHandler = offerHandler;
        this.client = client;
        this.config = config;
        if (parent == null) {
            return;
        }

        text = parent.createChild(-1, WidgetType.TEXT);
        prepareTextWidget(text, WidgetTextAlignment.LEFT, WidgetPositionMode.ABSOLUTE_TOP, 40, 10);
    }

    private void prepareTextWidget(Widget widget, int xAlignment, int yMode, int yOffset, int xOffset) {
        widget.setTextColor(MOUSE_OFF_TEXT_COLOR);
        widget.setFontId(FontID.VERDANA_11_BOLD);
        widget.setYPositionMode(yMode);
        widget.setOriginalX(xOffset);
        widget.setOriginalY(yOffset);
        widget.setOriginalHeight(20);
        widget.setXTextAlignment(xAlignment);
        widget.setWidthMode(WidgetSizeMode.MINUS);
        widget.revalidate();
    }

    public void showSuggestion(Suggestion suggestion) {
        var currentItemId = client.getVarpValue(CURRENT_GE_ITEM);
        if (offerHandler.isSettingQuantity()) {
            if (currentItemId != suggestion.getItemId()) {
                return;
            }
            if (!Objects.equals(suggestion.offerType(), offerHandler.getOfferType())) {
                return;
            }

            shiftChatboxWidgetsDown();
            showQuantity(suggestion.getQuantity());
        } else if (offerHandler.isSettingPrice()) {
            if (currentItemId != suggestion.getItemId()
                    || !Objects.equals(suggestion.offerType(), offerHandler.getOfferType())) {
                long price = offerManager.getViewedSlotItemPrice();
                if (offerHandler.getViewedSlotPriceErrorText() != null && price <= 0) {
                    shiftChatboxWidgetsDown();
                    setErrorText(offerHandler.getViewedSlotPriceErrorText());
                    return;
                }

                if (offerManager.getViewedSlotItemId() == currentItemId) {
                    shiftChatboxWidgetsDown();
                    if (offerHandler.getViewedSlotPriceErrorText() != null) {
                        showPrice(price, offerHandler.getViewedSlotPriceErrorText());
                    } else {
                        showPrice(price);
                    }
                }
            } else {
                shiftChatboxWidgetsDown();
                showPrice(suggestion.getPrice());
            }
        }
    }

    private void showQuantity(int quantity) {
        text.setText(setActionText("RuneAssist quantity: " + quantity));
        text.setAction(1, "Set quantity");
        setHoverListeners(text);
        text.setOnOpListener((JavaScriptCallback) ev ->
        {
            offerHandler.setChatboxValue(quantity);
        });
    }

    public void showPrice(long price) {
        showPrice(price, null);
    }

    public void showPrice(long price, String warning) {
        text.setText(setActionText("RuneAssist price: " + String.format("%,d", price) + " gp")
                + (warning == null || warning.isEmpty() ? "" : ". " + warning));
        text.setAction(0, "Set price");
        setHoverListeners(text);
        text.setOnOpListener((JavaScriptCallback) ev ->
        {
            offerHandler.setChatboxValue(price);
        });
    }

    private String setActionText(String target) {
        Keybind keybind = config.quickSetKeybind();
        if (keybind == null || Keybind.NOT_SET.equals(keybind)) {
            return "set to " + target;
        }
        return "Press [" + keybind + "] to set to " + target;
    }

    private void setHoverListeners(Widget widget) {
        widget.setHasListener(true);
        widget.setOnMouseRepeatListener((JavaScriptCallback) ev -> widget.setTextColor(0xFFFFFF));
        widget.setOnMouseLeaveListener((JavaScriptCallback) ev -> widget.setTextColor(MOUSE_OFF_TEXT_COLOR));
    }

    private void setErrorText(String message) {
        text.setText(message);
        text.setTextColor(MOUSE_OFF_ERROR_TEXT_COLOR);
        text.revalidate();
    }

    private void shiftChatboxWidgetsDown() {
        Widget chatboxTitle = client.getWidget(ComponentID.CHATBOX_TITLE);
        if (chatboxTitle != null) {
            chatboxTitle.setOriginalY(chatboxTitle.getOriginalY() + 7);
            chatboxTitle.revalidate();
        }
    }
}

package com.runeassist.flip.ui;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.TextComponent;

import java.awt.*;

public class GpDropOverlay extends Overlay {
    private final OverlayManager overlayManager;
    private final long startTime;
    private final Point startPosition = new Point(); // Starting position of the text
    final TextComponent textComponent = new TextComponent();

    public GpDropOverlay(OverlayManager overlayManager, Client client, long profit, int slot) {
        this.overlayManager = overlayManager;
        this.startTime = System.currentTimeMillis();

        Widget slotWidget = client.getWidget(465, slot + 7);
        if (slotWidget == null) {
            return;
        }
        startPosition.x = slotWidget.getCanvasLocation().getX() + 35;
        startPosition.y = slotWidget.getCanvasLocation().getY() + 75;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        String absProfitText = UIUtilities.quantityToRSDecimalStack(Math.abs(profit), false);
        String profitText = (profit >= 0 ? "+ " : "- ") + absProfitText + " gp";
        textComponent.setText(profitText);
        textComponent.setFont(FontManager.getRunescapeFont().deriveFont(Font.BOLD, 16f));
        if (profit < 0) {
            textComponent.setColor(Color.RED);
        } else {
            textComponent.setColor(Color.GREEN);
        }
        overlayManager.add(this);
    }


    @Override
    public Dimension render(Graphics2D graphics) {
        long elapsed = System.currentTimeMillis() - startTime;
        if (elapsed > 3000) { // Display for 5 seconds
            overlayManager.remove(this);
            return null;
        }

        // Calculate the upward movement. Adjust the divisor to control the speed.
        int yOffset = (int) (elapsed / 50); // Moves up 1 pixel every 50ms

        // Ensure the text moves upwards by subtracting yOffset from the starting Y position
        Point currentPosition = new Point(startPosition.x, startPosition.y - yOffset);
        textComponent.setPosition(currentPosition);
        textComponent.render(graphics);

        return null;
    }
}

package com.runeassist.flip.ui;

import com.runeassist.flip.model.FlipV2;
import com.runeassist.flip.model.Stats;

/** One line a player can paste into Discord #wins. */
public final class ShareSummary {
    private ShareSummary() {
    }

    public static String format(String intervalLabel, Stats stats, FlipV2 best) {
        String label = intervalLabel == null || intervalLabel.isEmpty() ? "Session" : intervalLabel;
        int flips = stats == null ? 0 : stats.flipsMade;
        long profit = stats == null ? 0 : stats.profit;
        StringBuilder sb = new StringBuilder("RuneAssist \u00b7 ").append(label).append(": ")
                .append(flips).append(flips == 1 ? " flip, " : " flips, ")
                .append(signed(profit)).append(" gp");
        if (best != null && best.getProfit() != 0) {
            String name = best.getCachedItemName() != null ? best.getCachedItemName() : ("item " + best.getItemId());
            sb.append(" \u00b7 best: ").append(name).append(' ').append(signed(best.getProfit()));
        }
        return sb.toString();
    }

    private static String signed(long gp) {
        String text = UIUtilities.formatProfit(Math.abs(gp));
        return (gp < 0 ? "-" : "+") + text;
    }
}

