    private void addProfile() {
        String newProfileName = JOptionPane.showInputDialog(
                SwingUtilities.getWindowAncestor(this),
                "Enter new profile name (must be valid file name):",
                "New preferences profile",
                JOptionPane.PLAIN_MESSAGE);
        if (newProfileName == null || newProfileName.trim().isEmpty()) {
            return;
        }
        newProfileName = newProfileName.trim();
        try {
            preferencesManager.addProfile(newProfileName);
            refresh();
        } catch (IOException ex) {
            log.error("adding new profile: {}", newProfileName, ex);
            JOptionPane.showMessageDialog(
                    SwingUtilities.getWindowAncestor(this),
                    "Error adding new profile: " + ex.getMessage(),
                    "Add profile failed",
                    JOptionPane.WARNING_MESSAGE);
        }
    }

    private void deleteProfile() {
        String selectedProfile = (String) profileSelector.getSelectedItem();
        if (selectedProfile == null) {
            return;
        }
        int result = JOptionPane.showConfirmDialog(
                SwingUtilities.getWindowAncestor(this),
                "Delete profile '" + selectedProfile + "'?",
                "Delete Profile",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.QUESTION_MESSAGE);
        if (result != JOptionPane.YES_OPTION) {
            return;
        }
        ((DefaultComboBoxModel<String>) profileSelector.getModel()).removeElement(selectedProfile);
        try {
            preferencesManager.deleteSelectedProfile();
            profileSelector.setSelectedItem(preferencesManager.getCurrentProfile());
        } catch (IOException ex) {
            log.error("removing profile: {}", selectedProfile, ex);
            JOptionPane.showMessageDialog(
                    SwingUtilities.getWindowAncestor(this),
                    "Error deleting profile: " + ex.getMessage(),
                    "Remove profile failed",
                    JOptionPane.WARNING_MESSAGE);
        }
        refresh();
    }

    private void startPairing() {
        setPairingBusy(true);
        historyStatusLabel.setText("Getting pairing code…");
        executorService.execute(() -> {
            try {
                String code = flipHistorySyncService.startPairing();
                SwingUtilities.invokeLater(() -> {
                    setPairingBusy(false);
                    showPairingCode(code);
                });
            } catch (Exception ex) {
                log.warn("pairing start failed", ex);
                SwingUtilities.invokeLater(() -> {
                    setPairingBusy(false);
                    refreshHistoryStatus();
                    historyStatusLabel.setText("Could not get a pairing code. Check the server is reachable.");
                    JOptionPane.showMessageDialog(
                            SwingUtilities.getWindowAncestor(this),
                            "Could not get a pairing code. Check the server is reachable.",
                            "Get pairing code",
                            JOptionPane.WARNING_MESSAGE);
                });
            }
        });
    }

    private void showPairingCode(String code) {
        String trimmed = code == null ? "" : code.trim();
        if (trimmed.isEmpty() || looksLikeUrl(trimmed)) {
            pairingCodeField.setText("");
            pairingCodePanel.setVisible(false);
            openLinkButton.setVisible(false);
            refreshHistoryStatus();
            revalidate();
            repaint();
            return;
        }
        pairingCodeField.setText(trimmed);
        pairingCodeField.setCaretPosition(0);
        pairingCodeField.selectAll();
        pairingCodeHint.setText(PrefsUi.wrapHtml(
                "Enter this code on the other device or website. Expires in 10 minutes.", statusWrapPx()));
        pairingCodePanel.setVisible(true);
        openLinkButton.setVisible(true);
        PrefsUi.stretchWidth(pairingCodePanel);
        pairingCodePanel.setMaximumSize(new Dimension(Integer.MAX_VALUE,
                Math.max(96, pairingCodePanel.getPreferredSize().height)));
        refreshHistoryStatus();
        copyPairingCode();
        revalidate();
        repaint();
    }

    private static boolean looksLikeUrl(String value) {
        String lower = value.toLowerCase(Locale.ROOT);
        return lower.startsWith("http://") || lower.startsWith("https://") || lower.contains("://");
    }

    private void openPairingInBrowser() {
        String code = pairingCodeField.getText();
        if (code == null || code.isEmpty()) {
            return;
        }
        LinkBrowser.browse(flipHistorySyncService.websiteLoginWithCodeUrl(code));
    }

    private void copyPairingCode() {
        String code = pairingCodeField.getText();
        if (code == null || code.isEmpty()) {
            return;
        }
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(code), null);
        copyCodeButton.setText("Copied");
        executorService.schedule(() -> SwingUtilities.invokeLater(() -> copyCodeButton.setText("Copy")),
                2, TimeUnit.SECONDS);
    }

    private void setPairingBusy(boolean busy) {
        linkDeviceBtn.setEnabled(!busy);
        redeemBtn.setEnabled(!busy);
    }

    private void refreshHistoryStatus() {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(this::refreshHistoryStatus);
            return;
        }
        historyStatusLabel.setText(PrefsUi.wrapHtml(flipHistorySyncService.statusMessage(), statusWrapPx()));
        historyStatusLabel.setForeground(flipHistorySyncService.isLinked()
                ? ColorScheme.GRAND_EXCHANGE_PRICE
                : ColorScheme.LIGHT_GRAY_COLOR);
        PrefsUi.stretchWidth(historyStatusLabel);
        if (!hasPairingCode()) {
            pairingCodePanel.setVisible(false);
        }
    }

    private boolean hasPairingCode() {
        String code = pairingCodeField.getText();
        return code != null && !code.isBlank() && !looksLikeUrl(code);
    }

    private void redeemPairing() {
        String code = JOptionPane.showInputDialog(
                SwingUtilities.getWindowAncestor(this),
                "Enter the pairing code from your other device or the website:",
                "Enter pairing code",
                JOptionPane.PLAIN_MESSAGE);
        if (code == null || code.trim().isEmpty()) {
            return;
        }
        executorService.execute(() -> {
            try {
                flipHistorySyncService.redeemPairing(code);
                SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                        SwingUtilities.getWindowAncestor(this),
                        "This client is now linked to that RuneAssist login.",
                        "Enter pairing code",
                        JOptionPane.INFORMATION_MESSAGE));
            } catch (Exception ex) {
                log.warn("pairing redeem failed", ex);
                SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                        SwingUtilities.getWindowAncestor(this),
                        "Could not redeem that code. It may be expired or already used.",
                        "Enter pairing code",
                        JOptionPane.WARNING_MESSAGE));
            }
        });
    }

    public void refresh() {
        if (!ensureEdt(this::refresh)) return;
        CardLayout layout = (CardLayout) getLayout();
        if (!accountPreferences.hasAccount()) {
            layout.show(this, "login");
            return;
        }
        layout.show(this, "preferences");
        sellOnlyModeToggleButton.setSelected(preferencesManager.isSellOnlyMode());
        buyAndHoldToggleButton.setSelected(preferencesManager.isBuyAndHold());
        f2pOnlyModeToggleButton.setSelected(preferencesManager.isF2pOnlyMode());
        timeBasedAbortToggleButton.setSelected(preferencesManager.isTimeBasedAbortEnabled());
        suppressTimeBasedAbortMinutesEvents = true;
        try {
            timeBasedAbortMinutesDropdown.setSelectedItem(PrefsUi.findByLong(
                    timeBasedAbortMinutesDropdown,
                    preferencesManager.getTimeBasedAbortMinutes(),
                    SuggestionPreferencesManager.DEFAULT_TIME_BASED_ABORT_MINUTES,
                    1));
        } finally {
            suppressTimeBasedAbortMinutesEvents = false;
        }
        syncReservedSlots(preferencesManager.getReservedSlots());
        syncDumpAlerts(preferencesManager.isReceiveDumpSuggestions(), preferencesManager.getDumpMinPredictedProfit());
        syncMinPredictedProfit(preferencesManager.getMinPredictedProfit());
        deleteProfileButton.setVisible(!preferencesManager.isDefaultProfileSelected());
        DefaultComboBoxModel<String> model = (DefaultComboBoxModel<String>) profileSelector.getModel();
        model.removeAllElements();
        model.addAll(preferencesManager.getAvailableProfiles());
        model.setSelectedItem(preferencesManager.getCurrentProfile());
    }

    private void syncMinPredictedProfit(Long value) {
        try {
            suppressMinProfitEvents = true;
            long effective = value == null
                    ? SuggestionPreferencesManager.DEFAULT_MIN_PREDICTED_PROFIT
                    : value;
            minPredictedProfitDropdown.setSelectedItem(PrefsUi.findByLong(
                    minPredictedProfitDropdown,
                    effective,
                    SuggestionPreferencesManager.DEFAULT_MIN_PREDICTED_PROFIT,
                    1));
        } finally {
            suppressMinProfitEvents = false;
        }
    }

    private void syncDumpAlerts(boolean enabled, Long minProfit) {
        try {
            suppressDumpAlertsEvents = true;
            dumpAlertsDropdown.setSelectedItem(enabled
                    ? PrefsUi.findByValue(dumpAlertsDropdown, minProfit != null ? minProfit : 100_000L, 1)
                    : dumpAlertsDropdown.getItemAt(0));
        } finally {
            suppressDumpAlertsEvents = false;
        }
    }

    private void syncReservedSlots(Integer value) {
        try {
            suppressReservedSlotsEvents = true;
            reservedSlotsDropdown.setSelectedItem(PrefsUi.findByValue(reservedSlotsDropdown, value, 0));
        } finally {
            suppressReservedSlotsEvents = false;
        }
    }

    private int statusWrapPx() {
        int width = getWidth();
        if (width <= 0) {
            width = MainPanel.CONTENT_WIDTH;
        }
        return Math.max(140, width - 48);
    }
}

package com.runeassist.flip.ui;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Parses ControlPanel custom timeframe text (90m, 1h 30m, 1:30). */
final class CustomTimeParse {
    private static final Pattern TOKEN = Pattern.compile(
            "(\\d+(?:\\.\\d+)?)\\s*(h|hr|hrs|hour|hours|m|min|mins|minute|minutes)?",
            Pattern.CASE_INSENSITIVE);

    private CustomTimeParse() {
    }

    static Integer minutes(String input) {
        if (input == null) {
            return null;
        }
        String trimmed = input.trim();
        if (trimmed.isEmpty()) {
            return null;
        }
        String normalized = trimmed.toLowerCase(Locale.ROOT);
        if (normalized.contains(":")) {
            return colonMinutes(normalized);
        }
        Integer tokenMinutes = tokenMinutes(normalized);
        if (tokenMinutes != null) {
            return tokenMinutes;
        }
        try {
            int minutes = Integer.parseInt(normalized);
            return minutes > 0 ? minutes : null;
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private static Integer colonMinutes(String normalized) {
        String[] parts = normalized.split(":");
        if (parts.length != 2) {
            return null;
        }
        try {
            int hours = Integer.parseInt(parts[0].trim());
            int minutes = Integer.parseInt(parts[1].trim());
            if (hours < 0 || minutes < 0 || minutes >= 60) {
                return null;
            }
            return hours * 60 + minutes;
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private static Integer tokenMinutes(String normalized) {
        Matcher matcher = TOKEN.matcher(normalized);
        int total = 0;
        int lastEnd = 0;
        boolean matched = false;
        while (matcher.find()) {
            if (!normalized.substring(lastEnd, matcher.start()).trim().isEmpty()) {
                return null;
            }
            String numberPart = matcher.group(1);
            String unit = matcher.group(2);
            double value;
            try {
                value = Double.parseDouble(numberPart);
            } catch (NumberFormatException ex) {
                return null;
            }
            if (unit == null || unit.toLowerCase(Locale.ROOT).startsWith("m")) {
                if (numberPart.contains(".")) {
                    return null;
                }
                total += (int) value;
            } else {
                total += (int) Math.round(value * 60.0);
            }
            matched = true;
            lastEnd = matcher.end();
        }
        if (!matched || !normalized.substring(lastEnd).trim().isEmpty()) {
            return null;
        }
        return total > 0 ? total : null;
    }
}

package com.runeassist.flip.ui;

import com.runeassist.flip.config.RuneAssistConfig;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.text.*;
import java.util.Locale;
import java.util.function.Supplier;

public class UIUtilities {
    public static final String redditIcon = "/reddit-icon.png";
    public static final String discordIcon = "/discord.png";
    public static final String githubIcon = "/github.png";
    public static final String logoutIcon = "/logout.png";
    public static final String internetIcon = "/internet.png";

    public static final float BUTTON_HOVER_LUMINANCE = 0.65f;
    public static final Color OUTDATED_COLOR = new Color(250, 74, 75);
    public static final Color TOMATO = new Color(255,99,71);

    private static final NumberFormat PRECISE_DECIMAL_FORMATTER = new DecimalFormat(
            "#,###.###",
            DecimalFormatSymbols.getInstance(Locale.ENGLISH)
    );
    private static final NumberFormat DECIMAL_FORMATTER = new DecimalFormat(
            "#,###.#",
            DecimalFormatSymbols.getInstance(Locale.ENGLISH)
    );

    public static synchronized String quantityToRSDecimalStack(long quantity, boolean precise)
    {
        String sign = quantity >= 0 ? "" : "-";
        quantity = Math.abs(quantity);
        if (Long.toString(quantity).length() <= 4)
        {
            return sign + QuantityFormatter.formatNumber(quantity);
        }

        long power = (long) Math.log10(quantity);

        // Output thousandths for values above a million
        NumberFormat format = precise && power >= 6
                ? PRECISE_DECIMAL_FORMATTER
                : DECIMAL_FORMATTER;

        return sign+format.format(quantity / Math.pow(10, (Long.divideUnsigned(power, 3)) * 3))
                + new String[] {"", "K", "M", "B", "T"}[(int) (power / 3)];
    }

    public static Color getProfitColor(long profit, RuneAssistConfig config) {
        if (profit > 0) {
            return config.profitAmountColor();
        } else if (profit < 0) {
            return config.lossAmountColor();
        } else {
            return Color.WHITE;
        }
    }

    public static Color getProfitColor(double profit, RuneAssistConfig config) {
        if (profit > 0) {
            return config.profitAmountColor();
        } else if (profit < 0) {
            return config.lossAmountColor();
        } else {
            return Color.WHITE;
        }
    }

    public static String formatProfit(long profit) {
        return quantityToRSDecimalStack(profit, true) + " gp";
    }

    public static String formatProfitWithoutGp(long profit) {
        return quantityToRSDecimalStack(profit, true);
    }

    public static String formatSuggestionDuration(double durationSeconds) {
        int totalMinutes = (int) Math.round(durationSeconds / 60.0);
        totalMinutes = Math.round(totalMinutes / 5.0f) * 5;
        totalMinutes = Math.max(totalMinutes, 5);

        String formatted = formatDurationMinutes(totalMinutes);
        if (!formatted.contains("h") && !formatted.contains("d")) {
            return formatted.replace("m", "min");
        }
        return formatted;
    }

    public static String formatDurationMinutes(int minutes) {
        int safeMinutes = Math.max(0, minutes);
        int days = safeMinutes / (24 * 60);
        int hours = (safeMinutes % (24 * 60)) / 60;
        int remainingMinutes = safeMinutes % 60;

        if (days > 0) {
            return hours == 0 ? days + "d" : days + "d " + hours + "h";
        }
        if (hours > 0) {
            return hours + "h " + remainingMinutes + "m";
        }
        return Math.max(1, remainingMinutes) + "m";
    }

    public static String formatHoldDuration(int durationSeconds) {
        if (durationSeconds <= 0) {
            return "0m";
        }
        int safeMinutes = durationSeconds / 60;
        if (safeMinutes <= 0) {
            return "0m";
        }
        int days = safeMinutes / (24 * 60);
        int hours = (safeMinutes % (24 * 60)) / 60;
        int remainingMinutes = safeMinutes % 60;
        if (days > 0) {
            return hours == 0 ? days + "d" : days + "d " + hours + "h";
        }
        if (hours > 0) {
            return remainingMinutes == 0 ? hours + "h" : hours + "h " + remainingMinutes + "m";
        }
        return remainingMinutes + "m";
    }

    public static String truncateString(String string, int length) {
        if (string.length() > length) {
            return string.substring(0, length) + "...";
        }
        return string;
    }

    public static JLabel buildButton(BufferedImage icon, String tooltip, Runnable onClick) {
        JLabel label = new JLabel();
        label.setToolTipText(tooltip);
        label.setHorizontalAlignment(JLabel.CENTER);
        ImageIcon iconOff = new ImageIcon(icon);
        ImageIcon iconOn = new ImageIcon(ImageUtil.luminanceScale(icon, BUTTON_HOVER_LUMINANCE));
        label.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                try {
                    onClick.run();
                } catch (Exception error) {}
            }
            @Override
            public void mouseEntered(MouseEvent e) {
                label.setCursor(new Cursor(Cursor.HAND_CURSOR));
                label.setIcon(iconOn);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                label.setIcon(iconOff);
            }
        });
        label.setIcon(iconOff);
        return label;
    }

    public static JLabel gearButton(String tooltip, Runnable onClick) {
        BufferedImage icon = ImageUtil.resizeImage(ImageUtil.loadImageResource(UIUtilities.class, "/preferences-icon.png"), 20, 20);
        return buildButton(ImageUtil.recolorImage(icon, ColorScheme.LIGHT_GRAY_COLOR), tooltip, onClick);
    }

    public static void addHoverIcons(AbstractButton button, Supplier<Icon> normal, Supplier<Icon> hover) {
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setIcon(hover.get());
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setIcon(normal.get());
            }
        });
    }

    /**
     * Returns true when the caller may proceed on the current (EDT) thread. Otherwise the task has
     * been scheduled via invokeLater and the caller must return immediately.
     */
    public static boolean ensureEdt(Runnable task) {
        if (SwingUtilities.isEventDispatchThread()) {
            return true;
        }
        SwingUtilities.invokeLater(task);
        return false;
    }

    public static String colorHex(Color color) {
        return String.format("#%06X", (0xFFFFFF & color.getRGB()));
    }

    public static JPanel darkPanel(LayoutManager layout, Color background) {
        JPanel panel = new JPanel(layout);
        panel.setBackground(background);
        return panel;
    }

    public static JPanel transparentPanel(LayoutManager layout) {
        JPanel panel = new JPanel(layout);
        panel.setOpaque(false);
        return panel;
    }

    public static JPanel verticalPanel(Color background) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(background);
        return panel;
    }

    public static void setFixedSize(JComponent component, int width, int height) {
        Dimension size = new Dimension(width, height);
        component.setPreferredSize(size);
        component.setMaximumSize(size);
    }

    public static void addVerticalGap(JPanel panel, int height) {
        panel.add(Box.createRigidArea(new Dimension(0, height)));
    }

    public static void addHorizontalGap(JPanel panel, int width) {
        panel.add(Box.createRigidArea(new Dimension(width, 0)));
    }

    public static JPanel formRow(String label, Component control) {
        JPanel panel = transparentPanel(new BorderLayout());
        panel.add(new JLabel(label), BorderLayout.LINE_START);
        panel.add(control, BorderLayout.LINE_END);
        return panel;
    }
}

