package com.runeassist.flip.ui;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.FlipV2;
import net.runelite.client.ui.FontManager;

import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

import static com.runeassist.flip.util.DateUtil.formatEpoch;

public class FlipPanel extends JPanel {
    private static final Color HOVER_BACKGROUND = RuneAssistColors.CARD.brighter();

    public FlipPanel(FlipV2 flip, RuneAssistConfig config, Runnable onClick) {
        this(flip, config, onClick, null);
    }

    public FlipPanel(FlipV2 flip, RuneAssistConfig config, Runnable onClick, Consumer<JPopupMenu> buildMenu) {
        setLayout(new BorderLayout());
        setBackground(RuneAssistColors.CARD);
        setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, 0, 1, 0, RuneAssistColors.HAIRLINE),
                BorderFactory.createEmptyBorder(4, 2, 4, 2)));

        JLabel itemNameLabel = new JLabel(UIUtilities.truncateString(flip.getCachedItemName(), 22));
        itemNameLabel.setForeground(Color.WHITE);
        itemNameLabel.setFont(FontManager.getRunescapeFont());

        JLabel qtyLabel = new JLabel(statusLine(flip));
        qtyLabel.setForeground(RuneAssistColors.MUTED);
        qtyLabel.setFont(FontManager.getRunescapeSmallFont());

        JPanel leftPanel = UIUtilities.verticalPanel(RuneAssistColors.CARD);
        leftPanel.add(itemNameLabel);
        leftPanel.add(qtyLabel);

        JLabel profitLabel = new JLabel(UIUtilities.formatProfit(flip.getProfit()));
        profitLabel.setForeground(UIUtilities.getProfitColor(flip.getProfit(), config));
        profitLabel.setFont(FontManager.getRunescapeSmallFont());
        profitLabel.setVerticalAlignment(SwingConstants.TOP);

        add(leftPanel, BorderLayout.CENTER);
        add(profitLabel, BorderLayout.EAST);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));

        String closeLabel = flip.getClosedQuantity() == flip.getOpenedQuantity() ? "Close time" : "Partial close time";
        long closedCostBasis = flip.getOpenedQuantity() <= 0
                ? 0
                : (flip.getSpent() * flip.getClosedQuantity()) / flip.getOpenedQuantity();
        String roiText = closedCostBasis > 0
                ? String.format("%.2f%%", ((double) flip.getProfit() / (double) closedCostBasis) * 100.0d)
                : "Unknown";
        Color profitColor = UIUtilities.getProfitColor(flip.getProfit(), config);
        String profitColorHex = UIUtilities.colorHex(profitColor);

        String tooltipText = String.format("<html>Profit: <font color='%s'>%s</font><br>ROI: <font color='%s'>%s</font><br>Avg buy price: <font color='#32A0FA'>%s</font><br>Avg sell price: <font color='#F0CF7B'>%s</font><br>Tax paid: <font color='#FFFFFF'>%s</font><br>Opened time: %s<br>%s: %s</html>",
                profitColorHex,
                UIUtilities.formatProfit(flip.getProfit()),
                profitColorHex,
                roiText,
                UIUtilities.formatProfit(flip.getAvgBuyPrice()),
                UIUtilities.formatProfit(flip.getAvgSellPrice()),
                UIUtilities.formatProfit(flip.getTaxPaid()),
                formatEpoch(flip.getOpenedTime()),
                closeLabel,
                formatEpoch(flip.getClosedTime()));
        setToolTipText(tooltipText);
        leftPanel.setToolTipText(tooltipText);
        qtyLabel.setToolTipText(tooltipText);
        itemNameLabel.setToolTipText(tooltipText);
        profitLabel.setToolTipText(tooltipText);

        Component[] clickableComponents = {this, leftPanel, qtyLabel, itemNameLabel, profitLabel};
        if (onClick != null || buildMenu != null) {
            MouseAdapter clickListener = new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    if (SwingUtilities.isRightMouseButton(e)) {
                        return;
                    }
                    if (onClick != null) {
                        onClick.run();
                    }
                }

                @Override
                public void mousePressed(MouseEvent e) {
                    maybeShowMenu(e, buildMenu);
                }

                @Override
                public void mouseReleased(MouseEvent e) {
                    maybeShowMenu(e, buildMenu);
                }

                @Override
                public void mouseEntered(MouseEvent e) {
                    setBackground(HOVER_BACKGROUND);
                    leftPanel.setBackground(HOVER_BACKGROUND);
                    for (Component component : clickableComponents) {
                        component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
                    }
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    setBackground(RuneAssistColors.CARD);
                    leftPanel.setBackground(RuneAssistColors.CARD);
                    for (Component component : clickableComponents) {
                        component.setCursor(Cursor.getDefaultCursor());
                    }
                }
            };

            for (Component component : clickableComponents) {
                component.addMouseListener(clickListener);
            }
        }
    }

    private void maybeShowMenu(MouseEvent e, Consumer<JPopupMenu> buildMenu) {
        if (buildMenu == null || !e.isPopupTrigger()) {
            return;
        }
        JPopupMenu menu = new JPopupMenu();
        buildMenu.accept(menu);
        if (menu.getComponentCount() > 0) {
            menu.show(e.getComponent(), e.getX(), e.getY());
        }
    }

    static String statusLine(FlipV2 flip) {
        if (flip.isClosed()) {
            return "Sold " + flip.getClosedQuantity() + " · " + closeTime(flip.getClosedTime());
        }
        String age = holdDuration(flip);
        return (flip.getClosedQuantity() > 0 ? "Part sold" : "Open") + (age == null ? "" : " · " + age);
    }

    private static String closeTime(int epoch) {
        if (epoch <= 0) return "Time unknown";
        return java.time.format.DateTimeFormatter.ofPattern("dd MMM HH:mm")
                .withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.ofEpochSecond(epoch));
    }

    private static String holdDuration(FlipV2 flip) {
        int start = flip.getOpenedTime();
        if (start <= 0) {
            return null;
        }
        int end = flip.isClosed() && flip.getClosedTime() > 0
                ? flip.getClosedTime()
                : (int) (System.currentTimeMillis() / 1000L);
        return UIUtilities.formatHoldDuration(end - start);
    }
}

package com.runeassist.flip.ui;

import java.util.Locale;
import java.awt.Font;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.BorderFactory;
import javax.swing.SwingConstants;
import java.awt.BorderLayout;
import java.awt.GridBagLayout;
import java.text.NumberFormat;
import net.runelite.client.ui.FontManager;
import com.runeassist.flip.model.Suggestion;

/** Presentation only: never changes eligibility, telemetry or trading decisions. */
final class SuggestionCardText {
    private SuggestionCardText() { }

    static void styleText(JLabel label, boolean heading) {
        label.setFont(FontManager.getRunescapeFont().deriveFont(heading ? Font.BOLD : Font.PLAIN,
                16f));
    }

    static String instruction(String action, String name, int quantity, long price, boolean priced) {
        NumberFormat numbers = NumberFormat.getIntegerInstance();
        String count = quantity > 0 ? " <font color='#FFFF00'>" + numbers.format(quantity) + "</font>" : "";
        String quote = priced ? "<br>for <font color='#FFFF00'>" + numbers.format(price) + "</font> gp" : "";
        return "<html><body width='104'><center>" + escape(action) + count + "<br>"
                + escape(name) + quote + "</center></body></html>";
    }

    /** Shared production layout also rendered by the visual regression harness. */
    static JPanel tradeBody(JLabel icon, JLabel instruction, JLabel profit) {
        JPanel body = new JPanel(new BorderLayout());
        body.setOpaque(false);
        JPanel centered = new JPanel(new GridBagLayout());
        centered.setOpaque(false);
        JPanel row = new JPanel(new BorderLayout(4, 0));
        row.setOpaque(false);
        icon.setBorder(BorderFactory.createEmptyBorder());
        row.add(icon, BorderLayout.WEST);
        instruction.setHorizontalAlignment(SwingConstants.CENTER);
        instruction.setForeground(RuneAssistColors.TEXT);
        row.add(instruction, BorderLayout.CENTER);
        centered.add(row);
        body.add(centered, BorderLayout.CENTER);
        profit.setHorizontalAlignment(SwingConstants.CENTER);
        profit.setBorder(BorderFactory.createEmptyBorder(5, 0, 4, 0));
        body.add(profit, BorderLayout.SOUTH);
        return body;
    }

    static String waitStatus(String message) {
        String text = message == null ? "" : message.toLowerCase(Locale.ROOT);
        if (text.contains("market data") && text.contains("unavailable")) return "Waiting for fresh prices";
        if (text.contains("unreachable") || text.contains("unavailable") || text.contains("offline")) {
            return "Reconnecting…";
        }
        if (text.contains("slots are full") || text.contains("slots full")) return "Waiting for offers to fill";
        if (text.contains("not enough coins")) return "More coins needed";
        if (text.contains("buy limit") || text.contains("buy-limit")) return "Waiting for buy limits";
        if (text.contains("paused")) return "Suggestions paused";
        if (text.contains("blocked every") || text.contains("skipped every")) return "No unblocked flips";
        return "Waiting for a suitable flip";
    }

    static String escape(String text) {
        return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    static String profitBasis(Suggestion suggestion) {
        if (suggestion == null) return "";
        if (suggestion.isSellSuggestion()) {
            return "Potential profit if the full quantity sells at this price, after tax. Not guaranteed.";
        }
        if (suggestion.isBuySuggestion()) {
            if (suggestion.getProfitEstimateBasis() == null
                    || "heuristic_net".equals(suggestion.getProfitEstimateBasis())) {
                return "Estimate from quotes, tax and a slippage allowance; not a calibrated expected return."
                        + " Partial fills and repricing can reduce profit.";
            }
            return "Estimated profit, not a guarantee. Partial fills and repricing can reduce profit.";
        }
        return "";
    }

    static String details(String message, String why) {
        String first = message == null ? "" : message.trim();
        String second = why == null ? "" : why.trim();
        if (first.isEmpty()) return escape(second);
        if (second.isEmpty() || first.equals(second)) return escape(first);
        return escape(first) + "<br>" + escape(second);
    }
}

