package com.runeassist.flip.ui;

import com.runeassist.flip.model.AccountStatus;
import com.runeassist.flip.model.AccountStatusManager;
import com.runeassist.flip.model.FlipManager;
import com.runeassist.flip.model.Offer;
import com.runeassist.flip.model.OfferStatus;
import com.runeassist.flip.model.StatusOfferList;
import net.runelite.client.ui.FontManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;

@Singleton
public class StatusStrip extends JPanel {
    private final AccountStatusManager accountStatusManager;
    private final FlipManager flipManager;
    private final JLabel line = new JLabel(" ");

    @Inject
    public StatusStrip(AccountStatusManager accountStatusManager, FlipManager flipManager) {
        this.accountStatusManager = accountStatusManager;
        this.flipManager = flipManager;
        setLayout(new BorderLayout());
        setBackground(RuneAssistColors.CARD);
        setBorder(RuneAssistColors.cardBorder());
        line.setForeground(RuneAssistColors.TEXT);
        line.setFont(FontManager.getRunescapeSmallFont());
        line.setHorizontalAlignment(SwingConstants.LEFT);
        add(line, BorderLayout.CENTER);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        setVisible(false);
    }

    public StatusStrip() {
        this(null, null);
    }

    public void setLineText(String text) {
        line.setText(text == null || text.isEmpty() ? " " : text);
    }

    public void refresh() {
        if (!UIUtilities.ensureEdt(this::refresh)) {
            return;
        }
        List<String> parts = new ArrayList<>();
        appendAged(parts);
        if (parts.isEmpty()) {
            setVisible(false);
            return;
        }
        setVisible(true);
        setLineText(String.join(" · ", parts));
    }

    private void appendSlots(List<String> parts) {
        AccountStatus status = safeStatus();
        if (status == null || status.getOffers() == null) {
            return;
        }
        int max = status.isWorldMember() || status.isAccountMember()
                ? StatusOfferList.NUM_SLOTS : StatusOfferList.NUM_F2P_SLOTS;
        int used = 0;
        for (Offer offer : status.getOffers()) {
            if (offer != null && offer.getStatus() != OfferStatus.EMPTY) {
                used++;
            }
        }
        parts.add(used + "/" + max + " slots");
    }

    private void appendAged(List<String> parts) {
        if (flipManager == null) {
            return;
        }
        int aged = flipManager.countOpenOlderThan(FlipManager.AGED_OPEN_SECONDS);
        if (aged > 0) parts.add(aged + (aged == 1 ? " position > 4h" : " positions > 4h"));
    }

    private void appendDeployed(List<String> parts) {
        AccountStatus status = safeStatus();
        if (status == null || status.getOffers() == null || status.getInventory() == null) {
            return;
        }
        long cashStack = status.currentCashStack();
        if (cashStack <= 0) {
            return;
        }
        long onMarket = status.getOffers().getGpOnMarket();
        int pct = (int) Math.round(100.0d * onMarket / (double) cashStack);
        pct = Math.max(0, Math.min(100, pct));
        parts.add(pct + "% deployed");
    }

    private AccountStatus safeStatus() {
        if (accountStatusManager == null) {
            return null;
        }
        try {
            return accountStatusManager.getAccountStatus();
        } catch (Throwable ignored) {
            // Throwable, not RuntimeException: reading the inventory off the client thread
            // raises an AssertionError under -ea, which is an Error and slipped straight past,
            // taking the panel -- and with it plugin startup -- down with it. This strip is
            // decoration; it renders without a status rather than stopping anything else.
            return null;
        }
    }
}

package com.runeassist.flip.ui;

import com.runeassist.flip.model.Suggestion;
import java.util.Objects;

/** Presentation state shared by client callbacks and Swing refreshes; WAIT only. */
final class WaitRefreshState {
    private Suggestion displayed;
    private Long account;

    synchronized void showing(Suggestion suggestion, Long accountHash) {
        clear();
        if (suggestion != null && suggestion.isWaitSuggestion() && accountHash != null) {
            displayed = suggestion;
            account = accountHash;
        }
    }

    synchronized boolean canKeepWhileRefreshing(Suggestion current, Long accountHash) {
        return displayed != null && displayed == current && current.isWaitSuggestion()
                && accountHash != null && Objects.equals(account, accountHash);
    }

    synchronized void clear() {
        displayed = null;
        account = null;
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.SortDirection;
import com.runeassist.flip.ui.*;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.List;
import java.util.function.*;

public class PaginatedTablePanel<T> extends JPanel {

    private static final Integer[] PAGE_SIZE_OPTIONS = {10, 25, 50, 100, 200, 500, 1000, 2000};

    private final String[] columnNames;
    private final Function<T, Object[]> rowMapper;
    private final DefaultTableModel tableModel;
    private final JTable table;
    private final JPanel topPanel;
    private final JPanel leftControls;
    private final JPanel rightControls;
    private final JPanel spinnerOverlay;
    private final Spinner spinner;
    private final JLayeredPane layeredPane;

    private List<T> rows = new ArrayList<>();

    public PaginatedTablePanel(String[] columnNames, Function<T, Object[]> rowMapper) {
        this(columnNames, rowMapper, 25);
    }

    public PaginatedTablePanel(String[] columnNames, Function<T, Object[]> rowMapper, int rowHeight) {
        this.columnNames = columnNames;
        this.rowMapper = rowMapper;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        topPanel = new JPanel(new BorderLayout());
        topPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topPanel.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));

        leftControls = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        leftControls.setBackground(ColorScheme.DARK_GRAY_COLOR);
        rightControls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
        rightControls.setBackground(ColorScheme.DARK_GRAY_COLOR);

        topPanel.add(leftControls, BorderLayout.WEST);
        topPanel.add(rightControls, BorderLayout.EAST);
        add(topPanel, BorderLayout.NORTH);

        tableModel = new DefaultTableModel(columnNames, 0) {
            @Override
            public boolean isCellEditable(int row, int column) {
                return false;
            }
        };

        table = new JTable(tableModel);
        table.setBackground(ColorScheme.DARK_GRAY_COLOR);
        table.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        table.setSelectionBackground(RuneAssistColors.ACCENT_MUTED);
        table.setSelectionForeground(Color.WHITE);
        table.setGridColor(ColorScheme.MEDIUM_GRAY_COLOR);
        table.setRowHeight(rowHeight);
        table.setAutoResizeMode(JTable.AUTO_RESIZE_ALL_COLUMNS);
        table.setRowSorter(null);
        table.getTableHeader().setReorderingAllowed(false);
        table.setFocusable(false);

        layeredPane = new JLayeredPane();
        layeredPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
        layeredPane.setOpaque(true);

        spinner = new Spinner();
        spinner.show();
        spinnerOverlay = new JPanel(new GridBagLayout());
        spinnerOverlay.setBackground(ColorScheme.DARK_GRAY_COLOR);
        spinnerOverlay.setOpaque(true);
        spinnerOverlay.add(spinner);
        spinnerOverlay.setVisible(false);

        JScrollPane scrollPane = new JScrollPane(table);
        scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
        scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);

        layeredPane.setLayout(new OverlayLayout(layeredPane));
        layeredPane.add(spinnerOverlay, JLayeredPane.MODAL_LAYER);
        layeredPane.add(scrollPane, JLayeredPane.DEFAULT_LAYER);
        add(layeredPane, BorderLayout.CENTER);
    }

    public JPanel leftControls() {
        return leftControls;
    }

    public JPanel rightControls() {
        return rightControls;
    }

    public JTable table() {
        return table;
    }

    public void setRenderer(TableCellRenderer renderer, int... columns) {
        for (int column : columns) {
            table.getColumnModel().getColumn(column).setCellRenderer(renderer);
        }
    }

    public void centerColumns(int... columns) {
        setRenderer(alignedRenderer(JLabel.CENTER), columns);
    }

    public void rightColumns(int... columns) {
        setRenderer(alignedRenderer(JLabel.RIGHT), columns);
    }

    public void moneyColumns(NumberFormat format, int... columns) {
        moneyColumns(format, false, columns);
    }

    public void moneyColumns(NumberFormat format, boolean centerStrings, int... columns) {
        setRenderer(moneyRenderer(format, centerStrings), columns);
    }

    public void profitColumns(NumberFormat format, RuneAssistConfig config, int... columns) {
        setRenderer(profitRenderer(format, config), columns);
    }

    public void gpColumns(NumberFormat format, boolean signed, int... columns) {
        setRenderer(gpRenderer(format, signed, null), columns);
    }

    public void gpProfitColumns(NumberFormat format, RuneAssistConfig config, int... columns) {
        setRenderer(gpRenderer(format, true, config), columns);
    }

    public void percentRoiColumns(RuneAssistConfig config, int... columns) {
        setRenderer(percentRoiRenderer(config), columns);
    }

    public void setTopControlsVisible(boolean visible) {
        topPanel.setVisible(visible);
    }

    public void enableBuiltInSorting() {
        table.setRowSorter(new TableRowSorter<>(tableModel));
    }

    public void installHeaderSort(Supplier<String> currentColumn,
                                  Supplier<SortDirection> currentDirection,
                                  BiConsumer<String, SortDirection> onSortChanged) {
        table.getTableHeader().addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                int columnIndex = table.getTableHeader().columnAtPoint(e.getPoint());
                if (columnIndex < 0 || columnIndex >= columnNames.length) {
                    return;
                }
                String clickedColumn = columnNames[columnIndex];
                SortDirection newDirection = SortDirection.DESC;
                if (clickedColumn.equals(currentColumn.get())) {
                    newDirection = currentDirection.get() == SortDirection.DESC
                            ? SortDirection.ASC : SortDirection.DESC;
                }
                onSortChanged.accept(clickedColumn, newDirection);
            }
        });
    }

    public void installPopupHandler(BiConsumer<MouseEvent, Integer> onPopup) {
        table.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (e.isPopupTrigger()) {
                    showPopup(e);
                }
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                if (e.isPopupTrigger()) {
                    showPopup(e);
                }
            }

            private void showPopup(MouseEvent e) {
                int viewRow = table.rowAtPoint(e.getPoint());
                if (viewRow < 0 || viewRow >= table.getRowCount()) {
                    return;
                }
                table.setRowSelectionInterval(viewRow, viewRow);
                onPopup.accept(e, table.convertRowIndexToModel(viewRow));
            }
        });
    }

    public void installPageFooter(Paginator paginatorPanel, int initialPageSize, IntConsumer onPageSizeChanged) {
        JComboBox<Integer> pageSizeComboBox = new JComboBox<>(PAGE_SIZE_OPTIONS);
        pageSizeComboBox.setSelectedItem(initialPageSize);
        pageSizeComboBox.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        pageSizeComboBox.setFocusable(false);
        pageSizeComboBox.setToolTipText("Page size");
        pageSizeComboBox.addActionListener(e -> onPageSizeChanged.accept((Integer) pageSizeComboBox.getSelectedItem()));

        JPanel bottomPanel = new JPanel(new BorderLayout());
        bottomPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JPanel pageSizePanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
        pageSizePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        pageSizePanel.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        JLabel pageSizeLabel = new JLabel("Page size:");
        pageSizeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        pageSizePanel.add(pageSizeLabel);
        pageSizePanel.add(pageSizeComboBox);

        paginatorPanel.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createEmptyBorder(0, 0, 0, pageSizePanel.getPreferredSize().width),
                paginatorPanel.getBorder()));
        bottomPanel.add(pageSizePanel, BorderLayout.WEST);
        bottomPanel.add(paginatorPanel, BorderLayout.CENTER);
        add(bottomPanel, BorderLayout.SOUTH);
    }

    public JLabel setSpinnerText(String text) {
        JLabel label = new JLabel(text);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(label.getFont().deriveFont(14f));
        JPanel loadingPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 10, 0));
        loadingPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        loadingPanel.setOpaque(false);
        loadingPanel.add(label);
        loadingPanel.add(spinner);
        spinnerOverlay.removeAll();
        spinnerOverlay.add(loadingPanel);
        spinnerOverlay.revalidate();
        spinnerOverlay.repaint();
        return label;
    }

    public void addOverlay(Component component, Integer layer) {
        layeredPane.add(component, layer);
    }

    public void setRows(List<T> newRows) {
        Runnable updateRows = () -> {
            rows = new ArrayList<>(newRows);
            tableModel.setRowCount(0);
            for (T row : rows) {
                tableModel.addRow(rowMapper.apply(row));
            }
            resizeAllColumns();
        };
        if (UIUtilities.ensureEdt(updateRows)) updateRows.run();
    }

    public T row(int modelRow) {
        return rows.get(modelRow);
    }

    public void setSpinnerVisible(boolean visible) {
        SwingUtilities.invokeLater(() -> {
            spinnerOverlay.setVisible(visible);
            table.setEnabled(!visible);
        });
    }

    private void resizeAllColumns() {
        for (int i = 0; i < table.getColumnCount(); i++) {
            resizeColumnWidth(i);
        }
    }

    private void resizeColumnWidth(int column) {
        TableColumn tableColumn = table.getColumnModel().getColumn(column);
        int preferredWidth = tableColumn.getMinWidth();
        int maxWidth = tableColumn.getMaxWidth();

        Component comp = table.getTableHeader().getDefaultRenderer()
                .getTableCellRendererComponent(table, tableColumn.getHeaderValue(), false, false, 0, column);
        preferredWidth = Math.max(comp.getPreferredSize().width + 10, preferredWidth);

        for (int row = 0; row < table.getRowCount(); row++) {
            comp = table.getCellRenderer(row, column)
                    .getTableCellRendererComponent(table, table.getValueAt(row, column), false, false, row, column);
            preferredWidth = Math.max(comp.getPreferredSize().width + 10, preferredWidth);
        }
        tableColumn.setPreferredWidth(Math.min(preferredWidth, maxWidth));
    }

    private static DefaultTableCellRenderer alignedRenderer(int alignment) {
        DefaultTableCellRenderer renderer = new DefaultTableCellRenderer();
        renderer.setHorizontalAlignment(alignment);
        return renderer;
    }

    private static DefaultTableCellRenderer moneyRenderer(NumberFormat format, boolean centerStrings) {
        return new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable table, Object value,
                                                           boolean isSelected, boolean hasFocus, int row, int column) {
                Component c = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
                if (value instanceof Long) {
                    setText(format.format(value));
                    setHorizontalAlignment(RIGHT);
                } else if (centerStrings && value instanceof String) {
                    setHorizontalAlignment(CENTER);
                }
                return c;
            }
        };
    }

    private static DefaultTableCellRenderer profitRenderer(NumberFormat format, RuneAssistConfig config) {
        return new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable table, Object value,
                                                           boolean isSelected, boolean hasFocus, int row, int column) {
                Component c = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
                if (value instanceof Long) {
                    long amount = (Long) value;
                    setText(format.format(amount));
                    setHorizontalAlignment(RIGHT);
                    if (!isSelected) {
                        setForeground(amount > 0 ? config.profitAmountColor()
                                : amount < 0 ? config.lossAmountColor()
                                : ColorScheme.LIGHT_GRAY_COLOR);
                    }
                }
                return c;
            }
        };
    }

    private static DefaultTableCellRenderer gpRenderer(NumberFormat format, boolean signed, RuneAssistConfig config) {
        return new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable table, Object value,
                                                           boolean isSelected, boolean hasFocus, int row, int column) {
                Component c = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
                setHorizontalAlignment(RIGHT);
                if (value instanceof Long) {
                    long amount = (Long) value;
                    setText((signed && amount > 0 ? "+" : "") + format.format(amount) + " gp");
                    if (config != null && !isSelected) {
                        setForeground(UIUtilities.getProfitColor(amount, config));
                    }
                } else {
                    setText(value == null ? "Unknown" : value.toString());
                }
                return c;
            }
        };
    }

    private static DefaultTableCellRenderer percentRoiRenderer(RuneAssistConfig config) {
        return new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable table, Object value,
                                                           boolean isSelected, boolean hasFocus, int row, int column) {
                Component c = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
                setHorizontalAlignment(RIGHT);
                if (value instanceof Double) {
                    double roi = (Double) value;
                    setText(String.format("%.2f%%", roi * 100.0d));
                    if (!isSelected) {
                        setForeground(UIUtilities.getProfitColor(roi, config));
                    }
                } else {
                    setText(value == null ? "Unknown" : value.toString());
                }
                return c;
            }
        };
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.controller.ApiRequestHandler;
import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.controller.ItemController;
import com.runeassist.flip.manager.PriceGraphConfigManager;
import com.runeassist.flip.model.*;
import com.runeassist.flip.ui.UIUtilities;
import com.runeassist.flip.ui.components.ItemSearchBox;
import com.runeassist.flip.ui.components.TrackingCardLayout;
import com.runeassist.flip.ui.graph.*;
import com.runeassist.flip.ui.graph.model.Data;
import com.runeassist.flip.ui.graph.model.PriceLine;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;


@Slf4j
public class PriceGraphPanel extends JPanel {

    // Dependencies
    private final ItemController itemController;
    private final ApiRequestHandler apiRequestHandler;
    private final OsrsLoginManager osrsLoginManager;
    private final PriceGraphConfigManager priceGraphConfigManager;
    private final SuggestionManager suggestionManager;

    // UI Components
    public final ItemSearchBox searchBox;
    private final JPanel contentPanel;
    private final JLabel errorLabel = new JLabel();
    private final GraphPanel graphPanel;
    private final StatsPanel statsPanel;
    private final TrackingCardLayout contentCardLayout = new TrackingCardLayout();
    private final JButton showSuggestionButton;

    // State
    private volatile int currentItemId;
    public volatile PriceLine offerPriceLine;


    // when isShowingSuggestionPriceData, the graph will auto update with the latest suggestion
    public volatile boolean isShowingSuggestionPriceData;
    public volatile Data suggestionPriceData;
    public volatile PriceLine suggestedPriceLine;


    public PriceGraphPanel(ItemController itemController,
                           PriceGraphConfigManager configManager,
                           RuneAssistConfig pluginConfig,
                           ApiRequestHandler apiRequestHandler,
                           OsrsLoginManager osrsLoginManager, SuggestionManager suggestionManager) {
        this.itemController = itemController;
        this.apiRequestHandler = apiRequestHandler;
        this.osrsLoginManager = osrsLoginManager;
        this.priceGraphConfigManager = configManager;
        this.suggestionManager = suggestionManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel topPanel = new JPanel(new BorderLayout());
        topPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topPanel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        JPanel searchPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 10, 0));
        searchPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel searchLabel = new JLabel("Search item:");
        searchLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        searchPanel.add(searchLabel);


        searchBox = new ItemSearchBox(
                (searchText, ignoredSet) -> itemController.search(searchText, itemController.allItemIds()),
                this::onItemSelected
        );
        searchBox.setPreferredSize(new Dimension(300, 30));
        searchPanel.add(searchBox);

        topPanel.add(searchPanel, BorderLayout.WEST);

        // Add the suggestion button to the right side
        JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 10, 0));
        rightPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        showSuggestionButton = new JButton("Switch to suggested item");
        showSuggestionButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        showSuggestionButton.setFocusable(false);
        showSuggestionButton.setVisible(!isShowingSuggestionPriceData);
        showSuggestionButton.addActionListener(e -> {
            searchBox.clear();
            showSuggestionPriceGraph();
        });
        rightPanel.add(showSuggestionButton);

        contentPanel = new JPanel(contentCardLayout);

        try {
            JLabel gearButton = UIUtilities.gearButton("Graph Settings", ()-> {
                if(contentCardLayout.getCurrentCard().equals(Cards.SETTINGS_CARD.name())) {
                    contentCardLayout.showPrevious(contentPanel);
                } else {
                    contentCardLayout.show(contentPanel, Cards.SETTINGS_CARD.name());
                }
            });
            rightPanel.add(gearButton, BorderLayout.EAST);
        } catch (Exception e) {
            log.error("error creating graph settings button", e);
        }

        topPanel.add(rightPanel, BorderLayout.EAST);

        add(topPanel, BorderLayout.NORTH);

        graphPanel = new GraphPanel(configManager);
        statsPanel = new StatsPanel(configManager, pluginConfig);
        statsPanel.setBackground(configManager.getConfig().backgroundColor);
        statsPanel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        contentPanel.add(DialogUi.centeredMessage("Search for item to see price graph", ColorScheme.DARK_GRAY_COLOR, true, 16f), Cards.LANDING_CARD.name());
        contentPanel.add(DialogUi.centeredMessage("Log into game to use price graphs.", ColorScheme.DARK_GRAY_COLOR, true, 16f), Cards.LOGIN_PROMPT.name());
        contentPanel.add(DialogUi.loadingCard("Loading price data...", ColorScheme.DARK_GRAY_COLOR), Cards.LOADING_CARD.name());
        contentPanel.add(DialogUi.splitGraphCard(graphPanel, statsPanel), Cards.GRAPH_CARD.name());
        contentPanel.add(DialogUi.errorCard(errorLabel, () -> {
            if (currentItemId > 0) {
                onItemSelected(currentItemId);
            }
        }), Cards.ERROR_CARD.name());
        contentPanel.add(new ConfigPanel(priceGraphConfigManager, () -> contentCardLayout.showPrevious(contentPanel)), Cards.SETTINGS_CARD.name());

        add(contentPanel, BorderLayout.CENTER);

        contentCardLayout.show(contentPanel, Cards.LANDING_CARD.name());
    }

    private void onItemSelected(Integer itemId) {
        if (itemId == null) {
            return;
        }
        if(osrsLoginManager.getPlayerDisplayName() == null) {
            contentCardLayout.show(contentPanel, Cards.LOGIN_PROMPT.name());
            return;
        }
        offerPriceLine = null;
        isShowingSuggestionPriceData = false;
        showSuggestionButton.setVisible(suggestionPriceData != null || suggestionManager.isGraphDataReadingInProgress());
        currentItemId = itemId;
        log.debug("Loading price graph for item: {}", itemId);
        contentCardLayout.show(contentPanel, Cards.LOADING_CARD.name());
        // Load the graph from the RuneAssist Ares backend.
        final PriceLine priceLine = offerPriceLine;
        apiRequestHandler.asyncGetRuneAssistGraph(itemId,
            (Data d) -> SwingUtilities.invokeLater(() -> {
                if (d == null || d.high1hTimes == null) showErrorCard("No price history for this item.");
                else showGraphCard(new DataManager(d, null), priceLine);
            }),
            (Throwable e) -> SwingUtilities.invokeLater(() -> showErrorCard("Price graph unavailable.")));
    }

    public void setLoadingCard() {
        contentCardLayout.show(contentPanel, Cards.LOADING_CARD.name());
    }

    public void setSuggestionPriceData(Data d) {
        suggestionPriceData = d;
        if (isShowingSuggestionPriceData) {
            if (d == null || d.lowLatestTimes == null) {
                showLandingCard();
                return;
            }
            DataManager dm = new DataManager(d, null);
            showGraphCard(dm, suggestedPriceLine);
        }
    }

    private void showErrorCard(String errorMessage) {
        showSuggestionButton.setVisible(false);
        errorLabel.setText("<html><center>" + errorMessage + "</center></html>");
        contentCardLayout.show(contentPanel, Cards.ERROR_CARD.name());
    }

    private void showGraphCard(DataManager dm, PriceLine suggestedPriceLine) {
        showSuggestionButton.setVisible(true);
        graphPanel.setData(dm, suggestedPriceLine);
        contentCardLayout.show(contentPanel, Cards.GRAPH_CARD.name());
        statsPanel.populate(dm, itemController);
    }

    public void showLandingCard() {
        showSuggestionButton.setVisible(false);
        if(osrsLoginManager.getPlayerDisplayName() == null) {
            contentCardLayout.show(contentPanel, Cards.LOGIN_PROMPT.name());
            return;
        }
        contentCardLayout.show(contentPanel, Cards.LANDING_CARD.name());
    }

    public void onTabShown() {
        String currentCard = contentCardLayout.getCurrentCard();
        if(currentCard.equals(Cards.LANDING_CARD.name()) || currentCard.equals(Cards.LOGIN_PROMPT.name())) {
            showLandingCard();
        }
    }

    public void showSuggestionPriceGraph() {
        isShowingSuggestionPriceData = true;
        showSuggestionButton.setVisible(false);
        if (suggestionPriceData != null) {
            setLoadingCard();
            setSuggestionPriceData(suggestionPriceData);
        }
    }

    public void newSuggestedItemId(int itemId, PriceLine suggestedPriceLine) {
        this.suggestedPriceLine = suggestedPriceLine;
        if (suggestionPriceData != null && suggestionPriceData.itemId != itemId) {
            suggestionPriceData = null;
            if (isShowingSuggestionPriceData) {
                showSuggestionPriceGraph();
            }
        }
    }

    enum Cards {
        LANDING_CARD,
        LOGIN_PROMPT,
        GRAPH_CARD,
        LOADING_CARD,
        ERROR_CARD,
        SETTINGS_CARD,
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.controller.ApiRequestHandler;
import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.controller.FlipHistorySyncService;
import com.runeassist.flip.controller.ItemController;
import com.runeassist.flip.manager.PriceGraphConfigManager;
import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.*;
import com.runeassist.flip.ui.graph.model.PriceLine;
import com.runeassist.flip.ui.RuneAssistColors;
import com.runeassist.flip.ui.RuneAssistTabbedPaneUI;
import com.google.inject.name.Named;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@Singleton
public class FlipsDialogController {

    private final ItemController itemController;
    private final ExecutorService executorService;
    private final RuneAssistConfig config;
    private final ApiRequestHandler apiRequestHandler;
    private final PriceGraphConfigManager priceGraphConfigManager;
    private final OsrsLoginManager osrsLoginManager;
    private final SuggestionManager suggestionManager;
    private final OsrsLoginRS osrsLoginRS;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;
    private final com.runeassist.flip.HeldCostTracker heldCostTracker;
    private final FlipHistorySyncService flipHistorySyncService;

    public PriceGraphPanel priceGraphPanel;
    private JTabbedPane tabbedPane;
    private JDialog dialog;
    private VisualizeFlipPanel visualizeFlipPanel;

    // Tab indices: Portfolio, Price graph, Visualize flip, Transactions, Analytics (web)
    private static final int TAB_PORTFOLIO = 0;
    private static final int TAB_PRICE_GRAPH = 1;
    private static final int TAB_VISUALIZE_FLIP = 2;
    private static final int TAB_TRANSACTIONS = 3;
    private static final int TAB_WEB_ANALYTICS = 4;

    @Inject
    public FlipsDialogController(
            @Named("runeAssistExecutor") ScheduledExecutorService executorService,
            ItemController itemController,
            RuneAssistConfig config,
            ApiRequestHandler apiRequestHandler,
            PriceGraphConfigManager priceGraphConfigManager,
            OsrsLoginManager osrsLoginManager,
            SuggestionManager suggestionManager,
            OsrsLoginRS osrsLoginRS,
            PortfolioStateRS portfolioStateRS,
            BankStateRS bankStateRS,
            com.runeassist.flip.HeldCostTracker heldCostTracker,
            FlipHistorySyncService flipHistorySyncService) {
        this.itemController = itemController;
        this.executorService = executorService;
        this.config = config;
        this.apiRequestHandler = apiRequestHandler;
        this.priceGraphConfigManager = priceGraphConfigManager;
        this.osrsLoginManager = osrsLoginManager;
        this.suggestionManager = suggestionManager;
        this.osrsLoginRS = osrsLoginRS;
        this.portfolioStateRS = portfolioStateRS;
        this.bankStateRS = bankStateRS;
        this.heldCostTracker = heldCostTracker;
        this.flipHistorySyncService = flipHistorySyncService;
    }

    public void initDialog(Window windowAncestor) {
        SwingUtilities.invokeLater(() -> {
            tabbedPane = new JTabbedPane();
            tabbedPane.setBackground(RuneAssistColors.SHELL);
            tabbedPane.setForeground(RuneAssistColors.ACCENT);
            tabbedPane.setOpaque(true);
            tabbedPane.setUI(new RuneAssistTabbedPaneUI());
            tabbedPane.setTabLayoutPolicy(JTabbedPane.SCROLL_TAB_LAYOUT);

            visualizeFlipPanel = new VisualizeFlipPanel(
                    itemController,
                    priceGraphConfigManager,
                    config,
                    apiRequestHandler,
                    flipHistorySyncService,
                    osrsLoginManager
            );
            PortfolioPanel portfolioPanel = new PortfolioPanel(
                    itemController,
                    config,
                    heldCostTracker,
                    flipHistorySyncService,
                    executorService,
                    suggestionManager,
                    osrsLoginRS,
                    portfolioStateRS,
                    bankStateRS,
                    itemId -> showPriceGraphTab(itemId, false, null)
            );
            priceGraphPanel = new PriceGraphPanel(
                    itemController,
                    priceGraphConfigManager,
                    config,
                    apiRequestHandler,
                    osrsLoginManager,
                    suggestionManager
            );
            TransactionsPanel transactionsPanel = new TransactionsPanel(
                    flipHistorySyncService,
                    itemController,
                    osrsLoginManager,
                    executorService
            );
            tabbedPane.addTab("Portfolio", portfolioPanel);
            tabbedPane.addTab("Price graph", priceGraphPanel);
            tabbedPane.addTab("Visualize flip", visualizeFlipPanel);
            tabbedPane.addTab("Transactions", transactionsPanel);
            tabbedPane.addTab("Analytics", new WebAnalyticsPanel(this::openWebAnalytics));

            JDialog dialog = new JDialog(windowAncestor);
            dialog.setTitle("RuneAssist Flipping");
            dialog.setResizable(true);
            dialog.setMinimumSize(new Dimension(800, 600));

            tabbedPane.addChangeListener(e -> {
                int selectedIndex = tabbedPane.getSelectedIndex();
                switch (selectedIndex) {
                    case TAB_PORTFOLIO:
                        portfolioPanel.onTabShown();
                        break;
                    case TAB_PRICE_GRAPH:
                        priceGraphPanel.onTabShown();
                        break;
                    case TAB_TRANSACTIONS:
                        transactionsPanel.onTabShown();
                        break;
                    default:
                        break;
                }
            });
            dialog.setContentPane(tabbedPane);

            GraphicsEnvironment env = GraphicsEnvironment.getLocalGraphicsEnvironment();
            Rectangle bounds = env.getMaximumWindowBounds(); // Excludes taskbar
            dialog.setSize(bounds.width, bounds.height);
            dialog.setLocation(bounds.x, bounds.y);

            this.dialog = dialog;
            dialog.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);
            dialog.setModalityType(Dialog.ModalityType.MODELESS);
            dialog.setVisible(false);
        });
    }

    public void showPriceGraphTab(Integer openOnPriceGraphItemId, boolean suggestionPriceGraph, PriceLine priceLine) {
        tabbedPane.setSelectedIndex(TAB_PRICE_GRAPH);
        if(openOnPriceGraphItemId != null) {
            priceGraphPanel.isShowingSuggestionPriceData = false;
            priceGraphPanel.searchBox.setItem(new ItemIdName(openOnPriceGraphItemId, itemController.getItemName(openOnPriceGraphItemId)));
            priceGraphPanel.offerPriceLine = priceLine;
        } else if (suggestionPriceGraph)  {
            priceGraphPanel.showSuggestionPriceGraph();
        } else {
            priceGraphPanel.showLandingCard();
        }
        dialog.setVisible(true);
    }

    public void openSuggestionPriceGraph() {
        Suggestion suggestion = suggestionManager.getSuggestion();
        if (config.priceGraphWebsite().equals(RuneAssistConfig.PriceGraphWebsite.RUNEASSIST)) {
            if (isSuggestionWithoutGraphData(suggestion)) {
                showPriceGraphTab(suggestion.getItemId(), false, null);
            } else if (suggestion != null && !suggestion.isWaitSuggestion()) {
                showPriceGraphTab(null, true, null);
            } else {
                showPriceGraphTab(null, false, null);
            }
            return;
        }

        if (suggestion == null || suggestion.isWaitSuggestion()) {
            return;
        }
        String url = config.priceGraphWebsite().getUrl(suggestion.getName(), suggestion.getItemId());
        LinkBrowser.browse(url);
    }

    private boolean isSuggestionWithoutGraphData(Suggestion suggestion) {
        if (suggestion == null || suggestion.isWaitSuggestion()) {
            return false;
        }
        // Fall back to a direct item fetch when the bundled/prefetched suggestion graph
        // is not ready yet (low-data mode, still in flight, or soft-failed attach).
        return priceGraphPanel == null || priceGraphPanel.suggestionPriceData == null
                || priceGraphPanel.suggestionPriceData.itemId != suggestion.getItemId();
    }


    public void showPortfolioTab() {
        tabbedPane.setSelectedIndex(TAB_PORTFOLIO);
        dialog.setVisible(true);
    }


    public void showWebAnalyticsTab() {
        tabbedPane.setSelectedIndex(TAB_WEB_ANALYTICS);
        dialog.setVisible(true);
    }

    /** Open website dashboard analytics (null section = full dashboard). */
    public void openWebAnalytics(String section) {
        LinkBrowser.browse(WebAnalyticsLinks.url(flipHistorySyncService.websiteUrl(), section));
    }

    public void showVisualizeFlip(FlipV2 flip) {
        if (flip == null) {
            return;
        }
        visualizeFlipPanel.showFlipVisualization(flip);
        tabbedPane.setSelectedIndex(TAB_VISUALIZE_FLIP);
        dialog.setVisible(true);
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.controller.FlipHistorySyncService;
import com.runeassist.flip.controller.ItemController;
import com.runeassist.flip.model.OfferStatus;
import com.runeassist.flip.model.OsrsLoginManager;
import com.runeassist.flip.model.Transaction;
import com.runeassist.flip.ui.Paginator;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

import static com.runeassist.flip.util.DateUtil.formatEpoch;

/** Lean FC TransactionsPanel: browse GE fills + delete/orphan via existing APIs. */
@Slf4j
public class TransactionsPanel extends JPanel {

    private static final String[] COLUMNS = {"Time", "Side", "Item", "Qty", "Price", "Spent"};
    private static final NumberFormat GP = NumberFormat.getIntegerInstance(Locale.US);
    private static final int PAGE_SIZE = 100;

    private final FlipHistorySyncService sync;
    private final ItemController itemController;
    private final OsrsLoginManager osrsLoginManager;
    private final ExecutorService executor;
    private final PaginatedTablePanel<Transaction> tablePanel;
    private final Paginator paginator;
    private final AtomicBoolean loading = new AtomicBoolean(false);

    private List<Transaction> all = Collections.emptyList();
    private int page = 1;

    public TransactionsPanel(
            FlipHistorySyncService sync,
            ItemController itemController,
            OsrsLoginManager osrsLoginManager,
            ExecutorService executor) {
        this.sync = sync;
        this.itemController = itemController;
        this.osrsLoginManager = osrsLoginManager;
        this.executor = executor;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        tablePanel = new PaginatedTablePanel<>(COLUMNS, this::toRow);
        tablePanel.installPopupHandler(this::showMenu);
        tablePanel.centerColumns(1, 3);
        tablePanel.moneyColumns(GP, 4, 5);

        paginator = new Paginator(n -> {
            page = n;
            renderPage();
        });
        tablePanel.installPageFooter(paginator, PAGE_SIZE, ignored -> {
            page = 1;
            paginator.setPageNumber(1);
            renderPage();
        });

        JButton refresh = new JButton("Refresh");
        refresh.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        refresh.setFocusable(false);
        refresh.addActionListener(e -> load(true));
        tablePanel.rightControls().add(refresh);

        add(tablePanel, BorderLayout.CENTER);
    }

    public void onTabShown() {
        load(false);
    }

    private void load(boolean force) {
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if (displayName == null || sync == null || !sync.isLinked()) {
            all = Collections.emptyList();
            page = 1;
            paginator.setPageNumber(1);
            tablePanel.setRows(Collections.emptyList());
            paginator.setTotalPages(1);
            return;
        }
        if (!force && !all.isEmpty()) {
            renderPage();
            return;
        }
        if (!loading.compareAndSet(false, true)) {
            return;
        }
        tablePanel.setSpinnerVisible(true);
        executor.execute(() -> {
            List<Transaction> rows;
            try {
                rows = sync.listTransactions(displayName);
            } catch (Exception e) {
                log.warn("transactions load failed: {}", e.getMessage());
                rows = Collections.emptyList();
            }
            List<Transaction> finalRows = rows != null ? rows : Collections.emptyList();
            List<Transaction> reversed = new ArrayList<>(finalRows);
            Collections.reverse(reversed);
            SwingUtilities.invokeLater(() -> {
                all = reversed;
                page = 1;
                paginator.setPageNumber(1);
                renderPage();
                tablePanel.setSpinnerVisible(false);
                loading.set(false);
            });
        });
    }

    private void renderPage() {
        int totalPages = Math.max(1, (all.size() + PAGE_SIZE - 1) / PAGE_SIZE);
        paginator.setTotalPages(totalPages);
        if (page > totalPages) {
            page = totalPages;
            paginator.setPageNumber(page);
        }
        int from = (page - 1) * PAGE_SIZE;
        int to = Math.min(all.size(), from + PAGE_SIZE);
        tablePanel.setRows(from >= to ? Collections.emptyList() : all.subList(from, to));
    }

    private Object[] toRow(Transaction tx) {
        String side = OfferStatus.BUY.equals(tx.getType()) ? "BUY" : "SELL";
        String item = itemController != null ? itemController.getItemName(tx.getItemId()) : String.valueOf(tx.getItemId());
        String time = tx.getTimestamp() != null
                ? formatEpoch((int) tx.getTimestamp().getEpochSecond())
                : "";
        return new Object[]{time, side, item, tx.getQuantity(), tx.getPrice(), tx.getAmountSpent()};
    }

    private void showMenu(MouseEvent e, int modelRow) {
        Transaction tx = tablePanel.row(modelRow);
        if (tx == null || tx.getId() == null) {
            return;
        }
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if (displayName == null || sync == null || !sync.isLinked()) {
            return;
        }
        JPopupMenu menu = new JPopupMenu();
        JMenuItem orphan = new JMenuItem("Remove from flip");
        orphan.addActionListener(evt -> {
            if (JOptionPane.showConfirmDialog(this,
                    "Remove this transaction from its flip? Flip profit will update.",
                    "Confirm", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) {
                return;
            }
            sync.orphanTransaction(displayName, tx.getId());
            all = new ArrayList<>(all);
            all.removeIf(t -> tx.getId().equals(t.getId()));
            renderPage();
        });
        menu.add(orphan);

        JMenuItem delete = new JMenuItem("Delete transaction");
        delete.addActionListener(evt -> {
            if (JOptionPane.showConfirmDialog(this,
                    "Delete this transaction? Related flips will update.",
                    "Confirm", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) {
                return;
            }
            sync.deleteTransaction(displayName, tx.getId());
            all = new ArrayList<>(all);
            all.removeIf(t -> tx.getId().equals(t.getId()));
            renderPage();
        });
        menu.add(delete);
        menu.show(e.getComponent(), e.getX(), e.getY());
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.HeldCostTracker;
import com.runeassist.flip.controller.FlipHistorySyncService;
import com.runeassist.flip.controller.ItemController;
import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.*;
import com.runeassist.flip.ui.RuneAssistColors;
import com.runeassist.flip.ui.UIUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableCellRenderer;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import java.util.List;

@Slf4j
public class PortfolioPanel extends JPanel {
    private static final NumberFormat GP_FORMAT = NumberFormat.getNumberInstance(Locale.US);
    private static final NumberFormat INT_FORMAT = NumberFormat.getIntegerInstance(Locale.US);
    private static final String CONTENT_CARD = "content";
    private static final String LOGIN_PROMPT_CARD = "login";
    private static final String[] COLUMN_NAMES = {
            "Item", "Market value", "Quantity", "Unrealized Profit", "Unrealized ROI", "Avg buy price", "Time held"
    };

    private static final Map<String, Comparator<PortfolioItemCardData>> SORT_COMPARATORS = new HashMap<>();
    static {
        SORT_COMPARATORS.put("Item", Comparator.comparing(
                PortfolioItemCardData::getItemName, Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER)));
        // Numeric columns pre-reversed so default DESC shows largest-first
        SORT_COMPARATORS.put("Market value", Comparator.<PortfolioItemCardData>comparingLong(
                i -> i.getPostTaxSellUnitPrice() * (long) i.getPortfolioQuantity()).reversed());
        SORT_COMPARATORS.put("Quantity", Comparator.comparingInt(PortfolioItemCardData::getPortfolioQuantity).reversed());
        SORT_COMPARATORS.put("Avg buy price", Comparator.comparingLong(PortfolioItemCardData::getUnitBuyPrice).reversed());
        SORT_COMPARATORS.put("Time held", Comparator.comparingInt(PortfolioItemCardData::getHeldMinutes));
        SORT_COMPARATORS.put("Unrealized Profit", Comparator.comparingLong(PortfolioItemCardData::portfolioUnrealizedProfit).reversed());
        SORT_COMPARATORS.put("Unrealized ROI", Comparator.comparing(
                PortfolioPanel::calculateUnrealizedRoi,
                Comparator.nullsLast(Comparator.<Double>naturalOrder().reversed())));
    }

    private final ItemController itemController;
    private final RuneAssistConfig config;
    private final HeldCostTracker heldCostTracker;
    private final FlipHistorySyncService flipHistorySyncService;
    private final ExecutorService executorService;
    private final SuggestionManager suggestionManager;
    private final OsrsLoginRS osrsLoginRS;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;
    private final Consumer<Integer> openPriceGraph;
    private final CardLayout cardLayout;
    private final JPanel cardPanel;
    private final JPanel summaryTablePanel;
    private final PaginatedTablePanel<PortfolioItemCardData> tablePanel;
    private final JLabel autoSyncInfoLabel;
    private final JButton clearPortfolioButton;
    private final Map<Integer, ImageIcon> itemIconCache = new ConcurrentHashMap<>();

    private List<PortfolioItemCardData> currentItems = new ArrayList<>();
    private String sortColumn = "Market value";
    private SortDirection sortDirection = SortDirection.DESC;

    public PortfolioPanel(ItemController itemController,
                          RuneAssistConfig config,
                          HeldCostTracker heldCostTracker,
                          FlipHistorySyncService flipHistorySyncService,
                          ExecutorService executorService,
                          SuggestionManager suggestionManager,
                          OsrsLoginRS osrsLoginRs,
                          PortfolioStateRS portfolioStateRS,
                          BankStateRS bankStateRS,
                          Consumer<Integer> openPriceGraph) {
        this.itemController = itemController;
        this.config = config;
        this.heldCostTracker = heldCostTracker;
        this.flipHistorySyncService = flipHistorySyncService;
        this.executorService = executorService;
        this.suggestionManager = suggestionManager;
        this.osrsLoginRS = osrsLoginRs;
        this.portfolioStateRS = portfolioStateRS;
        this.bankStateRS = bankStateRS;
        this.openPriceGraph = openPriceGraph;

        setLayout(new BorderLayout(0, 12));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        cardLayout = new CardLayout();
        cardPanel = new JPanel(cardLayout);
        cardPanel.setOpaque(false);

        JPanel contentPanel = plain(new BorderLayout(0, 12));
        contentPanel.setBorder(new EmptyBorder(8, 0, 0, 0));

        JPanel summarySection = plain(new BorderLayout(28, 0));
        summarySection.setBorder(new EmptyBorder(0, 0, 10, 0));
        summaryTablePanel = plain(new GridLayout(0, 2, 24, 10));
        summaryTablePanel.setBorder(new EmptyBorder(4, 0, 4, 0));
        summarySection.add(summaryTablePanel, BorderLayout.WEST);

        clearPortfolioButton = new JButton("Remove everything from portfolio");
        clearPortfolioButton.setFont(FontManager.getRunescapeFont());
        clearPortfolioButton.setFocusable(false);
        clearPortfolioButton.addActionListener(e -> onClearPortfolioClicked());

        JPanel rightControls = plain(new BorderLayout());
        rightControls.setBorder(new EmptyBorder(0, 12, 0, 0));
        JPanel syncWrap = plain(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        autoSyncInfoLabel = new JLabel();
        autoSyncInfoLabel.setForeground(RuneAssistColors.ACCENT);
        autoSyncInfoLabel.setFont(FontManager.getRunescapeFont());
        autoSyncInfoLabel.setHorizontalAlignment(SwingConstants.LEFT);
        syncWrap.add(autoSyncInfoLabel);
        rightControls.add(syncWrap, BorderLayout.SOUTH);
        summarySection.add(rightControls, BorderLayout.CENTER);
        contentPanel.add(summarySection, BorderLayout.NORTH);

        tablePanel = new PaginatedTablePanel<>(COLUMN_NAMES, this::toRow, 40);
        tablePanel.rightControls().add(clearPortfolioButton);
        tablePanel.installHeaderSort(() -> sortColumn, () -> sortDirection, (col, dir) -> {
            sortColumn = col;
            sortDirection = dir;
            renderTable();
        });
        tablePanel.installPopupHandler((e, row) -> showPortfolioMenu(e, tablePanel.row(row)));
        tablePanel.rightColumns(2, 6);
        tablePanel.gpColumns(GP_FORMAT, false, 1, 5);
        tablePanel.gpProfitColumns(GP_FORMAT, config, 3);
        tablePanel.percentRoiColumns(config, 4);
        tablePanel.setRenderer(itemCellRenderer(), 0);
        contentPanel.add(tablePanel, BorderLayout.CENTER);

        cardPanel.add(contentPanel, CONTENT_CARD);
        cardPanel.add(DialogUi.centeredMessage(
                "Log into the game to see account portfolio", null, false, 18f), LOGIN_PROMPT_CARD);
        add(cardPanel, BorderLayout.CENTER);

        portfolioStateRS.registerListener(state -> SwingUtilities.invokeLater(() -> {
            if (osrsLoginRS.get().loggedIn) {
                renderFromState(state);
            }
        }));
        osrsLoginRS.registerListener(state -> SwingUtilities.invokeLater(this::refresh));
        bankStateRS.registerListener(state -> SwingUtilities.invokeLater(this::refreshAutoSyncLabel));
        refresh();
    }

    public void onTabShown() {
        refresh();
    }

    private void refresh() {
        if (!osrsLoginRS.get().loggedIn) {
            cardLayout.show(cardPanel, LOGIN_PROMPT_CARD);
            clearPortfolioButton.setEnabled(false);
            revalidate();
            repaint();
            return;
        }
        cardLayout.show(cardPanel, CONTENT_CARD);
        clearPortfolioButton.setEnabled(true);
        refreshAutoSyncLabel();
        renderFromState(portfolioStateRS.get());
    }

    private void onClearPortfolioClicked() {
        String displayName = osrsLoginRS.get().displayName;
        if (displayName == null) {
            return;
        }
        if (JOptionPane.showConfirmDialog(this,
                "Are you sure you want to remove all items from your portfolio?",
                "Confirm", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) {
            return;
        }
        clearPortfolioButton.setEnabled(false);
        executorService.execute(() -> {
            mutatePortfolio(
                    () -> flipHistorySyncService.clearPortfolio(displayName),
                    () -> heldCostTracker.clearLots(displayName),
                    "cleared portfolio via server for " + displayName,
                    "cleared {} tracked units from local portfolio");
            SwingUtilities.invokeLater(() -> clearPortfolioButton.setEnabled(true));
        });
    }

    private void refreshAutoSyncLabel() {
        String text = bankStateRS.get().isLoaded()
                ? "Bank loaded. Full quantity syncing enabled. Note: items are excluded from syncing whilst active in one of your Grand Exchange slots."
                : "Please open your bank once to enable more accurate quantity syncing.";
        autoSyncInfoLabel.setText(
                "<html><div style='width: 560px; text-align: left;'>" + text + "</div></html>");
    }

    private void renderFromState(PortfolioState state) {
        currentItems = new ArrayList<>();
        for (PortfolioItemCardData item : state.getItemCardDataByItemId().values()) {
            if (item.isInPortfolio()) {
                currentItems.add(item);
            }
        }
        renderSummary(state.getSummaryData(), currentItems.size());
        renderTable();
        revalidate();
        repaint();
    }

    private void renderSummary(PortfolioSummaryData data, int totalItems) {
        summaryTablePanel.removeAll();
        if (data == null) {
            return;
        }
        addSummaryRow("Portfolio Market Value", formatGp(data.getPortfolioMarketValue(), false), config.profitAmountColor());
        addSummaryRow("Unrealized Profit", formatGp(data.getUnrealizedProfit(), true),
                UIUtilities.getProfitColor(data.getUnrealizedProfit(), config));
        addSummaryRow("Cash Value", formatGp(data.getCashValue(), false));
        addSummaryRow("Cash in Buy Offers", formatGp(data.getLockedBuyCash(), false));
        addSummaryRow("Assets Value", formatGp(data.getAssetsValue(), false));
        addSummaryRow("Unique Items in Portfolio", INT_FORMAT.format(totalItems));
    }

    private void addSummaryRow(String label, String value) {
        addSummaryRow(label, value, ColorScheme.LIGHT_GRAY_COLOR);
    }

    private void addSummaryRow(String label, String value, Color valueColor) {
        JLabel key = new JLabel(label);
        key.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        key.setFont(FontManager.getRunescapeFont());
        JLabel val = new JLabel(value, SwingConstants.RIGHT);
        val.setForeground(valueColor);
        val.setFont(FontManager.getRunescapeBoldFont());
        summaryTablePanel.add(key);
        summaryTablePanel.add(val);
    }

    private void renderTable() {
        List<PortfolioItemCardData> sorted = new ArrayList<>(currentItems);
        FilterSortUtil.sort(sorted, SORT_COMPARATORS, sortColumn, sortDirection);
        tablePanel.setRows(sorted);
    }

    private Object[] toRow(PortfolioItemCardData item) {
        long avgBuy = item.getUnitBuyPrice();
        return new Object[]{
                new ItemCell(item.getItemId(), item.getItemName()),
                item.getPostTaxSellUnitPrice() * item.getPortfolioQuantity(),
                INT_FORMAT.format(item.getPortfolioQuantity()),
                item.portfolioUnrealizedProfit(),
                calculateUnrealizedRoi(item),
                avgBuy > 0 ? avgBuy : null,
                UIUtilities.formatDurationMinutes(item.getHeldMinutes())
        };
    }

    private void showPortfolioMenu(MouseEvent e, PortfolioItemCardData item) {
        JPopupMenu menu = new JPopupMenu();
        addMenu(menu, "Show price graph", () -> openPriceGraph.accept(item.getItemId()));
        int qty = item.getPortfolioQuantity();
        if (qty > 0) {
            addMenu(menu, "Remove from portfolio", () -> removeFromPortfolio(item.getItemId(), 0));
        }
        if (qty > 1) {
            addMenu(menu, "Remove X from portfolio", () -> promptRemoveQuantity(item.getItemId()));
        }
        menu.show(e.getComponent(), e.getX(), e.getY());
    }

    private void promptRemoveQuantity(int itemId) {
        String input = JOptionPane.showInputDialog(
                this, "Quantity to remove:", "Remove from portfolio", JOptionPane.PLAIN_MESSAGE);
        if (input == null) {
            return;
        }
        try {
            int qty = Integer.parseInt(input.trim());
            if (qty > 0) {
                removeFromPortfolio(itemId, qty);
            }
        } catch (NumberFormatException ignored) {
        }
    }

    /** quantity <= 0 removes all tracked lots for the item. */
    private void removeFromPortfolio(int itemId, int quantity) {
        String displayName = osrsLoginRS.get().displayName;
        if (displayName == null) {
            return;
        }
        executorService.execute(() -> mutatePortfolio(
                () -> flipHistorySyncService.toggleItemPortfolio(displayName, itemId, quantity, 0L, true),
                () -> heldCostTracker.removeLots(displayName, itemId, quantity),
                "removed item " + itemId + " qty " + quantity + " from server portfolio",
                "removed {} x item " + itemId + " from local portfolio"));
    }

    private void mutatePortfolio(BooleanSupplier serverOp, IntSupplier localOp, String serverLog, String localLog) {
        if (flipHistorySyncService != null && flipHistorySyncService.isLinked() && serverOp.getAsBoolean()) {
            log.info(serverLog);
            return;
        }
        log.info(localLog, localOp.getAsInt());
        suggestionManager.setSuggestionNeeded(true);
    }

    private static void addMenu(JPopupMenu menu, String label, Runnable action) {
        JMenuItem item = new JMenuItem(label);
        item.addActionListener(e -> action.run());
        menu.add(item);
    }

    private DefaultTableCellRenderer itemCellRenderer() {
        return new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(
                    JTable table, Object value, boolean isSelected, boolean hasFocus, int row, int column) {
                JLabel label = (JLabel) super.getTableCellRendererComponent(
                        table, value, isSelected, hasFocus, row, column);
                if (!(value instanceof ItemCell)) {
                    label.setIcon(null);
                    return label;
                }
                ItemCell cell = (ItemCell) value;
                label.setText(cell.name);
                ImageIcon cached = itemIconCache.get(cell.itemId);
                if (cached != null) {
                    label.setIcon(cached);
                    return label;
                }
                label.setIcon(null);
                itemController.loadImage(cell.itemId, image -> {
                    if (image != null) {
                        itemIconCache.put(cell.itemId, new ImageIcon(image));
                        SwingUtilities.invokeLater(table::repaint);
                    }
                });
                return label;
            }
        };
    }

    private String formatGp(long amount, boolean signed) {
        return (signed && amount > 0 ? "+" : "") + GP_FORMAT.format(amount) + " gp";
    }

    private static Double calculateUnrealizedRoi(PortfolioItemCardData item) {
        if (item.getUnrealizedUnitProfit() == null) {
            return null;
        }
        long unitBuyPrice = item.getPostTaxSellUnitPrice() - item.getUnrealizedUnitProfit();
        return unitBuyPrice <= 0 ? null
                : (double) item.getUnrealizedUnitProfit() / (double) unitBuyPrice;
    }

    private static JPanel plain(LayoutManager layout) {
        JPanel panel = new JPanel(layout);
        panel.setOpaque(false);
        return panel;
    }

    private static final class ItemCell {
        final int itemId;
        final String name;

        ItemCell(int itemId, String name) {
            this.itemId = itemId;
            this.name = name;
        }
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.controller.ApiRequestHandler;
import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.controller.FlipHistorySyncService;
import com.runeassist.flip.controller.ItemController;
import com.runeassist.flip.manager.PriceGraphConfigManager;
import com.runeassist.flip.model.FlipV2;
import com.runeassist.flip.model.OsrsLoginManager;
import com.runeassist.flip.model.VisualizeFlipResponse;
import com.runeassist.flip.ui.graph.*;
import com.runeassist.flip.ui.graph.model.Data;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;
import java.util.Collections;
import java.util.function.Consumer;

@Slf4j
public class VisualizeFlipPanel extends JPanel {

    private final ItemController itemController;
    private final ApiRequestHandler apiRequestHandler;
    private final FlipHistorySyncService flipHistorySyncService;
    private final OsrsLoginManager osrsLoginManager;

    private final JLabel errorLabel = new JLabel();
    private final GraphPanel graphPanel;
    private final FlipStatsPanel statsPanel;
    private final CardLayout contentCardLayout = new CardLayout();

    private volatile FlipV2 currentFlip;

    public VisualizeFlipPanel(ItemController itemController,
                              PriceGraphConfigManager configManager,
                              RuneAssistConfig pluginConfig,
                              ApiRequestHandler apiRequestHandler,
                              FlipHistorySyncService flipHistorySyncService,
                              OsrsLoginManager osrsLoginManager) {
        this.itemController = itemController;
        this.apiRequestHandler = apiRequestHandler;
        this.flipHistorySyncService = flipHistorySyncService;
        this.osrsLoginManager = osrsLoginManager;

        setLayout(contentCardLayout);
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        graphPanel = new GraphPanel(configManager);
        statsPanel = new FlipStatsPanel(configManager, pluginConfig);
        statsPanel.setBackground(configManager.getConfig().backgroundColor);
        statsPanel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        add(DialogUi.centeredMessage("Open a flip from the side panel to visualize it here.", ColorScheme.DARK_GRAY_COLOR, true, 16f), Cards.LANDING_CARD.name());
        add(DialogUi.loadingCard("Loading price data...", ColorScheme.DARK_GRAY_COLOR), Cards.LOADING_CARD.name());
        add(DialogUi.splitGraphCard(graphPanel, statsPanel), Cards.GRAPH_CARD.name());
        add(DialogUi.errorCard(errorLabel, () -> {
            if (currentFlip != null) {
                showFlipVisualization(currentFlip);
            }
        }), Cards.ERROR_CARD.name());

        contentCardLayout.show(this, Cards.LANDING_CARD.name());
    }

    public void showFlipVisualization(FlipV2 flip) {
        if (flip == null) {
            return;
        }
        currentFlip = flip;
        contentCardLayout.show(this, Cards.LOADING_CARD.name());
        Consumer<String> onFailure = (String errorMessage) -> {
            SwingUtilities.invokeLater(() -> showErrorCard(errorMessage));
        };
        Consumer<VisualizeFlipResponse> onSuccess = (VisualizeFlipResponse d) -> {
            if (d == null) {
                onFailure.accept("No price data available for this item.");
                return;
            }
            if (d.getGraphData() == null || !d.getGraphData().hasPriceSeries()) {
                apiRequestHandler.asyncGetRuneAssistGraph(flip.getItemId(),
                    (Data graph) -> {
                        if (graph == null || !graph.hasPriceSeries()) {
                            String message = d.getMessage();
                            onFailure.accept(message == null || message.isEmpty()
                                    ? "No price data available for this item."
                                    : message);
                            return;
                        }
                        d.graphData = graph;
                        d.graphData.clearPredictionData();
                        SwingUtilities.invokeLater(() -> showGraphCard(new DataManager(d.getGraphData(), d), flip));
                    },
                    (Throwable e) -> {
                        String message = d.getMessage();
                        onFailure.accept(message == null || message.isEmpty()
                                ? "No price data available for this item."
                                : message);
                    });
                return;
            }
            d.graphData.clearPredictionData();
            SwingUtilities.invokeLater(() -> showGraphCard(new DataManager(d.getGraphData(), d), flip));
        };

        String displayName = flipHistorySyncService == null ? null : flipHistorySyncService.displayNameForAccount(flip.getAccountId());
        if (displayName != null && flipHistorySyncService != null
                && flipHistorySyncService.isOsrsLinked(displayName)
                && flip.getId() != null) {
            flipHistorySyncService.asyncVisualizeFlip(displayName, flip.getId(), onSuccess, (err) -> {
                log.debug("server visualize flip failed, falling back to FlipV2 aggregates: {}", err);
                loadAggregateOverlay(flip, onSuccess, onFailure);
            });
            return;
        }
        loadAggregateOverlay(flip, onSuccess, onFailure);
    }

    /** Post-diet fallback: graph + FlipV2 buy/sell aggregates (no local lot ledger). */
    private void loadAggregateOverlay(FlipV2 flip,
                                      Consumer<VisualizeFlipResponse> onSuccess,
                                      Consumer<String> onFailure) {
        apiRequestHandler.asyncGetRuneAssistGraph(flip.getItemId(),
            (Data d) -> {
                if (d == null || !d.hasPriceSeries()) {
                    onFailure.accept("No price history for this item.");
                    return;
                }
                d.clearPredictionData();
                onSuccess.accept(VisualizeFlipResponse.fromLocalLots(d, flip, Collections.emptyList()));
            },
            (Throwable e) -> {
                String detail = e != null && e.getMessage() != null && !e.getMessage().isEmpty()
                        ? e.getMessage()
                        : "check your connection and try again";
                log.warn("visualize flip graph failed for item {}", flip.getItemId(), e);
                onFailure.accept("Could not load price history from RuneAssist (" + detail + ").");
            });
    }

    private void showErrorCard(String errorMessage) {
        errorLabel.setText("<html><center>" + errorMessage + "</center></html>");
        contentCardLayout.show(this, Cards.ERROR_CARD.name());
    }

    private void showGraphCard(DataManager dm, FlipV2 f) {
        graphPanel.setData(dm);
        contentCardLayout.show(this, Cards.GRAPH_CARD.name());
        statsPanel.populate(f, itemController);
    }

    enum Cards {
        LANDING_CARD,
        GRAPH_CARD,
        LOADING_CARD,
        ERROR_CARD
    }
}

package com.runeassist.flip.ui.flipsdialog;

import com.runeassist.flip.ui.Spinner;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.awt.*;

final class DialogUi {
    private DialogUi() {
    }

    static JPanel centeredMessage(String message, Color background, boolean opaque, float fontSize) {
        JPanel panel = new JPanel(new GridBagLayout());
        panel.setOpaque(opaque);
        if (background != null) {
            panel.setBackground(background);
        }
        JLabel label = new JLabel(message);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(label.getFont().deriveFont(fontSize));
        label.setHorizontalAlignment(SwingConstants.CENTER);
        label.setMinimumSize(label.getPreferredSize());
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.weightx = 1.0;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        panel.add(label, gbc);
        return panel;
    }

    static JPanel loadingCard(String message, Color background) {
        JLabel loadingLabel = new JLabel(message);
        Spinner spinner = new Spinner();
        JPanel loadingPanel = new JPanel(new GridBagLayout());
        GridBagConstraints gbc = new GridBagConstraints();

        loadingLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        loadingLabel.setFont(loadingLabel.getFont().deriveFont(14f));
        loadingPanel.setBackground(background);
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.insets = new Insets(10, 10, 10, 10);
        spinner.show();
        loadingPanel.add(spinner, gbc);
        gbc.gridy = 1;
        loadingPanel.add(loadingLabel, gbc);
        return loadingPanel;
    }

    static JPanel errorCard(JLabel errorLabel, Runnable onRetry) {
        errorLabel.setForeground(Color.RED);
        errorLabel.setFont(errorLabel.getFont().deriveFont(14f));
        errorLabel.setHorizontalAlignment(SwingConstants.CENTER);
        JPanel errorPanel = new JPanel(new GridBagLayout());
        errorPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.insets = new Insets(10, 10, 10, 10);
        errorPanel.add(errorLabel, gbc);
        gbc.gridy = 1;
        gbc.insets = new Insets(20, 10, 10, 10);
        JButton retryButton = new JButton("Retry");
        retryButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        retryButton.setFocusable(false);
        retryButton.addActionListener(e -> onRetry.run());
        errorPanel.add(retryButton, gbc);
        return errorPanel;
    }

    static JSplitPane splitGraphCard(Component graph, Component stats) {
        JSplitPane splitPane = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, true);
        splitPane.setLeftComponent(graph);
        splitPane.setRightComponent(stats);
        splitPane.setResizeWeight(0.95);
        splitPane.setDividerLocation(0.95);
        splitPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
        return splitPane;
    }
}

package com.runeassist.flip.ui.flipsdialog;

/**
 * Deep links into the RuneAssist website dashboard. Heavy flip analytics (profit
 * graph, item breakdown, flip history, stale/attention) live on the web so the
 * plugin stays under the Plugin Hub review token budget.
 */
public final class WebAnalyticsLinks {

    public static final String SECTION_PROFIT = "profit";
    public static final String SECTION_FLIPS = "flips";
    public static final String SECTION_ITEMS = "items";
    public static final String SECTION_ATTENTION = "attention";
    public static final String SECTION_ACCOUNTS = "accounts";

    private WebAnalyticsLinks() {
    }

    /**
     * @param websiteBaseUrl e.g. {@code https://runeassist.com/app/} (trailing slash optional)
     * @param section        one of the SECTION_* constants, or null/blank for the dashboard root
     */
    public static String url(String websiteBaseUrl, String section) {
        String base = normalizeBase(websiteBaseUrl);
        if (section == null || section.trim().isEmpty()) {
            return base + "#/dashboard";
        }
        String s = section.trim().toLowerCase();
        if (SECTION_ACCOUNTS.equals(s)) {
            return base + "#/accounts";
        }
        return base + "#/dashboard?section=" + s;
    }

    static String normalizeBase(String websiteBaseUrl) {
        if (websiteBaseUrl == null || websiteBaseUrl.trim().isEmpty()) {
            return "https://runeassist.com/app/";
        }
        return websiteBaseUrl.endsWith("/") ? websiteBaseUrl : websiteBaseUrl + "/";
    }
}

