    public void fetchSlotItemPrice(boolean isViewingSlot, Supplier<OfferEditor> offerEditorSupplier) {
        if (isViewingSlot) {
            var currentItemId = client.getVarpValue(CURRENT_GE_ITEM);
            offerManager.setViewedSlotItemId(currentItemId);
            if (currentItemId == -1 || currentItemId == 0) return;

            var suggestion = suggestionManager.getSuggestion();
            if (suggestion != null && suggestion.isModifySuggestion()
                    && suggestion.getItemId() != currentItemId) {
                // Offer editor is on a different item than the MODIFY card — do not
                // treat it as a custom quote (that looks like a new BUY/SELL).
                viewedSlotPriceErrorText = null;
                highlightController.redraw();
                return;
            }
            if (suggestion != null && suggestion.getItemId() == currentItemId &&
                    Objects.equals(suggestion.offerType(), getOfferType())) {
                offerManager.setViewedSlotItemPrice(suggestion.getPrice());
                return;
            }

            // Price an item the suggestion engine didn't propose via Ares /v1/market/quote.
            // Blocks on HTTP, so run off the client thread and marshal the result back.
            // Quote may include a wiki-feature hint in "message" (freshness / confidence) —
            // same offer-editor slot FC fills from ItemPrice.message, without a closed quant.
            viewedSlotPriceErrorText = "Loading price...";
            final int itemIdForQuote = currentItemId;
            executorService.execute(() -> {
                Map<String, Object> q;
                try { q = market.quote(itemIdForQuote); } catch (Exception e) { q = null; }
                final Map<String, Object> fq = q;
                clientThread.invoke(() -> {
                    if (fq == null) {
                        viewedSlotPriceErrorText = "No price data for this item.";
                        return;
                    }
                    Object hint = fq.get("message");
                    if (hint instanceof String && !((String) hint).isEmpty()) {
                        viewedSlotPriceErrorText = (String) hint;
                    } else {
                        viewedSlotPriceErrorText = null;
                    }
                    Number buyAt = fq.get("buy_at") instanceof Number ? (Number) fq.get("buy_at") : null;
                    Number sellAt = fq.get("sell_at") instanceof Number ? (Number) fq.get("sell_at") : null;
                    if (buyAt == null && sellAt == null) {
                        viewedSlotPriceErrorText = "No price data for this item.";
                        return;
                    }
                    long price = isSelling()
                        ? (sellAt != null ? sellAt.longValue() : buyAt.longValue())
                        : (buyAt != null ? buyAt.longValue() : sellAt.longValue());
                    if (price <= 0) {
                        viewedSlotPriceErrorText = "No price data for this item.";
                        return;
                    }
                    offerManager.setViewedSlotItemPrice(price);

                    highlightController.redraw();
                    log.debug("fetched item {} price: {}", offerManager.getViewedSlotItemId(), price);

                    // todo: Usage of OfferEditor is messy. It mutates a widget so we need to get the original instance
                    //  of it which is created downstream on some other event handler path. This is why we use a supplier
                    //  but probably it should be an injected class of some kind. We should clean this up in the future
                    //  but for now just need it to work as currently broken.

                    OfferEditor flippingWidget = offerEditorSupplier.get();
                    if (flippingWidget != null) {
                        String warn = viewedSlotPriceErrorText;
                        if (warn != null && (warn.startsWith("Loading") || warn.startsWith("No price"))) {
                            flippingWidget.showPrice(price);
                        } else {
                            flippingWidget.showPrice(price, warn);
                        }
                    }
                });
            });

        } else {
            // Do not clear viewedSlotItemId/Price here. TRADINGPOST_SEARCH goes back to -1 as soon
            // as an item is picked from search — before the quantity/price screen — so clearing
            // would wipe the custom-item quote before the quick-set keybind can use it. The cached
            // quote is replaced the next time isViewingSlot is true for a different item.
            viewedSlotPriceErrorText = null;
        }
        highlightController.redraw();
    }

    public boolean isSettingQuantity() {
        var chatboxTitleWidget = getChatboxTitleWidget();
        if (chatboxTitleWidget == null) return false;
        String chatInputText = chatboxTitleWidget.getText();
        return chatInputText.equals("How many do you wish to buy?") || chatInputText.equals("How many do you wish to sell?");
    }

    public boolean isSettingPrice() {
        var chatboxTitleWidget = getChatboxTitleWidget();
        if (chatboxTitleWidget == null) return false;
        String chatInputText = chatboxTitleWidget.getText();

        var offerTextWidget = getOfferTextWidget();
        if (offerTextWidget == null) return false;
        String offerText = offerTextWidget.getText();
        return chatInputText.equals("Set a price for each item:") && (offerText.equals("Buy offer") || offerText.equals("Sell offer"));
    }


    private Widget getChatboxTitleWidget() {
        return client.getWidget(ComponentID.CHATBOX_TITLE);
    }

    private Widget getOfferTextWidget() {
        var offerContainerWidget = client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER);
        if (offerContainerWidget == null) return null;
        return offerContainerWidget.getChild(GE_OFFER_INIT_STATE_CHILD_ID);
    }

    public boolean isSelling() {
        return client.getVarbitValue(Varbits.GE_OFFER_CREATION_TYPE) == 1;
    }

    public boolean isBuying() {
        return client.getVarbitValue(Varbits.GE_OFFER_CREATION_TYPE) == 0;
    }

    public String getOfferType() {
        if (isBuying()) {
            return "buy";
        } else if (isSelling()) {
            return "sell";
        } else {
            return null;
        }
    }

    public void setSuggestedAction(Suggestion suggestion) {
        var currentItemId = client.getVarpValue(CURRENT_GE_ITEM);

        if (isSettingQuantity()) {
            if (suggestion == null || currentItemId != suggestion.getItemId()) {
                return;
            }
            setChatboxValue(suggestion.getQuantity());
        } else if (isSettingPrice()) {
            long price = -1;
            if (suggestion == null || currentItemId != suggestion.getItemId()
                    || !Objects.equals(suggestion.offerType(), getOfferType())) {
                if (offerManager.getViewedSlotItemId() != currentItemId) {
                    return;
                }
                price = offerManager.getViewedSlotItemPrice();
            } else {
                price = suggestion.getPrice();
            }

            if (price == -1) return;

            setChatboxValue(price);
        }
    }

    public void setChatboxValue(long value) {
        var chatboxInputWidget = client.getWidget(ComponentID.CHATBOX_FULL_INPUT);
        if (chatboxInputWidget == null) return;
        chatboxInputWidget.setText(value + "*");
        client.setVarcStrValue(VarClientStr.INPUT_TEXT, String.valueOf(value));
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.*;
import com.runeassist.flip.util.ProfitCalculator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SlotProfitColorizer {

    private static final int GE_SLOT_COUNT = 8;
    private static final int FIRST_SLOT_CHILD_ID = 7; // Slots are children 7-14 (0-7)
    private static final int PRICE_TEXT_WIDGET_CHILD_INDEX = 25; // Child index within each slot that contains price text
    private static final int DETAIL_VIEW_CHILD_ID = 15; // Detail view when a slot is opened
    private static final int DETAIL_PRICE_TEXT_CHILD_INDEX = 25; // Price text within detail view
    private static final int OFFER_SETUP_CHILD_ID = 26; // Offer setup screen (buy/sell)
    private static final int OFFER_SETUP_PRICE_TEXT_CHILD_INDEX = 41; // Price text within offer setup

    private static final String DEFAULT_COLOR = "ff981f"; // Game's default orange color for slot overview
    private static final String DETAIL_AND_SETUP_DEFAULT_COLOR = "ffb83f"; // Default color for detail view and offer setup

    private final Client client;
    private final RuneAssistConfig config;
    private final OfferManager offerManager;
    private final GrandExchange grandExchange;
    private final ProfitCalculator profitCalculator;

    private SavedOffer getOffer(int slotIndex) {
        try {
            long accountHash = client.getAccountHash();
            return offerManager.loadOffer(accountHash, slotIndex);
        } catch (Exception e) {
            log.debug("Error loading offer for slot {}", slotIndex, e);
            return null;
        }
    }

    public void updateAllSlots() {
        if (!config.slotPriceColorEnabled()) {
            return;
        }

        int openSlot = grandExchange.getOpenSlot();
        if (openSlot > -1) {
            if (grandExchange.isSetupOfferOpen()) {
                updateOfferSetup();
            } else {
                updateDetailView(openSlot);
            }
            return;
        }

        for (int slotIndex = 0; slotIndex < GE_SLOT_COUNT; slotIndex++) {
            updateOverviewSlot(slotIndex);
        }
    }

    private void updateOverviewSlot(int slotIndex) {
        try {
            Widget slotWidget = getSlotWidget(slotIndex);
            Widget priceTextWidget = getPriceTextWidget(slotWidget);

            updatePriceTextColor(priceTextWidget, slotIndex, Color.decode("#" + DEFAULT_COLOR));
        } catch (Exception e) {
            log.error("Error updating slot {} price color", slotIndex, e);
        }
    }

    private void updateDetailView(int openSlot) {
        if (openSlot == -1) {
            return;
        }

        try {
            Widget detailViewWidget = client.getWidget(InterfaceID.GE_OFFERS, DETAIL_VIEW_CHILD_ID);
            Widget priceTextWidget = detailViewWidget != null ? detailViewWidget.getChild(DETAIL_PRICE_TEXT_CHILD_INDEX) : null;

            updatePriceTextColor(priceTextWidget, openSlot, Color.decode("#" + DETAIL_AND_SETUP_DEFAULT_COLOR));
        } catch (Exception e) {
            log.debug("Error updating detail view price color", e);
        }
    }

    private void updatePriceTextColor(Widget priceTextWidget, int slotIndex, Color defaultColor) {
        if (!hasValidText(priceTextWidget)) {
            return;
        }

        Color targetColor = defaultColor;

        if (!isBuyOffer(slotIndex)) {
            targetColor = determineProfitColor(calculateSlotProfit(slotIndex), defaultColor);
        } else if (isOfferTracked(slotIndex)) {
            targetColor = config.slotPriceProfitableColor();
        }

        priceTextWidget.setText(applyColorTag(priceTextWidget.getText(), targetColor));
    }

    private void updateOfferSetup() {
        try {
            Widget offerSetupWidget = client.getWidget(InterfaceID.GE_OFFERS, OFFER_SETUP_CHILD_ID);
            if (offerSetupWidget == null || offerSetupWidget.isHidden()) {
                return;
            }

            Widget priceTextWidget = offerSetupWidget.getChild(OFFER_SETUP_PRICE_TEXT_CHILD_INDEX);
            if (priceTextWidget == null) {
                return;
            }

            Color defaultColor = Color.decode("#" + DETAIL_AND_SETUP_DEFAULT_COLOR);
            Color color = determineOfferSetupColor(defaultColor);

            priceTextWidget.setTextColor(color.getRGB() & 0xFFFFFF);
        } catch (Exception e) {
            log.debug("Error updating offer setup price color", e);
        }
    }

    private Color determineOfferSetupColor(Color defaultColor) {
        if (!grandExchange.isOfferTypeSell()) {
            // For buy offers, show profitable if we have a tracked price and the price matches it.
            int viewedItemId = offerManager.getViewedSlotItemId();
            long viewedItemPrice = offerManager.getViewedSlotItemPrice();
            if (viewedItemId > 0 && viewedItemPrice > 0 && grandExchange.getOfferPrice() == viewedItemPrice) {
                return config.slotPriceProfitableColor();
            }

            return defaultColor;
        }

        int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
        if (itemId <= 0) {
            // Modify (and inventory sell) never go through search.
            itemId = grandExchange.getCurrentItemId();
        }
        if (itemId <= 0) {
            return defaultColor;
        }

        // For sell offers, calculate profit based on the current price
        Long profit = profitCalculator.calculateProfitPerItem(itemId, grandExchange.getOfferPrice());

        return determineProfitColor(profit, defaultColor);
    }

    private Color determineProfitColor(Long profit, Color defaultColor) {
        if (profit == null || profit == 0) {
            return defaultColor;
        }

        if (profit < 0) {
            return config.slotPriceUnprofitableColor();
        } else {
            return config.slotPriceProfitableColor();
        }
    }

    public void resetAllSlots() {
        for (int slotIndex = 0; slotIndex < GE_SLOT_COUNT; slotIndex++) {
            resetSlot(slotIndex);
        }

        resetDetailView();
        resetOfferSetup();
    }

    private void resetSlot(int slotIndex) {
        try {
            Widget slotWidget = getSlotWidget(slotIndex);
            Widget priceTextWidget = getPriceTextWidget(slotWidget);

            if (!hasValidText(priceTextWidget)) {
                return;
            }

            resetWidgetTextColor(priceTextWidget, DEFAULT_COLOR);
        } catch (Exception e) {
            log.error("Error resetting slot {} price color", slotIndex, e);
        }
    }

    private void resetDetailView() {
        try {
            Widget detailViewWidget = client.getWidget(InterfaceID.GE_OFFERS, DETAIL_VIEW_CHILD_ID);
            Widget priceTextWidget = detailViewWidget != null ? detailViewWidget.getChild(DETAIL_PRICE_TEXT_CHILD_INDEX) : null;

            if (!hasValidText(priceTextWidget)) {
                return;
            }

            resetWidgetTextColor(priceTextWidget, DETAIL_AND_SETUP_DEFAULT_COLOR);
        } catch (Exception e) {
            log.debug("Error resetting detail view price color", e);
        }
    }

    public void resetOfferSetup() {
        try {
            Widget offerSetupWidget = client.getWidget(InterfaceID.GE_OFFERS, OFFER_SETUP_CHILD_ID);
            if (offerSetupWidget == null) {
                return;
            }

            Widget priceTextWidget = offerSetupWidget.getChild(OFFER_SETUP_PRICE_TEXT_CHILD_INDEX);
            if (priceTextWidget == null) {
                return;
            }

            priceTextWidget.setTextColor(Integer.parseInt(DETAIL_AND_SETUP_DEFAULT_COLOR, 16));
        } catch (Exception e) {
            log.debug("Error resetting offer setup price color", e);
        }
    }

    private Long calculateSlotProfit(int slotIndex) {
        try {
            return profitCalculator.calculateSlotProfit(slotIndex);
        } catch (Exception e) {
            log.debug("Error calculating profit for slot {}", slotIndex, e);
            return null;
        }
    }

    private boolean isBuyOffer(int slotIndex) {
        try {
            // First try to get it from SavedOffer
            SavedOffer savedOffer = getOffer(slotIndex);
            if (savedOffer != null) {
                return savedOffer.getOfferStatus() == OfferStatus.BUY;
            }

            // Fallback to current GE offer
            GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
            if (offers != null && slotIndex < offers.length) {
                GrandExchangeOffer currentOffer = offers[slotIndex];
                if (currentOffer != null) {
                    GrandExchangeOfferState state = currentOffer.getState();
                    return state == GrandExchangeOfferState.BUYING
                            || state == GrandExchangeOfferState.BOUGHT
                            || state == GrandExchangeOfferState.CANCELLED_BUY;
                }
            }
        } catch (Exception e) {
            log.debug("Error determining offer type for slot {}", slotIndex, e);
        }

        return false; // Default to sell if unknown
    }

    private boolean isOfferTracked(int slotIndex) {
        return getOffer(slotIndex) != null;
    }

    private String applyColorTag(String text, Color determinedColor) {
        return "<col=" + colorToHex(determinedColor) + ">" + stripColorTags(text) + "</col>";
    }

    private String stripColorTags(String text) {
        if (text == null) {
            return "";
        }

        // Remove <col=XXXXXX> and </col> tags
        return text.replaceAll("<col=[0-9a-fA-F]{6}>", "").replaceAll("</col>", "");
    }

    private String colorToHex(Color color) {
        return String.format("%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
    }

    private Widget getSlotWidget(int slotIndex) {
        return client.getWidget(InterfaceID.GE_OFFERS, FIRST_SLOT_CHILD_ID + slotIndex);
    }

    private Widget getPriceTextWidget(Widget slotWidget) {
        if (slotWidget == null) {
            return null;
        }

        return slotWidget.getChild(PRICE_TEXT_WIDGET_CHILD_INDEX);
    }

    private boolean hasValidText(Widget widget) {
        if (widget == null) {
            return false;
        }

        String text = widget.getText();
        return text != null && !text.isEmpty();
    }

    private void resetWidgetTextColor(Widget widget, String defaultColor) {
        String plainText = stripColorTags(widget.getText());
        widget.setText("<col=" + defaultColor + ">" + plainText + "</col>");
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.ItemIdName;
import com.runeassist.flip.ui.FuzzySearchScorer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.ToDoubleFunction;
import java.util.stream.Collectors;
import java.util.stream.IntStream;


@Slf4j
@Singleton
public class ItemController {

    public static final int COINS_ITEM_ID = 995;
    public static final int PLATINUM_TOKENS_ITEM_ID = 13204;
    // dependencies
    private final FuzzySearchScorer fuzzySearchScorer;
    private final Client client;
    private final ItemManager itemManager;
    private final ClientThread clientThread;

    // state
    private final Map<Integer, String> cachedItemNames = new ConcurrentHashMap<>();
    private volatile List<ItemIdName> cachedItems = new ArrayList<>(); // volatile used to guarantee immediate visibility across threads on re-assignment
    private final AtomicBoolean initScheduled = new AtomicBoolean(false);

    @Inject
    public ItemController(Client client,
                          ClientThread clientThread,
                          ItemManager itemManager,
                          FuzzySearchScorer fuzzySearchScorer,
                          ScheduledExecutorService executorService) {
        this.fuzzySearchScorer = fuzzySearchScorer;
        this.client = client;
        this.itemManager = itemManager;
        this.clientThread = clientThread;

        Runnable initItems = () -> {
            // only allow one init attempt at a time
            if(initScheduled.compareAndSet(false, true)) {
                clientThread.invokeLater(() -> {
                    List<ItemIdName> items = IntStream.range(0, client.getItemCount())
                            .mapToObj(itemManager::getItemComposition)
                            .filter(item -> item.isGeTradeable() && item.getNote() == -1)
                            .map(i -> new ItemIdName(i.getId(), i.getName()))
                            .collect(Collectors.toList());
                    if (!items.isEmpty()) {
                        cachedItems = items;
                        cachedItems.forEach(i -> cachedItemNames.put(i.itemId, i.name));
                        initScheduled.set(false);
                        log.debug("initialised {} items", items.size());
                        return true;
                    }
                    // if no items are found try again
                    return false;
                });
            }
        };

        // re-init every 5 mins just in case new items are added without restart
        executorService.scheduleAtFixedRate(initItems, 0, 5, TimeUnit.MINUTES);
    }

    public List<ItemIdName> search(String input, Set<Integer> existingSelectedItems) {

        if(input == null || input.isBlank()) {
            return cachedItems.stream()
                    .sorted(Comparator.comparing((ItemIdName i) -> !existingSelectedItems.contains(i.itemId)).thenComparing(i -> i.name))
                    .collect(Collectors.toList());
        }

        ToDoubleFunction<ItemIdName> comparator = fuzzySearchScorer.comparator(input);
        return cachedItems.stream()
                .filter(item -> comparator.applyAsDouble(item) > 0)
                .sorted(Comparator.comparing((ItemIdName i) -> !existingSelectedItems.contains(i.itemId)).thenComparing(Comparator.comparingDouble(comparator).reversed()
                        .thenComparing(i -> i.name)))
                .collect(Collectors.toList());
    }


    public Set<Integer> allItemIds() {
        return cachedItemNames.keySet();
    }

    public String getItemName(Integer itemId) {
        return cachedItemNames.getOrDefault(itemId, "Name unavailable");
    }

    public void loadImage(Integer itemId, Consumer<AsyncBufferedImage> c) {
        clientThread.invokeLater(() -> {
            c.accept(itemManager.getImage(itemId));
        });
    }

    public int toUnnotedItemId(int itemId) {
        ItemComposition composition = itemManager.getItemComposition(itemId);
        if (composition != null && composition.getNote() != -1 && composition.getLinkedNoteId() > 0) {
            return composition.getLinkedNoteId();
        }
        return itemId;
    }

    public long totalCash(Map<Integer, Integer> itemQuantities) {
        if (itemQuantities == null) {
            return 0L;
        }
        return itemQuantities.getOrDefault(COINS_ITEM_ID, 0)
                + (long) itemQuantities.getOrDefault(PLATINUM_TOKENS_ITEM_ID, 0) * 1000L;
    }

    public Map<Integer, Integer> getRunliteInventory() {
        return buildRuneliteItemMap(InventoryID.INVENTORY);
    }

    public Map<Integer, Integer> getRunliteBankInventory() {
        return buildRuneliteItemMap(InventoryID.BANK);
    }

    private Map<Integer, Integer> buildRuneliteItemMap(InventoryID inventoryID) {
        ItemContainer container = client.getItemContainer(inventoryID);
        if (container == null) {
            return null;
        }
        Map<Integer, Integer> totals = new HashMap<>();
        for (Item item : container.getItems()) {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
                continue;
            }
            Integer unnotedTradeableItemId = toUnnotedTradeableItemId(item.getId());
            if (unnotedTradeableItemId == null) {
                continue;
            }
            totals.merge(unnotedTradeableItemId, item.getQuantity(), Integer::sum);
        }
        return totals;
    }

    private Integer toUnnotedTradeableItemId(int itemId) {
        int unnotedItemId = toUnnotedItemId(itemId);
        if (unnotedItemId == COINS_ITEM_ID || unnotedItemId == PLATINUM_TOKENS_ITEM_ID) {
            return unnotedItemId;
        }
        ItemComposition unnoted = itemManager.getItemComposition(unnotedItemId);
        if (unnoted == null || !unnoted.isGeTradeable()) {
            return null;
        }
        return unnotedItemId;
    }
}

package com.runeassist.flip.controller;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.inject.Singleton;
import com.runeassist.flip.model.ComposeSuggestionMapper;
import com.runeassist.flip.model.ComposeSuggestionResponse;
import com.runeassist.flip.model.Suggestion;
import com.runeassist.flip.ui.graph.model.Data;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Live HTTP to RuneAssist Ares for price graphs and the dump-alert stream.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ApiRequestHandler {

    private static final String UA = "RuneAssist-flip/1.0";
    private static final String ARES_ORIGIN = "https://runeassist.com";
    private static final String DUMP_ALERTS = ARES_ORIGIN + "/v1/dump-alerts";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient client;
    private final Gson gson;

    /**
     * Fetch an item's price-history graph from RuneAssist's backend (JSON matching {@link Data}).
     */
    public Call asyncGetRuneAssistGraph(int itemId, Consumer<Data> onData, Consumer<Throwable> onError) {
        Request request = new Request.Builder()
                .url(ARES_ORIGIN + "/v1/graph?id=" + itemId)
                .header("User-Agent", UA)
                .build();
        Call graphCall = client.newBuilder().callTimeout(15, TimeUnit.SECONDS).build().newCall(request);
        graphCall.enqueue(new Callback() {
            @Override
            public void onFailure(Call call, java.io.IOException e) {
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) {
                try (Response r = response) {
                    if (!r.isSuccessful() || r.body() == null) {
                        onError.accept(new RuntimeException("graph HTTP " + r.code()));
                        return;
                    }
                    Data d = gson.fromJson(r.body().charStream(), Data.class);
                    if (d == null) {
                        onError.accept(new RuntimeException("empty graph"));
                        return;
                    }
                    onData.accept(d);
                } catch (Exception ex) {
                    onError.accept(ex);
                }
            }
        });
        return graphCall;
    }

    /**
     * Open a long-lived dump-alert stream ({@code POST /v1/dump-alerts}). The response is
     * handed to {@code onSuccess} still open — frames are uvarint-length JSON
     * {@code {suggestion}} objects (keepalive = zero-length frame), matching Flipping
     * Copilot's dump-alert framing with JSON instead of protobuf.
     *
     * @param filters dumpMinPredictedProfit / f2pOnly / blockedIds / capital / remainingSlots
     */
    public Call asyncConsumeDumpAlerts(
            Map<String, Object> filters,
            Consumer<Response> onSuccess,
            Consumer<Throwable> onFailure) {
        String bodyJson = gson.toJson(filters != null ? filters : Map.of());
        Request request = new Request.Builder()
                .url(DUMP_ALERTS)
                .header("User-Agent", UA)
                .post(RequestBody.create(JSON, bodyJson))
                .build();

        Call call = client.newBuilder()
                .readTimeout(15, TimeUnit.SECONDS)
                .callTimeout(0, TimeUnit.MILLISECONDS)
                .build()
                .newCall(request);

        call.enqueue(new Callback() {
            @Override
            public void onFailure(Call call, java.io.IOException e) {
                onFailure.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) {
                if (!response.isSuccessful() || response.body() == null) {
                    int code = response.code();
                    response.close();
                    onFailure.accept(new RuntimeException("dump-alerts HTTP " + code));
                    return;
                }
                onSuccess.accept(response);
            }
        });
        return call;
    }

    /**
     * Decode one dump-alert JSON frame into a {@link Suggestion}, or null if unusable.
     */
    public Suggestion decodeDumpSuggestionFrame(byte[] payload) {
        if (payload == null || payload.length == 0) {
            return null;
        }
        try {
            JsonObject root = gson.fromJson(new String(payload, java.nio.charset.StandardCharsets.UTF_8), JsonObject.class);
            if (root == null || !root.has("suggestion")) {
                return null;
            }
            ComposeSuggestionResponse.SuggestionDto dto =
                    gson.fromJson(root.get("suggestion"), ComposeSuggestionResponse.SuggestionDto.class);
            return ComposeSuggestionMapper.toSuggestion(dto, "ares-dump");
        } catch (Exception e) {
            log.warn("dump frame decode failed: {}", e.getMessage());
            return null;
        }
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.HeldItemSyncStateRS;
import com.runeassist.flip.ui.OfferEditor;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.*;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.InterfaceID;


@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GameUiChangesHandler {
    private static final int SCRIPT_GE_COLLECT = 782;
    private static final int SCRIPT_GE_SLOT_REDRAW = 804;
    private static final String BANK_TAG_TAB_VIEW_OPTION = "View tag tab";
    // Bank tag tab widgets exist before bank item bounds settle.
    // Wait one full frame before resolving the highlight target.
    private static final int BANK_REBUILD_HIGHLIGHT_REDRAW_DELAY_FRAMES = 2;

    // dependencies
    private final ClientThread clientThread;
    private final Client client;
    private final GePreviousSearch gePreviousSearch;
    private final HighlightController highlightController;
    private final SuggestionManager suggestionManager;
    private final GrandExchange grandExchange;
    private final OfferManager offerManager;
    private final OfferHandler offerHandler;
    private final SlotProfitColorizer slotProfitColorizer;
    private final HeldItemSyncStateRS heldItemSyncStateRS;
    private final RuneAssistConfig config;
    private final AccountStatusManager accountStatusManager;
    private final net.runelite.client.plugins.PluginManager pluginManager;
    private final FlipHistorySyncService flipHistorySyncService;
    // state
    boolean quantityOrPriceChatboxOpen;
    boolean itemSearchChatboxOpen = false;
    int bankRebuildHighlightRedrawFramesRemaining = 0;
    @Getter
    OfferEditor flippingWidget = null;

    public void onVarClientIntChanged(VarClientIntChanged event) {
        if (event.getIndex() == VarClientID.CHAT_LASTREBUILD) {
            // this is triggered when a bank tag tab is opened/closed
            requestBankRebuildHighlightRedraw();
        }

        if (event.getIndex() == VarClientID.MESLAYERMODE
                && client.getVarcIntValue(VarClientID.MESLAYERMODE) == 14
                && client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS) != null) {
            itemSearchChatboxOpen = true;
            clientThread.invokeLater(gePreviousSearch::showSuggestedItemInSearch);
        }

        if (quantityOrPriceChatboxOpen
                && event.getIndex() == VarClientID.MESLAYERMODE
                && client.getVarcIntValue(VarClientID.MESLAYERMODE) == 0
        ) {
            quantityOrPriceChatboxOpen = false;
            return;
        }

        if (itemSearchChatboxOpen
                && event.getIndex() == VarClientID.MESLAYERMODE
                && client.getVarcIntValue(VarClientID.MESLAYERMODE) == 0
        ) {
            clientThread.invokeLater(highlightController::redraw);
            itemSearchChatboxOpen = false;
            return;
        }

        //Check that it was the chat input that got enabled.
        if (event.getIndex() != VarClientID.MESLAYERMODE
                || client.getWidget(ComponentID.CHATBOX_TITLE) == null
                || client.getVarcIntValue(VarClientID.MESLAYERMODE) != 7
                || client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER) == null) {
            return;
        }
        quantityOrPriceChatboxOpen = true;

        clientThread.invokeLater(() ->
        {
            // A competing Hub flipping plugin may inject its own "Press [X] to set to Y gp" text
            // into this exact same chatbox widget -- if both plugins are enabled at once (see
            // HubPluginConflict's own doc comment), creating ours too makes the two overlap
            // into unreadable garbled text rather than either one working. Go fully quiet here,
            // matching RuneAssistSuggestionSource's own suppression of its suggestion output.
            if (com.runeassist.flip.HubPluginConflict.isEnabled(pluginManager)) {
                return;
            }
            flippingWidget = new OfferEditor(offerManager, client.getWidget(ComponentID.CHATBOX_CONTAINER), offerHandler, client, config);
            Suggestion suggestion = suggestionManager.getSuggestion();
            if (suggestion != null) {
                flippingWidget.showSuggestion(suggestion);
            }
        });
    }

    public void onVarClientStrChanged(VarClientStrChanged event) {
        if (event.getIndex() == VarClientID.MESLAYERINPUT && itemSearchChatboxOpen) {
            clientThread.invokeLater(highlightController::redraw);
        }
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.GE_OFFERS) {
            if (!accountStatusManager.isOwnedModifyActive() || !grandExchange.isSlotOpen()) {
                suggestionManager.setSuggestionNeeded(true);
            }
            clientThread.invokeLater(slotProfitColorizer::updateAllSlots);
        }
        // 467 (GE_OFFERS_SIDE) loads after 465. Redrawing only on the main GE
        // window left SELL highlights looking at a null inventory widget (runes
        // never outlined even when the suggestion was already SELL). Collect /
        // inventory / bank-pin are the other GE-adjacent interfaces that change
        // which widgets are targetable.
        if (event.getGroupId() == InterfaceID.GE_HISTORY
                || event.getGroupId() == InterfaceID.GE_OFFERS
                || event.getGroupId() == InterfaceID.GE_OFFERS_SIDE
                || event.getGroupId() == InterfaceID.GE_COLLECT
                || event.getGroupId() == InterfaceID.INVENTORY
                || event.getGroupId() == InterfaceID.BANKPIN_KEYPAD) {
            clientThread.invokeLater(highlightController::redraw);
        }
        if (event.getGroupId() == InterfaceID.BANKMAIN) {
            requestBankRebuildHighlightRedraw();
        }
    }

    public void onWidgetClosed(WidgetClosed event) {
        if (event.getGroupId() == InterfaceID.GE_OFFERS) {
            clientThread.invokeLater(highlightController::removeAll);
            // GE_OFFERS reloads when opening the slot editor for modify. Clearing
            // the lock here dropped the MODIFY card (panel → "Getting the next
            // flip…", no price highlight). releaseStaleOwnedModify on tick
            // drops the lock when the editor is actually gone.
        }
        if (event.getGroupId() == InterfaceID.BANKMAIN) {
            clientThread.invokeLater(highlightController::redraw);
        }
    }

    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarbitId() == VarbitID.GE_SELECTEDSLOT) {
            int open = grandExchange.getOpenSlot();
            Suggestion suggestion = suggestionManager.getSuggestion();
            if (open >= 0 && suggestion != null && suggestion.isModifySuggestion()
                    && suggestion.actionedTick == -1
                    && slotIsForModify(open, suggestion)) {
                accountStatusManager.beginOwnedModify(suggestion, open);
            } else if (accountStatusManager.isOwnedModifyActive()
                    && (open < 0 || !slotIsForModify(open, suggestion))) {
                accountStatusManager.clearOwnedModify();
                suggestionManager.setSuggestionNeeded(true);
            }
        }

        if (event.getVarpId() == 375
                || event.getVarpId() == VarPlayerID.TRADINGPOST_SEARCH
                || event.getVarbitId() == VarbitID.GE_NEWOFFER_QUANTITY
                || event.getVarbitId() == VarbitID.GE_NEWOFFER_PRICE
                || event.getVarbitId() == VarbitID.GE_SELECTEDSLOT) {
            clientThread.invokeLater(highlightController::redraw);
        }

        if (event.getVarpId() == VarPlayerID.TRADINGPOST_SEARCH) {
            clientThread.invokeLater(() -> offerHandler.fetchSlotItemPrice(event.getValue() > -1, this::getFlippingWidget));
        }
    }

    public void handleMenuOptionClicked(MenuOptionClicked event) {
        if (event.getMenuOption().equals("Confirm") && grandExchange.isSlotOpen()) {
            log.debug("offer confirmed tick {}", client.getTickCount());
            accountStatusManager.clearOwnedModify();
            heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            offerManager.setOfferJustPlaced(true);
            suggestionManager.setLastOfferSubmittedTick(client.getTickCount());
            suggestionManager.setSuggestionNeeded(true);
            Suggestion suggestion = suggestionManager.getSuggestion();
            if(suggestion != null) {
                suggestion.actionedTick = client.getTickCount();
                suggestionManager.recordOfferSubmission(suggestion, client.getTickCount());
                flipHistorySyncService.reportSuggestionOutcome(suggestion, "acted");
            }
        }
        if (BANK_TAG_TAB_VIEW_OPTION.equals(event.getMenuOption())) {
            requestBankRebuildHighlightRedraw();
        }
    }

    /** True when the open GE slot is this MODIFY: owned/clicked slot, editor item, */
    private boolean slotIsForModify(int open, Suggestion suggestion) {
        if (open < 0) {
            return false;
        }
        int currentItem = grandExchange.getCurrentItemId();
        AccountStatusManager.OwnedModify owned = accountStatusManager.getOwnedModify();
        if (owned != null && owned.itemId > 0) {
            if (ModifyStep.editorMatches(open, currentItem, owned.itemId, owned.slot)) {
                return true;
            }
            if (liveOfferItemId(open) == owned.itemId) {
                return true;
            }
        }
        if (suggestion == null || !suggestion.isModifySuggestion()) {
            return false;
        }
        if (ModifyStep.editorMatches(open, currentItem, suggestion.getItemId(), suggestion.getBoxId())) {
            return true;
        }
        return liveOfferItemId(open) == suggestion.getItemId();
    }

    private int liveOfferItemId(int slot) {
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null || slot < 0 || slot >= offers.length || offers[slot] == null) {
            return -1;
        }
        return offers[slot].getItemId();
    }


    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == SCRIPT_GE_COLLECT || event.getScriptId() == SCRIPT_GE_SLOT_REDRAW) {
            clientThread.invokeLater(slotProfitColorizer::updateAllSlots);
        }
        if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING) {
            requestBankRebuildHighlightRedraw();
        }
    }

    public void onBeforeRender(BeforeRender event) {
        if (bankRebuildHighlightRedrawFramesRemaining > 0) {
            bankRebuildHighlightRedrawFramesRemaining--;
            if (bankRebuildHighlightRedrawFramesRemaining == 0) {
                highlightController.redraw();
            }
        }
        if (grandExchange.isOpen()) {
            slotProfitColorizer.updateAllSlots();
        }
    }

    private void requestBankRebuildHighlightRedraw() {
        bankRebuildHighlightRedrawFramesRemaining = BANK_REBUILD_HIGHLIGHT_REDRAW_DELAY_FRAMES;
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.HeldItemSyncStateRS;
import com.runeassist.flip.ui.SuggestionPanel;
import com.google.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GrandExchangeCollectHandler {

    // dependencies
    private final OsrsLoginManager osrsLoginManager;
    private final GrandExchangeUncollectedManager geUncollected;
    private final SuggestionManager suggestionManager;
    private final Client client;
    private final HeldItemSyncStateRS heldItemSyncStateRS;
    private final AccountStatusManager accountStatusManager;
    private final FlipHistorySyncService flipHistorySyncService;

    @Setter
    private SuggestionPanel suggestionPanel;

    public void handleCollect(MenuOptionClicked event, int slot) {
        String menuOption = event.getMenuOption();
        Widget widget = event.getWidget();
        if (menuOption != null && menuOption.contains("Collect")) {
            accountStatusManager.clearOwnedModify();
            Suggestion suggestion = suggestionManager.getSuggestion();
            if (suggestion != null && suggestion.isAbortSuggestion() && suggestion.actionedTick == -1) {
                suggestion.actionedTick = client.getTickCount();
                flipHistorySyncService.reportSuggestionOutcome(suggestion, "acted");
            }
        }
        if (widget != null) {
            handleCollectAll(menuOption, widget);
            handleCollectWithSlotOpen(menuOption, widget, slot);
            handleCollectionBoxCollectAll(menuOption, widget);
            handleCollectionBoxCollectItem(menuOption, widget);
            handleModifyOffer(menuOption, widget);
        }
    }

    private void handleModifyOffer(String menuOption, Widget widget) {
        if (menuOption.equals("Modify offer")) {
            int slot = widget.getId() - 30474247;
            log.debug("modify offer clicked (tick {}) on slot {}", client.getTickCount(), slot);
            Suggestion suggestion = suggestionManager.getSuggestion();
            if (suggestion != null && suggestion.isModifySuggestion()) {
                accountStatusManager.beginOwnedModify(suggestion, slot);
            }
            suggestionManager.suggestionsDelayedUntil = client.getTickCount() + 3;
            geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
        }
    }

    private void handleCollectAll(String menuOption, Widget widget) {
        if (widget.getId() == 30474246) {
            if (menuOption.equals("Collect to inventory")) {
                geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            } else if (menuOption.equals("Collect to bank")) {
                geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            }
            suggestionPanel.refresh();
        }
    }

    private void handleCollectWithSlotOpen(String menuOption, Widget widget, int slot) {
        if (widget.getId() == 30474264 ) {
            if (menuOption.contains("Collect")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            } else if (menuOption.contains("Bank")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            }
            suggestionPanel.refresh();
        }
    }

    private void handleCollectionBoxCollectAll(String menuOption, Widget widget) {
        if (widget.getId() == 26345476 && menuOption.equals("Collect to bank")) {
            geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
            heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            suggestionPanel.refresh();
            
        } else if (widget.getId() == 26345475 && menuOption.equals("Collect to inventory")) {
            geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
            heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            suggestionPanel.refresh();
        }
    }

    private void handleCollectionBoxCollectItem(String menuOption, Widget widget) {
        int slot = widget.getId() - 26345477;
        if (slot >= 0 && slot <= 7) {
            if (menuOption.contains("Collect")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            } else if (menuOption.contains("Bank")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            }
            suggestionPanel.refresh();
        }
    }
}

package com.runeassist.flip.controller;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.LinkedHashSet;
import java.util.Set;

@Slf4j
@Singleton
public class PortfolioController {
    // dependencies
    private final Client client;
    private final ItemController itemController;

    @Inject
    public PortfolioController(Client client,
                               ItemController itemController) {
        this.client = client;
        this.itemController = itemController;
    }

    public Set<Integer> getActiveGrandExchangeItemIdsForSync() {
        Set<Integer> itemIds = new LinkedHashSet<>();
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null) {
            return itemIds;
        }
        for (GrandExchangeOffer offer : offers) {
            if (offer == null) {
                continue;
            }
            GrandExchangeOfferState state = offer.getState();
            if (state != GrandExchangeOfferState.EMPTY) {
                int itemId = offer.getItemId();
                if (itemId > 0) {
                    itemIds.add(itemController.toUnnotedItemId(itemId));
                }
            }
        }
        return itemIds;
    }

}

package com.runeassist.flip.controller;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.BankState;
import com.runeassist.flip.model.PortfolioItemCardData;
import com.runeassist.flip.model.PortfolioState;
import com.runeassist.flip.rs.BankStateRS;
import com.runeassist.flip.rs.PortfolioStateRS;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.IntUnaryOperator;

/**
 * Local Bank Tags portfolio tab — FC parity without a server portfolio-tags endpoint.
 * <p>
 * Bank Tags is resolved at runtime (see {@link BankTagsLookup}) so this plugin can sideload
 * without {@code @PluginDependency(BankTagsPlugin.class)}.
 */
@Singleton
@Slf4j
public class PortfolioBankTagController {
    private static final String CONFIG_GROUP = "runeassistflip";
    private static final String CREATED_TAB_CONFIG_KEY = "portfolioBankTagTabCreated";
    private static final String TAG_NAME = "portfolio";
    private static final int TAB_ICON_ITEM_ID = ItemID.FRISD_TAXBAG_BULGING;
    private static final String LEGACY_TAB_ICON_ITEM_ID = String.valueOf(ItemController.PLATINUM_TOKENS_ITEM_ID);

    private final RuneAssistConfig config;
    private final ClientThread clientThread;
    private final ConfigManager configManager;
    private final PluginManager pluginManager;
    private final ItemManager itemManager;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;

    private final AtomicBoolean registered = new AtomicBoolean(false);
    private final AtomicBoolean active = new AtomicBoolean(false);
    private final AtomicBoolean syncQueued = new AtomicBoolean(false);
    private volatile Set<Integer> bankedPortfolioItemIds = Collections.emptySet();
    private Runnable removePortfolioListener;
    private Runnable removeBankListener;

    @Inject
    public PortfolioBankTagController(RuneAssistConfig config,
                                      ClientThread clientThread,
                                      ConfigManager configManager,
                                      PluginManager pluginManager,
                                      ItemManager itemManager,
                                      PortfolioStateRS portfolioStateRS,
                                      BankStateRS bankStateRS) {
        this.config = config;
        this.clientThread = clientThread;
        this.configManager = configManager;
        this.pluginManager = pluginManager;
        this.itemManager = itemManager;
        this.portfolioStateRS = portfolioStateRS;
        this.bankStateRS = bankStateRS;
    }

    public void startUp() {
        active.set(true);
        removePortfolioListener = portfolioStateRS.registerListener(state -> requestSync());
        removeBankListener = bankStateRS.registerListener(state -> requestSync());
        requestSync();
    }

    public void shutDown() {
        active.set(false);
        if (removePortfolioListener != null) {
            removePortfolioListener.run();
            removePortfolioListener = null;
        }
        if (removeBankListener != null) {
            removeBankListener.run();
            removeBankListener = null;
        }
        unregisterTag();
    }

    public void onConfigChanged() {
        requestSync();
    }

    /** Re-evaluate when Bank Tags itself is toggled on/off. */
    public void onBankTagsPluginChanged() {
        requestSync();
    }

    private void requestSync() {
        if (!active.get() || !syncQueued.compareAndSet(false, true)) {
            return;
        }

        // Plugin start-up runs on the AWT event thread when toggled from the plugin
        // panel. ItemManager.canonicalize(), used by sync(), requires the client thread.
        clientThread.invokeLater(() -> {
            syncQueued.set(false);
            if (active.get()) {
                sync();
            }
        });
    }

    private void sync() {
        BankTagsPlugin bankTagsPlugin = BankTagsLookup.findActive(pluginManager);
        TagManager tagManager = BankTagsLookup.tagManager(bankTagsPlugin);
        if (!config.portfolioBankTag() || bankTagsPlugin == null || tagManager == null) {
            bankedPortfolioItemIds = Collections.emptySet();
            if (!config.portfolioBankTag()) {
                removeAutoCreatedTab();
            }
            unregisterTag(tagManager);
            return;
        }

        registerTag(tagManager);
        ensureBankTagTab();
        updateBankedPortfolioItems(bankTagsPlugin);
    }

    private void registerTag(TagManager tagManager) {
        if (registered.compareAndSet(false, true)) {
            tagManager.registerTag(TAG_NAME, itemId -> bankedPortfolioItemIds.contains(canonicalize(itemId)));
            log.debug("registered dynamic Bank Tags tag '{}'", TAG_NAME);
        }
    }

    private void unregisterTag() {
        unregisterTag(BankTagsLookup.tagManager(BankTagsLookup.findActive(pluginManager)));
    }

    private void unregisterTag(TagManager tagManager) {
        bankedPortfolioItemIds = Collections.emptySet();
        if (!registered.compareAndSet(true, false)) {
            return;
        }
        if (tagManager != null) {
            tagManager.unregisterTag(TAG_NAME);
            log.debug("unregistered dynamic Bank Tags tag '{}'", TAG_NAME);
        }
    }

    private void ensureBankTagTab() {
        List<String> tabs = new ArrayList<>(Text.fromCSV(configValue(BankTagsPlugin.TAG_TABS_CONFIG)));
        if (!tabs.contains(TAG_NAME)) {
            tabs.add(TAG_NAME);
            configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
            configManager.setConfiguration(CONFIG_GROUP, CREATED_TAB_CONFIG_KEY, true);
        }

        String iconKey = BankTagsPlugin.TAG_ICON_PREFIX + TAG_NAME;
        String iconItemId = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, iconKey);
        if (iconItemId == null || LEGACY_TAB_ICON_ITEM_ID.equals(iconItemId)) {
            configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, iconKey, TAB_ICON_ITEM_ID);
        }
    }

    private void removeAutoCreatedTab() {
        if (!Boolean.TRUE.equals(configManager.getConfiguration(CONFIG_GROUP, CREATED_TAB_CONFIG_KEY, Boolean.class))) {
            return;
        }

        List<String> tabs = new ArrayList<>(Text.fromCSV(configValue(BankTagsPlugin.TAG_TABS_CONFIG)));
        if (tabs.remove(TAG_NAME)) {
            configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
        }
        configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + TAG_NAME);
        configManager.unsetConfiguration(CONFIG_GROUP, CREATED_TAB_CONFIG_KEY);
    }

    private String configValue(String key) {
        String value = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, key);
        return value == null ? "" : value;
    }

    private void updateBankedPortfolioItems(BankTagsPlugin bankTagsPlugin) {
        Set<Integer> itemIds = selectBankedPortfolioItemIds(
                portfolioStateRS.get(),
                bankStateRS.get(),
                this::canonicalize);
        setBankedPortfolioItemIds(itemIds, bankTagsPlugin);
    }

    /**
     * Portfolio items that both have banked portfolio quantity and are present in the
     * observed bank. Pure for unit tests; canonicalize is injected so ItemManager is optional.
     */
    static Set<Integer> selectBankedPortfolioItemIds(PortfolioState portfolioState,
                                                     BankState bankState,
                                                     IntUnaryOperator canonicalize) {
        if (portfolioState == null || !portfolioState.isLoaded() || bankState == null || !bankState.isLoaded()) {
            return Collections.emptySet();
        }

        Set<Integer> bankItems = new HashSet<>();
        Map<Integer, Integer> items = bankState.getItems();
        if (items != null) {
            items.forEach((itemId, quantity) -> {
                if (itemId != null && quantity != null && quantity > 0) {
                    bankItems.add(canonicalize.applyAsInt(itemId));
                }
            });
        }

        Set<Integer> itemIds = new HashSet<>();
        for (PortfolioItemCardData item : portfolioState.getItemCardDataByItemId().values()) {
            if (item != null && item.hasPortfolioQuantityInBank()) {
                int itemId = canonicalize.applyAsInt(item.getItemId());
                if (bankItems.contains(itemId)) {
                    itemIds.add(itemId);
                }
            }
        }
        return Collections.unmodifiableSet(itemIds);
    }

    private void setBankedPortfolioItemIds(Set<Integer> itemIds, BankTagsPlugin bankTagsPlugin) {
        Set<Integer> previous = bankedPortfolioItemIds;
        if (previous.equals(itemIds)) {
            return;
        }

        bankedPortfolioItemIds = itemIds;
        refreshActivePortfolioTag(bankTagsPlugin);
    }

    private void refreshActivePortfolioTag(BankTagsPlugin bankTagsPlugin) {
        if (bankTagsPlugin == null) {
            return;
        }
        if (TAG_NAME.equals(bankTagsPlugin.getActiveTag())) {
            bankTagsPlugin.openBankTag(TAG_NAME, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
        }
    }

    private int canonicalize(int itemId) {
        return itemManager.canonicalize(Math.abs(itemId));
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.*;
import com.runeassist.flip.ui.UIUtilities;
import joptsimple.internal.Strings;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.time.Instant;

import static com.runeassist.flip.util.DateUtil.formatEpoch;
import static net.runelite.http.api.RuneLiteAPI.GSON;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class WebHookController {

    private final RuneAssistConfig config;
    private final OkHttpClient okHttpClient;

    private void sendWebHook(DiscordWebhookBody discordWebhookBody) {
        String configURL = config.webhook();
        if (Strings.isNullOrEmpty(configURL)) {return; }

        HttpUrl url = HttpUrl.parse(configURL);
        if (url == null) {
            log.warn("bad discord webhook url {}", configURL);
            return;
        }
        MultipartBody.Builder requestBodyBuilder = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("payload_json", GSON.toJson(discordWebhookBody));
        buildRequestAndSend(url, requestBodyBuilder);
    }

    private void buildRequestAndSend(HttpUrl url, MultipartBody.Builder requestBodyBuilder) {
        RequestBody requestBody = requestBodyBuilder.build();
        Request request = new Request.Builder()
                .url(url)
                .post(requestBody)
                .build();
        sendRequest(request);
    }

    private void sendRequest(Request request) {
        okHttpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.debug("Error on webhook", e);
            }

            @Override
            public void onResponse(Call call, Response response) {
                response.close();
            }
        });
    }

    public void sendMessage(Stats stats, SessionData sd, String displayName, boolean sessionIsFinished) {
        if (stats.profit != 0 && displayName != null) {

            long seconds = sd.durationMillis / 1000;
            String beganAtText = formatEpoch(sd.startTime);
            String endedAtText = sessionIsFinished ? formatEpoch(Instant.now().getEpochSecond()) : "n/a";
            String durationText = String.format("%02d:%02d:%02d", seconds / 3600, (seconds % 3600) / 60, seconds % 60);
            String profitText = UIUtilities.formatProfit(stats.profit);
            String taxText = UIUtilities.formatProfit(stats.taxPaid);
            String roiText = String.format("%.3f%%", stats.calculateRoi() * 100);
            String cashStackText = UIUtilities.quantityToRSDecimalStack(Math.abs(sd.averageCash), false) + " gp";

            String template = "%s, your session stats are:\n" +
                    "```" +
                    "Session began at:      %s\n" +
                    "Session ended at:      %s\n" +
                    "Active session time:   %s\n" +
                    "Flips made:            %d\n" +
                    "Profit:                %s\n" +
                    "Tax paid:              %s\n" +
                    "Roi:                   %s\n" +
                    "Avg wealth:            %s\n" +
                    "```";

            String discordMessage = String.format(template, displayName, beganAtText, endedAtText, durationText, stats.flipsMade, profitText, taxText, roiText, cashStackText);
            DiscordWebhookBody discordWebhookBody = new DiscordWebhookBody();
            discordWebhookBody.setContent(discordMessage);
            sendWebHook(discordWebhookBody);
        }
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.ui.UIUtilities;
import com.runeassist.flip.util.ProfitCalculator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TooltipController {
    private static final int SCRIPT_TOOLTIP_GE = 526;
    private static final int TOOLTIP_HEIGHT_WITH_PROFIT = 45;

    private static final int WIDTH_PADDING = 4;

    private final Client client;
    private final ProfitCalculator profitCalculator;

    public void tooltip(ScriptPostFired e) {
        if(e.getScriptId() != SCRIPT_TOOLTIP_GE) {
            return;
        }

        Widget tooltip = client.getWidget(InterfaceID.GeOffers.TOOLTIP);

        if(tooltip == null || tooltip.isHidden()) {
            return;
        }

        Widget background = tooltip.getChild(0);
        Widget border = tooltip.getChild(1);
        Widget text = tooltip.getChild(2);

        if (text != null && background != null && border != null) {

            if (text.getText().contains("Profit:")) {
                // If the tooltip already contains profit information, we don't need to process it again
                return;
            }

            if(!isItemSelling(text.getText())) {
                return;
            }

            String name = getItemNameFromTooltipText(text.getText());

            if(name != null) {
                long profit = profitCalculator.getProfitByItemName(name);
                text.setText(text.getText()  + "<br>Profit: " + UIUtilities.quantityToRSDecimalStack(profit, false) + " gp");
                tooltip.setOriginalHeight(TOOLTIP_HEIGHT_WITH_PROFIT);

                int width = calculateTooltipWidth(text.getFont(), text.getText());
                tooltip.setOriginalWidth(width);

                tooltip.revalidate();
                border.revalidate();
                background.revalidate();
                text.revalidate();
            }
        }
    }

    public boolean isItemSelling(String text) {
        text = text.replaceAll("<br>", " ").trim();
        Pattern pattern = Pattern.compile("^(Buying|Selling): (.+) (\\d{1,3}(?:,\\d{3})*|\\d+) / (\\d{1,3}(?:,\\d{3})*|\\d+)( Profit: -?[\\d,]+ gp?)?$");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            String action = matcher.group(1);
            return action.equals("Selling");
        } else {
            return false; // or handle as you wish
        }
    }

    public String getItemNameFromTooltipText(String text) {
        text = text.replaceAll("<br>", " ").trim();
        Pattern pattern = Pattern.compile("^(Buying|Selling): (.+) (\\d{1,3}(?:,\\d{3})*|\\d+) / (\\d{1,3}(?:,\\d{3})*|\\d+)( Profit: -?[\\d,]+ gp?)?$");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return matcher.group(2);
        } else {
            return null; // or handle as you wish
        }
    }

    private int calculateTooltipWidth(FontTypeFace f, String text)
    {
        final String[] lines = text.split("<br>");
        int maxWidth = 0;
        for (String line : lines) {
            String left = "";
            left = line;

            int width = f.getTextWidth(left);
            if (width > maxWidth) {
                maxWidth = width;
            }
        }
        return maxWidth + WIDTH_PADDING;
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.SavedOffer;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import net.runelite.api.GrandExchangeOfferState;

/** Session-local evidence, independent of persisted offers or suggestion attribution. */
final class OfferObservationTracker {
    private final Map<Integer, SavedOffer> slots = new HashMap<>();
    private String sessionId = UUID.randomUUID().toString();
    private Long account;

    void reset() {
        slots.clear();
        sessionId = UUID.randomUUID().toString();
        account = null;
    }

    boolean observe(long accountHash, int slot, SavedOffer offer, boolean login, long now) {
        if (account == null || account != accountHash) {
            reset();
            account = accountHash;
        }
        SavedOffer previous = slots.get(slot);
        boolean first = previous == null;
        boolean empty = offer.getState() == GrandExchangeOfferState.EMPTY;
        boolean active = offer.getState() == GrandExchangeOfferState.BUYING
                || offer.getState() == GrandExchangeOfferState.SELLING;
        boolean previousActive = previous != null && (previous.getState() == GrandExchangeOfferState.BUYING
                || previous.getState() == GrandExchangeOfferState.SELLING);
        boolean same = previous != null && !GrandExchangeOfferEventHandler.isNewOffer(previous, offer)
                && !(active && !previousActive);
        offer.setObservedAt(now);
        offer.setObservationSessionId(sessionId);
        offer.setLoginObservation(login);
        if (!empty) {
            offer.setOfferInstanceId(same ? previous.getOfferInstanceId() : UUID.randomUUID().toString());
            if (same) {
                offer.setPlacedAt(previous.getPlacedAt());
            } else if (!login && active && offer.getQuantitySold() == 0 && previous != null
                    && previous.getState() == GrandExchangeOfferState.EMPTY) {
                // Timestamp of the actual client placement transition, not a market-price inference.
                offer.setPlacedAt(now);
            }
        }
        slots.put(slot, offer);
        return first;
    }
}

package com.runeassist.flip.controller;

import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;

/**
 * Resolves the core Bank Tags plugin at runtime.
 * <p>
 * RuneAssist cannot use {@code @PluginDependency(BankTagsPlugin.class)} or hard Guice
 * injection of Bank Tags types: a sideloaded plugin that does either fails to construct /
 * load. Hub installs share the client classloader, so {@code instanceof} +
 * {@link Plugin#getInjector()} still reach TagManager when Bank Tags is enabled.
 */
public final class BankTagsLookup {
    private BankTagsLookup() {
    }

    public static BankTagsPlugin findActive(PluginManager pluginManager) {
        if (pluginManager == null) {
            return null;
        }
        for (Plugin plugin : pluginManager.getPlugins()) {
            if (plugin instanceof BankTagsPlugin && pluginManager.isPluginActive(plugin)) {
                return (BankTagsPlugin) plugin;
            }
        }
        return null;
    }

    public static TagManager tagManager(BankTagsPlugin bankTagsPlugin) {
        if (bankTagsPlugin == null || bankTagsPlugin.getInjector() == null) {
            return null;
        }
        try {
            return bankTagsPlugin.getInjector().getInstance(TagManager.class);
        } catch (RuntimeException ex) {
            return null;
        }
    }
}

package com.runeassist.flip.controller;

import javax.inject.Singleton;
import java.awt.*;

@Singleton
public class HighlightColorController {

    // Color ranges for red highlight (R,G,B values)
    private static final int[] RED_START = {205, 0, 50};
    private static final int[] RED_END = {255, 50, 0};

    // Color ranges for blue highlight (R,G,B values)
    private static final int[] BLUE_START = {5, 153, 255};
    private static final int[] BLUE_END = {55, 205, 205};

    // Color ranges for amber highlight (R,G,B values)
    private static final int[] AMBER_START = {210, 108, 0};
    private static final int[] AMBER_END = {236, 134, 10};

    // Constants for controlling the drift
    private static final long CYCLE_DURATION = 600000; // 10 minutes for one complete cycle
    private static final int BASE_ALPHA = 79;
    private static final int MIN_ALPHA = 31;
    private static final int DUMP_ALPHA_MAX = 127;
    private static final double DUMP_ALPHA_FREQUENCY_HZ = 2.0;

    public Color getRedColor() {
        return getRedColor(false);
    }

    public Color getRedColor(boolean isDumpAlert) {
        double phase = calculatePhase();
        int alpha = calculateAlpha(isDumpAlert);
        return interpolateColor(RED_START, RED_END, phase, alpha);
    }

    public Color getBlueColor() {
        return getBlueColor(false);
    }

    public Color getBlueColor(boolean isDumpAlert) {
        double phase = calculatePhase();
        int alpha = calculateAlpha(isDumpAlert);
        return interpolateColor(BLUE_START, BLUE_END, phase, alpha);
    }

    public Color getAmberColor() {
        return getAmberColor(false);
    }

    public Color getAmberColor(boolean isDumpAlert) {
        double phase = calculatePhase();
        int alpha = calculateAlpha(isDumpAlert);
        return interpolateColor(AMBER_START, AMBER_END, phase, alpha);
    }

    private double calculatePhase() {
        // Current time modulo cycle duration gives us position in the cycle
        long currentTime = System.currentTimeMillis();
        double cyclePosition = (currentTime % CYCLE_DURATION) / (double) CYCLE_DURATION;

        // Use absolute sine wave to create smooth back-and-forth oscillation
        return Math.abs(Math.sin(cyclePosition * Math.PI));
    }

    private Color interpolateColor(int[] start, int[] end, double phase, int alpha) {
        int red = interpolateComponent(start[0], end[0], phase);
        int green = interpolateComponent(start[1], end[1], phase);
        int blue = interpolateComponent(start[2], end[2], phase);

        return new Color(red, green, blue, alpha);
    }

    private int interpolateComponent(int start, int end, double phase) {
        return (int) Math.round(start + (end - start) * phase);
    }

    private int calculateAlpha(boolean isDumpAlert) {
        if (!isDumpAlert) {
            return BASE_ALPHA;
        }
        double timeSeconds = System.currentTimeMillis() / 1000.0;
        double phase = (timeSeconds * DUMP_ALPHA_FREQUENCY_HZ) % 1.0;
        double oscillation = 1.0 - Math.abs(2.0 * phase - 1.0);
        return (int) Math.round(MIN_ALPHA + (DUMP_ALPHA_MAX - MIN_ALPHA) * oscillation);
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.AresMarketClient;
import com.runeassist.flip.HeldCostTracker;
import com.runeassist.flip.model.PortfolioItemCardData;
import com.runeassist.flip.model.SuggestionManager;
import com.runeassist.flip.rs.BankStateRS;
import com.runeassist.flip.rs.PortfolioStateRS;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.chatbox.ChatboxPanelManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.function.Consumer;

/** Near-GE Examine menus: Add/Remove (+ X qty) for portfolio held lots. */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PortfolioMenuEntries {

    private static final String MENU_ADD = "Add-All to portfolio";
    private static final String MENU_ADD_X = "Add-X to portfolio";
    private static final String MENU_REMOVE = "Remove-All from portfolio";
    private static final String MENU_REMOVE_X = "Remove-X from portfolio";

    enum MenuLocation { INVENTORY, BANK }

    private final Client client;
    private final ItemController itemController;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;
    private final ChatboxPanelManager chatboxPanelManager;
    private final HeldCostTracker heldCostTracker;
    private final AresMarketClient market;
    private final FlipHistorySyncService flipHistorySyncService;
    private final SuggestionManager suggestionManager;
    private final ExecutorService executorService;

    public void injectExamineMenus(MenuEntryAdded event) {
        InventoryMenuItem menuItem = getInventoryMenuItem(event);
        if (menuItem == null) {
            return;
        }
        int locationQty = getLocationQuantity(menuItem.unnotedItemId, menuItem.location);
        if (locationQty <= 0) {
            return;
        }
        PortfolioQtys qtys = resolvePortfolioQtys(menuItem.unnotedItemId);
        MenuVisibility vis = menuVisibility(locationQty, qtys.portfolioQty, qtys.notInPortfolio, qtys.unknownItem);
        if (vis.showRemoveX) {
            addEntry(MENU_REMOVE_X, menuItem,
                    e -> promptQuantity(menuItem, "Enter quantity to remove:", qtys.portfolioQty, true));
        }
        if (vis.showRemove) {
            addEntry(MENU_REMOVE, menuItem, e -> untrackHeld(menuItem, locationQty));
        }
        if (vis.showAddX) {
            int addMax = qtys.notInPortfolio > 0 ? qtys.notInPortfolio : locationQty;
            addEntry(MENU_ADD_X, menuItem,
                    e -> promptQuantity(menuItem, "Enter quantity to add:", addMax, false));
        }
        if (vis.showAdd) {
            addEntry(MENU_ADD, menuItem, e -> trackHeld(menuItem, locationQty));
        }
    }

    static MenuVisibility menuVisibility(int locationQty, int portfolioQty, int notInPortfolio, boolean unknownItem) {
        boolean showAdd = locationQty > 0 && (unknownItem || portfolioQty <= 0 || notInPortfolio > 0);
        boolean showRemove = locationQty > 0 && portfolioQty > 0;
        boolean showAddX = notInPortfolio > 1;
        boolean showRemoveX = portfolioQty > 1;
        return new MenuVisibility(showAdd, showRemove, showAddX, showRemoveX);
    }

    static final class MenuVisibility {
        final boolean showAdd;
        final boolean showRemove;
        final boolean showAddX;
        final boolean showRemoveX;

        MenuVisibility(boolean showAdd, boolean showRemove, boolean showAddX, boolean showRemoveX) {
            this.showAdd = showAdd;
            this.showRemove = showRemove;
            this.showAddX = showAddX;
            this.showRemoveX = showRemoveX;
        }
    }

    private static final class PortfolioQtys {
        final int portfolioQty;
        final int notInPortfolio;
        final boolean unknownItem;

        PortfolioQtys(int portfolioQty, int notInPortfolio, boolean unknownItem) {
            this.portfolioQty = portfolioQty;
            this.notInPortfolio = notInPortfolio;
            this.unknownItem = unknownItem;
        }
    }

    private static final class InventoryMenuItem {
        final int unnotedItemId;
        final String menuTarget;
        final MenuLocation location;

        InventoryMenuItem(int unnotedItemId, String menuTarget, MenuLocation location) {
            this.unnotedItemId = unnotedItemId;
            this.menuTarget = menuTarget;
            this.location = location;
        }
    }

    private PortfolioQtys resolvePortfolioQtys(int itemId) {
        PortfolioItemCardData card = null;
        if (portfolioStateRS.get().isLoaded()) {
            card = portfolioStateRS.get().getItemCardDataByItemId().get(itemId);
        }
        if (card != null) {
            return new PortfolioQtys(card.getPortfolioQuantity(), card.getNotInPortfolioQuantity(), false);
        }
        Player localPlayer = client.getLocalPlayer();
        String displayName = localPlayer != null ? localPlayer.getName() : null;
        Map<Integer, long[]> held = heldCostTracker.held(displayName);
        long[] row = held == null ? null : held.get(itemId);
        int portfolioQty = row == null ? 0 : (int) Math.max(0L, row[0]);
        Map<Integer, Integer> inv = itemController.getRunliteInventory();
        int invQty = inv == null ? 0 : Math.max(0, inv.getOrDefault(itemId, 0));
        int bankQty = 0;
        if (bankStateRS.get().isLoaded()) {
            Map<Integer, Integer> bank = bankStateRS.get().getItems();
            bankQty = bank == null ? 0 : Math.max(0, bank.getOrDefault(itemId, 0));
        }
        int notInPortfolio = Math.max(0, invQty + bankQty - portfolioQty);
        boolean unknownItem = portfolioQty <= 0;
        if (unknownItem) {
            notInPortfolio = 0;
        }
        return new PortfolioQtys(portfolioQty, notInPortfolio, unknownItem);
    }

    private void promptQuantity(InventoryMenuItem menuItem, String prompt, int maxQty, boolean remove) {
        chatboxPanelManager.openTextInput(prompt)
                .charValidator(c -> c >= '0' && c <= '9')
                .onDone((String input) -> {
                    if (input == null || input.isEmpty()) {
                        return;
                    }
                    try {
                        int qty = Integer.parseInt(input);
                        if (qty > 0) {
                            int capped = maxQty > 0 ? Math.min(qty, maxQty) : qty;
                            if (remove) {
                                untrackHeld(menuItem, capped);
                            } else {
                                trackHeld(menuItem, capped);
                            }
                        }
                    } catch (NumberFormatException ignored) {
                    }
                })
                .build();
    }

    private void trackHeld(InventoryMenuItem menuItem, int qty) {
        if (qty <= 0) {
            return;
        }
        int itemId = menuItem.unnotedItemId;
        Player localPlayer = client.getLocalPlayer();
        String displayName = localPlayer != null ? localPlayer.getName() : null;
        executorService.execute(() -> {
            long unitCost = 0;
            try {
                Map<String, Object> quote = market.quote(itemId);
                if (quote != null && quote.get("buy_at") instanceof Number) {
                    unitCost = ((Number) quote.get("buy_at")).longValue();
                }
            } catch (Exception ex) {
                log.warn("market quote failed while adding item {} to portfolio", itemId, ex);
            }
            if (flipHistorySyncService != null && flipHistorySyncService.isLinked()
                    && flipHistorySyncService.toggleItemPortfolio(displayName, itemId, qty, unitCost, false)) {
                log.info("added {} x item {} to server portfolio at estimated cost {} gp", qty, itemId, unitCost);
            } else {
                heldCostTracker.addManualLot(displayName, itemId, qty, unitCost);
                suggestionManager.setSuggestionNeeded(true);
                log.info("added {} x item {} to local portfolio at estimated cost {} gp", qty, itemId, unitCost);
            }
        });
    }

    private void untrackHeld(InventoryMenuItem menuItem, int qty) {
        if (qty <= 0) {
            return;
        }
        int itemId = menuItem.unnotedItemId;
        Player localPlayer = client.getLocalPlayer();
        String displayName = localPlayer != null ? localPlayer.getName() : null;
        executorService.execute(() -> {
            if (flipHistorySyncService != null && flipHistorySyncService.isLinked()
                    && flipHistorySyncService.toggleItemPortfolio(displayName, itemId, qty, 0L, true)) {
                log.info("removed {} x item {} from server portfolio", qty, itemId);
            } else {
                int removed = heldCostTracker.removeLots(displayName, itemId, qty);
                suggestionManager.setSuggestionNeeded(true);
                log.info("removed {} x item {} from local portfolio", removed, itemId);
            }
        });
    }

    private void addEntry(String option, InventoryMenuItem menuItem, Consumer<MenuEntry> onClick) {
        client.getMenu()
                .createMenuEntry(-1)
                .setOption(option)
                .setTarget(menuItem.menuTarget)
                .onClick(onClick);
    }

    private int getLocationQuantity(int itemId, MenuLocation location) {
        if (location == MenuLocation.INVENTORY) {
            Map<Integer, Integer> inv = itemController.getRunliteInventory();
            return inv == null ? 0 : Math.max(0, inv.getOrDefault(itemId, 0));
        }
        if (location == MenuLocation.BANK) {
            if (!bankStateRS.get().isLoaded()) {
                return 0;
            }
            Map<Integer, Integer> bank = bankStateRS.get().getItems();
            return bank == null ? 0 : Math.max(0, bank.getOrDefault(itemId, 0));
        }
        return 0;
    }

    private MenuLocation getMenuLocation(int widgetId) {
        Widget geInventoryWidget = client.getWidget(467, 0);
        if (geInventoryWidget != null && geInventoryWidget.getId() == widgetId) {
            return MenuLocation.INVENTORY;
        }
        Widget inventoryWidget = client.getWidget(149, 0);
        if (inventoryWidget != null && inventoryWidget.getId() == widgetId) {
            return MenuLocation.INVENTORY;
        }
        Widget bankInventoryWidget = client.getWidget(
                BankWidgets.BANK_INVENTORY_WIDGET_GROUP, BankWidgets.BANK_INVENTORY_WIDGET_CHILD);
        if (bankInventoryWidget != null && bankInventoryWidget.getId() == widgetId) {
            return MenuLocation.INVENTORY;
        }
        for (int childId : BankWidgets.BANK_ITEM_CONTAINER_CHILDREN) {
            Widget bankItemWidget = client.getWidget(BankWidgets.BANK_WIDGET_GROUP, childId);
            if (bankItemWidget != null && bankItemWidget.getId() == widgetId) {
                return MenuLocation.BANK;
            }
        }
        return null;
    }

    private InventoryMenuItem getInventoryMenuItem(MenuEntryAdded event) {
        if (!"Examine".equals(event.getOption())) {
            return null;
        }
        int inventorySlot = event.getActionParam0();
        int inventoryWidgetId = event.getActionParam1();
        MenuLocation location = getMenuLocation(inventoryWidgetId);
        if (location == null) {
            return null;
        }
        Widget inventoryWidget = client.getWidget(inventoryWidgetId);
        if (inventoryWidget == null || inventorySlot < 0) {
            return null;
        }
        Widget[] items = inventoryWidget.getDynamicChildren();
        if (items == null || inventorySlot >= items.length) {
            return null;
        }
        Widget itemWidget = items[inventorySlot];
        if (itemWidget == null || itemWidget.getItemId() <= 0) {
            return null;
        }
        int unnotedItemId = itemController.toUnnotedItemId(itemWidget.getItemId());
        String menuTarget = resolveMenuTarget(event.getTarget(), unnotedItemId);
        return new InventoryMenuItem(unnotedItemId, menuTarget, location);
    }

    private String resolveMenuTarget(String eventTarget, int itemId) {
        if (eventTarget != null && !eventTarget.isBlank()) {
            return eventTarget;
        }
        ItemComposition item = client.getItemDefinition(itemId);
        return "<col=ff9040>" + item.getName() + "</col>";
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.*;
import com.runeassist.flip.ui.NpcHighlightOverlay;
import com.runeassist.flip.ui.WidgetHighlightOverlay;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class HighlightController {
    private static final Rectangle CLOSE_BUTTON_HIGHLIGHT_BOUNDS = new Rectangle(2, 2, 19, 19);
    private static final String GE_CLERK_NAME = "Grand Exchange Clerk";
    private static final String BANKER_NAME = "Banker";
    private static final String BOB_BARTER_NAME = "Bob Barter";

    private final RuneAssistConfig config;
    private final SuggestionManager suggestionManager;
    private final PausedManager pausedManager;
    private final SuggestionPreferencesManager suggestionPreferencesManager;
    private final GrandExchange grandExchange;
    private final AccountStatusManager accountStatusManager;
    private final Client client;
    private final OfferManager offerManager;
    private final OverlayManager overlayManager;
    private final HighlightColorController highlightColorController;
    private final PluginManager pluginManager;
    private final ModelOutlineRenderer modelOutlineRenderer;

    private final ArrayList<Overlay> highlightOverlays = new ArrayList<>();
    private volatile boolean active = true;
    private final AtomicInteger generation = new AtomicInteger(0);

    public void activate() {
        active = true;
        generation.incrementAndGet();
    }

    public void deactivateAndRemoveAll() {
        active = false;
        final int clearGeneration = generation.incrementAndGet();
        Runnable clearTask = () -> clearOverlaysIfCurrentGeneration(clearGeneration);
        if (SwingUtilities.isEventDispatchThread()) {
            clearTask.run();
            return;
        }
        SwingUtilities.invokeLater(clearTask);
    }

    public void redraw() {
        if (!active) {
            return;
        }
        removeAll();
        if (!active) {
            return;
        }
        if (!config.suggestionHighlights()) {
            log.debug("highlight redraw: suggestionHighlights config is OFF");
            return;
        }
        if (pausedManager.isPaused()) {
            log.debug("highlight redraw: skipped, suggestions paused");
            return;
        }
        if (offerManager.isOfferJustPlaced()) {
            log.debug("highlight redraw: skipped, offer just placed");
            return;
        }
        Suggestion suggestion = suggestionManager.getSuggestion();
        if (suggestion == null) {
            log.debug("highlight redraw: skipped, suggestion is null");
            return;
        }
        if (suggestion.isDecantSuggestion()) {
            highlightDecant(suggestion);
            return;
        }
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        boolean sellFromBank = accountStatus != null && accountStatus.shouldSellFromBank(suggestion);
        boolean isCollectNeeded = accountStatus != null
                && accountStatus.isCollectNeeded(suggestion, grandExchange.isSetupOfferOpen());
        boolean goToBank = sellFromBank && !isCollectNeeded;
        log.debug("highlight redraw: type={} item={} geOpen={} homeScreen={} slotOpen={} bankOpen={} goToBank={} accountStatusNull={}",
                suggestion.getType(), suggestion.getItemId(), grandExchange.isOpen(),
                grandExchange.isHomeScreenOpen(), grandExchange.isSlotOpen(), BankWidgets.isBankOpen(client), goToBank,
                accountStatus == null);
        if (goToBank && grandExchange.isOpen() && highlightGrandExchangeCloseButton(suggestion)) {
            return;
        }
        if (!goToBank && BankWidgets.isBankOpen(client) && !suggestion.isWaitSuggestion()
                && highlightBankCloseButton(suggestion)) {
            return;
        }
        if (goToBank && drawSellFromBankHighlight(suggestion)) {
            return;
        }
        if (!grandExchange.isOpen()) {
            if (!BankWidgets.isBankOpen(client)) {
                highlightNpcAtGrandExchange(suggestion, accountStatus, goToBank);
            }
            return;
        }
        if (grandExchange.isHomeScreenOpen()) {
            boolean drew = drawHomeScreenHighLights(suggestion);
            log.debug("highlight redraw: drawHomeScreenHighLights returned {}", drew);
        } else if (grandExchange.isSlotOpen()) {
            drawOfferScreenHighlights(suggestion);
        } else {
            log.debug("highlight redraw: GE open but neither home screen nor slot screen detected");
        }
    }

    private void highlightDecant(Suggestion suggestion) {
        if (grandExchange.isOpen()) {
            highlightGrandExchangeCloseButton(suggestion);
            return;
        }
        if (BankWidgets.isBankOpen(client)) {
            highlightBankCloseButton(suggestion);
            return;
        }
        NPC bob = findClosestNpcByName(BOB_BARTER_NAME);
        if (bob == null) {
            return;
        }
        addNpcHighlight(bob, glowBlue(suggestion.isBuyDumpSuggestion()));
    }

    private void highlightNpcAtGrandExchange(Suggestion suggestion, AccountStatus accountStatus, boolean goToBank) {
        if (accountStatus == null) {
            return;
        }
        NPC clerk = findClosestNpcByName(GE_CLERK_NAME);
        if (clerk == null) {
            return;
        }
        NPC target;
        if (goToBank) {
            target = findClosestNpcByName(BANKER_NAME);
        } else if (drawHomeScreenHighLights(suggestion)) {
            target = clerk;
        } else {
            return;
        }
        if (target == null) {
            return;
        }
        addNpcHighlight(target, glowBlue(suggestion.isBuyDumpSuggestion()));
    }

    private Supplier<Color> glowBlue(boolean flash) {
        return () -> {
            Color base = highlightColorController.getBlueColor(flash);
            if (base == null) {
                return null;
            }
            return new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.min(255, base.getAlpha() * 3));
        };
    }

    private NPC findClosestNpcByName(String name) {
        Player player = client.getLocalPlayer();
        if (player == null) {
            return null;
        }
        WorldPoint playerLocation = player.getWorldLocation();
        if (playerLocation == null) {
            return null;
        }
        NPC closest = null;
        int closestDistance = Integer.MAX_VALUE;
        for (NPC npc : client.getNpcs()) {
            if (npc == null || !name.equals(npc.getName())) {
                continue;
            }
            WorldPoint npcLocation = npc.getWorldLocation();
            if (npcLocation == null) {
                continue;
            }
            int distance = npcLocation.distanceTo(playerLocation);
            if (distance < closestDistance) {
                closestDistance = distance;
                closest = npc;
            }
        }
        return closest;
    }

    private void addNpcHighlight(NPC npc, Supplier<Color> colorSupplier) {
        if (!active || npc == null) {
            return;
        }
        final int addGeneration = generation.get();
        SwingUtilities.invokeLater(() -> {
            if (!active || generation.get() != addGeneration) {
                return;
            }
            NpcHighlightOverlay overlay = new NpcHighlightOverlay(npc, colorSupplier, modelOutlineRenderer);
            highlightOverlays.add(overlay);
            overlayManager.add(overlay);
        });
    }

    private boolean drawHomeScreenHighLights(Suggestion suggestion) {
        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(flashHighlight);
        Supplier<Color> redHighlight = () -> highlightColorController.getRedColor(flashHighlight);
        Supplier<Color> amberHighlight = () -> highlightColorController.getAmberColor(flashHighlight);
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (accountStatus.isCollectNeeded(suggestion, grandExchange.isSetupOfferOpen())) {
            Widget collectButton = grandExchange.getCollectButton();
            if (collectButton != null) {
                add(collectButton, blueHighlight, new Rectangle(2, 1, 81, 18));
            }
            return true;
        }
        if (suggestion.isAbortSuggestion()) {
            int slot = grandExchange.slotForSuggestion(suggestion);
            if (slot >= 0) {
                add(grandExchange.getSlotWidget(slot), redHighlight);
            }
            return true;
        }
        if (suggestion.isModifySuggestion()) {
            int slot = grandExchange.slotForSuggestion(suggestion);
            if (slot >= 0) {
                Widget slotWidget = grandExchange.getSlotWidget(slot);
                if (slotWidget != null && !slotWidget.isHidden()) {
                    add(slotWidget, amberHighlight);
                }
            }
            return true;
        }
        // Only a real buy card lights the buy button. The inherited "scanning for
        // dumps" highlight during a WAIT made sense when the client searched the GE
        // itself; RuneAssist's dump alerts arrive from the server, so a lit button
        // with nothing to buy just looks like a bug.
        if (suggestion.isBuySuggestion()) {
            highlightCreateBuyOfferButton(accountStatus, blueHighlight);
            return true;
        }
        if (suggestion.isSellSuggestion() && accountStatus.hasSufficientInventoryForSellSuggestion(suggestion)) {
            Widget itemWidget = BankWidgets.geInventoryItem(client, suggestion.getItemId());
            log.debug("highlight sell branch: itemWidgetNull={} itemWidgetHidden={}",
                    itemWidget == null, itemWidget != null && itemWidget.isHidden());
            if (itemWidget != null && !itemWidget.isHidden()) {
                add(itemWidget, blueHighlight, new Rectangle(0, 0, 34, 32));
            }
            return true;
        }
        if (suggestion.isSellSuggestion()) {
            log.debug("highlight sell branch: hasSufficientInventoryForSellSuggestion=false for item={}",
                    suggestion.getItemId());
        }
        return false;
    }

    private boolean drawSellFromBankHighlight(Suggestion suggestion) {
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(suggestion.isBuyDumpSuggestion());
        Widget bankItemWidget = BankWidgets.bankItem(client, suggestion.getItemId());
        if (bankItemWidget != null && !bankItemWidget.isHidden()) {
            add(bankItemWidget, blueHighlight, new Rectangle(0, 0, 34, 32));
            return true;
        }
        Widget portfolioTagButton = BankWidgets.portfolioTagButton(client, pluginManager, config.portfolioBankTag());
        if (portfolioTagButton != null) {
            add(portfolioTagButton, blueHighlight);
            return true;
        }
        return false;
    }

    private boolean highlightGrandExchangeCloseButton(Suggestion suggestion) {
        return highlightCloseButton(BankWidgets.geCloseButton(client), suggestion);
    }

    private boolean highlightBankCloseButton(Suggestion suggestion) {
        return highlightCloseButton(BankWidgets.bankCloseButton(client), suggestion);
    }

    private boolean highlightCloseButton(Widget closeButton, Suggestion suggestion) {
        if (closeButton == null || closeButton.isHidden()) {
            return false;
        }
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(suggestion.isBuyDumpSuggestion());
        add(closeButton, blueHighlight, new Rectangle(CLOSE_BUTTON_HIGHLIGHT_BOUNDS));
        return true;
    }

    private void highlightCreateBuyOfferButton(AccountStatus accountStatus, Supplier<Color> colorSupplier) {
        int slotId = accountStatus.findEmptySlot();
        if (slotId == -1) {
            return;
        }
        Widget buyButton = grandExchange.getBuyButton(slotId);
        if (buyButton != null && !buyButton.isHidden()) {
            add(buyButton, colorSupplier, new Rectangle(0, 0, 45, 44));
        }
    }

    private void drawOfferScreenHighlights(Suggestion suggestion) {
        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(flashHighlight);
        GEOfferScreenSetupOfferState s = grandExchange.getOfferScreenSetupOfferState();
        if (s == null) {
            return;
        }
        if (s.offerDetailsCorrect(suggestion)) {
            highlightConfirm(blueHighlight);
            return;
        }
        boolean offerTypeMatches = Objects.equals(s.offerType, suggestion.offerType());
        boolean itemMatches = s.currentItemId == suggestion.getItemId();

        if (suggestion.isBuyDumpSuggestion()) {
            if (!offerTypeMatches || accountStatusManager.getAccountStatus().isCollectNeeded(suggestion, grandExchange.isSetupOfferOpen())) {
                highlightBackButton(blueHighlight);
            } else if (!s.searchOpen && s.currentItemId != -1 && !itemMatches) {
                highlightItemSearchButton(blueHighlight);
            } else if (itemMatches) {
                if (s.offerPrice != suggestion.getPrice()) {
                    highlightPrice(blueHighlight);
                }
                highlightQuantity(suggestion, s.offerQuantity, blueHighlight);
            } else if (s.searchOpen) {
                highlightItemInSearch(suggestion, blueHighlight);
            }
            return;
        }

        if (isCustomChoiceItem(s, offerTypeMatches, itemMatches) && !suggestion.isModifySuggestion()) {
            if (s.offerPrice == offerManager.getViewedSlotItemPrice()) {
                highlightConfirm(blueHighlight);
            } else {
                highlightPrice(blueHighlight);
            }
            return;
        }

        if (offerTypeMatches && itemMatches) {
            if (s.offerPrice != suggestion.getPrice()) {
                highlightPrice(blueHighlight);
            }
            highlightQuantity(suggestion, s.offerQuantity, blueHighlight);
            return;
        }
        if (suggestion.isAbortSuggestion()
                || ((suggestion.isSellSuggestion() || suggestion.isModifySuggestion()) && s.isEmptyBuyState())) {
            highlightBackButton(blueHighlight);
            return;
        }
        if (offerTypeMatches && s.currentItemId == -1 && s.searchOpen) {
            highlightItemInSearch(suggestion, blueHighlight);
        }
    }

    private boolean isCustomChoiceItem(GEOfferScreenSetupOfferState s, boolean offerTypeMatches, boolean itemMatches) {
        return s.currentItemId != -1 && ((!offerTypeMatches && s.offerType.equals("sell")) || (!s.searchOpen && !itemMatches))
                && s.currentItemId == offerManager.getViewedSlotItemId()
                && offerManager.getViewedSlotItemPrice() > -1;
    }

    private void highlightItemInSearch(Suggestion suggestion, Supplier<Color> colorSupplier) {
        if (!client.getVarcStrValue(VarClientStr.INPUT_TEXT).isEmpty()) {
            return;
        }
        Widget searchResults = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        if (searchResults == null) {
            return;
        }
        for (Widget widget : searchResults.getDynamicChildren()) {
            if (widget.getName().equals("<col=ff9040>" + suggestion.getName() + "</col>")) {
                add(widget, colorSupplier);
                return;
            }
        }
        Widget itemWidget = searchResults.getChild(3);
        if (itemWidget != null && itemWidget.getItemId() == suggestion.getItemId()) {
            add(itemWidget, colorSupplier);
        }
    }

    private void highlightPrice(Supplier<Color> colorSupplier) {
        Widget setPriceButton = grandExchange.getSetPriceButton();
        if (setPriceButton != null) {
            add(setPriceButton, colorSupplier, new Rectangle(1, 6, 33, 23));
        }
    }

    private void highlightQuantity(Suggestion suggestion, int offerQuantity, Supplier<Color> colorSupplier) {
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (offerQuantity != suggestion.getQuantity()) {
            Widget setQuantityButton;
            if (accountStatus.getInventory().getTotalAmount(suggestion.getItemId()) == suggestion.getQuantity()
                    && suggestion.isSellSuggestion()) {
                setQuantityButton = grandExchange.getSetQuantityAllButton();
            } else {
                setQuantityButton = grandExchange.getSetQuantityButton();
            }
            if (setQuantityButton != null) {
                add(setQuantityButton, colorSupplier, new Rectangle(1, 6, 33, 23));
            }
        }
    }

    private void highlightConfirm(Supplier<Color> colorSupplier) {
        Widget confirmButton = grandExchange.getConfirmButton();
        if (confirmButton != null) {
            add(confirmButton, colorSupplier, new Rectangle(1, 1, 150, 38));
        }
    }

    private void highlightItemSearchButton(Supplier<Color> colorSupplier) {
        Widget searchWidget = BankWidgets.geItemSearchButton(client);
        if (searchWidget != null) {
            add(searchWidget, colorSupplier);
        }
    }

    private void highlightBackButton(Supplier<Color> colorSupplier) {
        Widget backButton = grandExchange.getBackButton();
        if (backButton != null) {
            add(backButton, colorSupplier);
        }
    }

    private void add(Widget widget, Supplier<Color> colorSupplier, Rectangle adjustedBounds) {
        if (!active || widget == null) {
            return;
        }
        final int addGeneration = generation.get();
        SwingUtilities.invokeLater(() -> {
            if (!active || generation.get() != addGeneration) {
                return;
            }
            WidgetHighlightOverlay overlay = new WidgetHighlightOverlay(widget, colorSupplier, adjustedBounds);
            highlightOverlays.add(overlay);
            overlayManager.add(overlay);
        });
    }

    private void add(Widget widget, Supplier<Color> colorSupplier) {
        if (widget == null) {
            return;
        }
        add(widget, colorSupplier, new Rectangle(0, 0, widget.getWidth(), widget.getHeight()));
    }

    public void removeAll() {
        final int clearGeneration = generation.incrementAndGet();
        SwingUtilities.invokeLater(() -> clearOverlaysIfCurrentGeneration(clearGeneration));
    }

    private void clearOverlaysIfCurrentGeneration(int expectedGeneration) {
        if (generation.get() != expectedGeneration) {
            return;
        }
        highlightOverlays.forEach(overlayManager::remove);
        highlightOverlays.clear();
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.*;
import com.runeassist.flip.rs.PortfolioStateRS;
import com.runeassist.flip.ui.UIUtilities;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.List;

@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class InventorySlotTooltipDataProvider {

    private final ItemManager itemManager;
    private final SuggestionManager suggestionManager;
    private final ItemController itemController;
    private final PortfolioStateRS portfolioStateRS;

    public InventorySlotTooltipData getTooltipData(int itemId, int quantity, TooltipHoverSource source) {
        if (!portfolioStateRS.get().isLoaded()) {
            return null;
        }
        int unnotedItemId = itemController.toUnnotedItemId(itemId);
        PortfolioItemCardData itemData = portfolioStateRS.get().getItemCardDataByItemId().get(unnotedItemId);
        if (itemData == null) {
            return null;
        }

        String itemName = itemManager.getItemComposition(itemData.getItemId()).getName();
        Suggestion suggestion = suggestionManager.getSuggestion();
        Suggestion.PortfolioItem portfolioItem = findPortfolioItem(suggestion, itemData.getItemId());
        List<String> lines = buildTooltipLines(itemData, portfolioItem, source);
        return new InventorySlotTooltipData(itemData.getItemId(), quantity, itemName, lines);
    }

    private List<String> buildTooltipLines(PortfolioItemCardData itemData, Suggestion.PortfolioItem portfolioItem, TooltipHoverSource source) {
        boolean inPortfolio = itemData.isInPortfolio();

        List<String> lines = new ArrayList<>(5);

        lines.add(formatQuantityLine(itemData.getRuneliteInventoryQuantity(), itemData.getSuggestionBankQuantity(), source));
        if (itemData.isPartiallyInPortfolio()) {
            lines.add("Quantity in Portfolio: " + NumberFormat.getIntegerInstance().format(itemData.getPortfolioQuantity()));
        }
        if (!inPortfolio) {
            Long totalValue = calculateValue(itemData);
            lines.add("Total value: " + (totalValue == null ? "Unknown" : UIUtilities.formatProfit(totalValue)));
        } else {
            lines.add("Time held: " + UIUtilities.formatDurationMinutes(itemData.getHeldMinutes()));
            lines.add("Avg buy price: " + (portfolioItem == null || portfolioItem.getAmount() <= 0
                    ? "Unknown"
                    : UIUtilities.formatProfit(portfolioItem.getUnitBuyPrice())));
            Long totalValue = calculateValue(itemData);
            lines.add("Total value: " + (totalValue == null ? "Unknown" : UIUtilities.formatProfit(totalValue)));
            Long unrealizedProfit = itemData.getUnrealizedUnitProfit() == null ? null : itemData.inventoryTooltipUnrealizedProfit();
            lines.add("Unrealized Profit: " + (unrealizedProfit == null ? "Unknown" : UIUtilities.formatProfit(unrealizedProfit)));
            String unrealizedRoi = calculateUnrealizedRoi(itemData, portfolioItem);
            lines.add("Unrealized ROI: " + (unrealizedRoi == null ? "Unknown" : unrealizedRoi));
        }
        return lines;
    }

    private String calculateUnrealizedRoi(PortfolioItemCardData itemData, Suggestion.PortfolioItem portfolioItem) {
        if (portfolioItem == null || portfolioItem.getAmount() <= 0 || portfolioItem.getUnitBuyPrice() <= 0 || itemData.getUnrealizedUnitProfit() == null) {
            return null;
        }
        double roi = (double) itemData.getUnrealizedUnitProfit() / (double) portfolioItem.getUnitBuyPrice();
        return String.format("%.2f%%", roi * 100.0d);
    }

    private Suggestion.PortfolioItem findPortfolioItem(Suggestion suggestion, int itemId) {
        if (suggestion == null || suggestion.getPortfolioItems() == null || suggestion.getPortfolioItems().isEmpty()) {
            return null;
        }
        for (Suggestion.PortfolioItem portfolioItem : suggestion.getPortfolioItems()) {
            if (portfolioItem != null && portfolioItem.getItemId() == itemId) {
                return portfolioItem;
            }
        }
        return null;
    }

    private Long calculateValue(PortfolioItemCardData itemData) {
        long unitPrice = itemData.getPostTaxSellUnitPrice();
        if (unitPrice <= 0) {
            return null;
        }
        long totalQuantity = Math.max(0L, (long) itemData.getRuneliteInventoryQuantity() + itemData.getSuggestionBankQuantity());
        return unitPrice * totalQuantity;
    }

    private String formatQuantityLine(int inventoryQuantity, long bankQuantity, TooltipHoverSource source) {
        NumberFormat fmt = NumberFormat.getIntegerInstance();
        String invPart = "Inventory: " + fmt.format(Math.max(0, inventoryQuantity));
        String bankPart = "Bank: " + fmt.format(Math.max(0L, bankQuantity));

        if (source == TooltipHoverSource.BANK) {
            if (inventoryQuantity <= 0) {
                return bankPart;
            }
            return bankPart + ", " + invPart;
        }
        if (bankQuantity <= 0) {
            return invPart;
        }
        return invPart + ", " + bankPart;
    }

}

package com.runeassist.flip.controller;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.util.Text;

import java.awt.Rectangle;

/** Shared bank / GE widget lookups for highlights and portfolio menus. */
public final class BankWidgets {
    static final int BANK_WIDGET_GROUP = 12;
    static final int[] BANK_ITEM_CONTAINER_CHILDREN = {12, 13, 89};
    static final int BANK_INVENTORY_WIDGET_GROUP = 15;
    static final int BANK_INVENTORY_WIDGET_CHILD = 3;

    private static final String PORTFOLIO_BANK_TAG = "portfolio";
    private static final int BANK_TAG_TAB_CHILD_OFFSET = 4;
    private static final int CLOSE_BUTTON_INDEX = 11;

    private BankWidgets() {
    }

    public static boolean isBankOpen(Client client) {
        Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        return bank != null && !bank.isHidden();
    }

    public static Widget bankCloseButton(Client client) {
        return frameChild(client.getWidget(InterfaceID.Bankmain.FRAME), CLOSE_BUTTON_INDEX);
    }

    public static Widget geCloseButton(Client client) {
        return frameChild(client.getWidget(InterfaceID.GeOffers.FRAME), CLOSE_BUTTON_INDEX);
    }

    public static Widget geItemSearchButton(Client client) {
        Widget setupContainer = client.getWidget(InterfaceID.GE_OFFERS, 26);
        if (setupContainer == null) {
            return null;
        }
        Widget[] children = setupContainer.getChildren();
        return children != null && children.length > 0 ? children[0] : null;
    }

    /** Prefer noted GE-side inventory match, else unnoted. */
    public static Widget geInventoryItem(Client client, int unnotedItemId) {
        Widget inventory = client.getWidget(InterfaceID.GE_OFFERS_SIDE, 0);
        if (inventory == null) {
            return null;
        }
        Widget[] children = inventory.getDynamicChildren();
        if (children == null) {
            return null;
        }
        Widget noted = null;
        Widget unnoted = null;
        for (Widget widget : children) {
            if (widget == null || widget.isHidden() || widget.getItemQuantity() <= 0) {
                continue;
            }
            int itemId = widget.getItemId();
            if (itemId <= 0 || !matchesItemId(client, itemId, unnotedItemId)) {
                continue;
            }
            if (client.getItemDefinition(itemId).getNote() != -1) {
                noted = widget;
            } else {
                unnoted = widget;
            }
        }
        return noted != null ? noted : unnoted;
    }

    public static Widget bankItem(Client client, int unnotedItemId) {
        for (int childId : BANK_ITEM_CONTAINER_CHILDREN) {
            Widget bankItems = client.getWidget(BANK_WIDGET_GROUP, childId);
            if (bankItems == null || bankItems.isHidden()) {
                continue;
            }
            Widget itemWidget = visibleItem(client, bankItems, unnotedItemId);
            if (itemWidget != null) {
                return itemWidget;
            }
        }
        return null;
    }

    public static Widget portfolioTagButton(Client client, PluginManager pluginManager, boolean enabled) {
        if (!enabled) {
            return null;
        }
        BankTagsPlugin bankTagsPlugin = BankTagsLookup.findActive(pluginManager);
        if (bankTagsPlugin == null || PORTFOLIO_BANK_TAG.equals(bankTagsPlugin.getActiveTag())) {
            return null;
        }
        Widget parent = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
        if (parent == null || parent.isHidden() || parent.getChildren() == null) {
            return null;
        }
        Widget[] children = parent.getChildren();
        for (int i = BANK_TAG_TAB_CHILD_OFFSET; i < children.length; i += 2) {
            Widget button = children[i];
            if (button == null || button.isHidden()) {
                continue;
            }
            String widgetName = button.getName();
            if (widgetName != null && PORTFOLIO_BANK_TAG.equals(Text.removeTags(widgetName))) {
                return button;
            }
        }
        return null;
    }

    public static boolean matchesItemId(Client client, int itemId, int unnotedItemId) {
        if (itemId == unnotedItemId) {
            return true;
        }
        if (itemId <= 0) {
            return false;
        }
        ItemComposition itemComposition = client.getItemDefinition(itemId);
        return itemComposition.getNote() != -1 && itemComposition.getLinkedNoteId() == unnotedItemId;
    }

    private static Widget frameChild(Widget frame, int index) {
        if (frame == null || frame.getDynamicChildren() == null) {
            return null;
        }
        Widget[] children = frame.getDynamicChildren();
        return children.length > index ? children[index] : null;
    }

    private static Widget visibleItem(Client client, Widget itemContainer, int unnotedItemId) {
        Widget[] children = itemContainer.getDynamicChildren();
        if (children == null) {
            return null;
        }
        Rectangle containerBounds = itemContainer.getBounds();
        boolean clip = containerBounds != null && containerBounds.width > 0 && containerBounds.height > 0;
        for (Widget widget : children) {
            if (widget == null || widget.isHidden() || widget.getItemQuantity() <= 0) {
                continue;
            }
            if (!matchesItemId(client, widget.getItemId(), unnotedItemId)) {
                continue;
            }
            Rectangle bounds = widget.getBounds();
            if (clip && (bounds == null || !containerBounds.intersects(bounds))) {
                continue;
            }
            return widget;
        }
        return null;
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.controller.history.AccountHttp;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;

/** Opt-in bug reports. Device token attributes {@code /v1/account/feedback} after dialog confirm. */
@Slf4j
@Singleton
public class BugReportClient {

    public static final String CONFIG_GROUP = "runeassistflip";
    public static final String KEY_DEVICE_TOKEN = "cloudDeviceToken";
    public static final String KEY_USER_ID = "cloudUserId";
    public static final String DEFAULT_ORIGIN = "https://runeassist.com";

    private final AccountHttp api;
    private final ScheduledExecutorService executor;

    @Inject
    public BugReportClient(AccountHttp api, @Named("runeAssistExecutor") ScheduledExecutorService executor) {
        this.api = api;
        this.executor = executor;
    }

    public String websiteUrl() {
        return DEFAULT_ORIGIN;
    }

    /** Submit after consent dialog. Registers a device token if needed. */
    public void reportBug(String displayName, String message, byte[] screenshotPng, Consumer<Boolean> callback) {
        executor.execute(() -> {
            boolean ok;
            try {
                ensureRegistered();
                JsonObject req = new JsonObject();
                req.addProperty("message", message);
                if (displayName != null && !displayName.isEmpty()) {
                    req.addProperty("displayName", displayName);
                }
                if (screenshotPng != null && screenshotPng.length > 0) {
                    req.addProperty("screenshot", java.util.Base64.getEncoder().encodeToString(screenshotPng));
                }
                ok = api.post("/v1/account/feedback", req, true) != null;
            } catch (Exception e) {
                log.warn("report bug failed: {}", e.getMessage());
                ok = false;
            }
            if (callback != null) {
                boolean result = ok;
                SwingUtilities.invokeLater(() -> callback.accept(result));
            }
        });
    }

    private synchronized void ensureRegistered() throws Exception {
        if (api.isLinked()) {
            return;
        }
        JsonObject body = api.post("/v1/account/register", new JsonObject(), false);
        if (body == null || !body.has("deviceToken") || !body.has("userId")) {
            throw new IllegalStateException("register failed");
        }
        api.storeToken(body.get("userId").getAsString(), body.get("deviceToken").getAsString());
    }
}

package com.runeassist.flip.controller;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.stream.Stream;

@Slf4j
public class Persistance {
    public static Gson gson;
    public static final String LOGIN_RESPONSE_JSON_FILE = "login-response.json";
    public static final String UNACKED_TRANSACTIONS_FILE_TEMPLATE = "%s_unacked.jsonl";
    /**
     * The plugin's data directory as handed out by RuneLite (Plugin.getPluginDirectory()), which
     * the Plugin Hub requires for all file access. Set once by the plugin's Guice provider.
     */
    private static volatile Filepath dataDir;

    public static void setDataDir(Filepath dir) {
        dataDir = dir;
    }

    public static Filepath dataDir() {
        Filepath dir = dataDir;
        if (dir == null) {
            throw new IllegalStateException("RuneAssist data directory is not initialised yet");
        }
        return dir;
    }

    /** A file directly inside the data directory; a name with separators or dots-only is rejected. */
    public static Filepath file(String name) {
        return dataDir().joinSegment(name);
    }

    public static void setUp(Gson gson) throws IOException {
        Persistance.gson = gson;
        Filepath dir = dataDir();
        if (!dir.exists()) {
            dir.createDirectories();
        }
        createRequiredFiles();
    }

    public static boolean hasExistingInstallation() {
        Filepath dir = dataDir;
        if (dir == null || !dir.isDirectory()) {
            return false;
        }
        try (Stream<Filepath> entries = dir.walk(1)) {
            return entries.anyMatch(p -> !p.equals(dir));
        } catch (IOException e) {
            return false;
        }
    }

    private static void createRequiredFiles() throws IOException {
        generateFileIfDoesNotExist(LOGIN_RESPONSE_JSON_FILE);
    }

    private static void generateFileIfDoesNotExist(String filename) throws IOException {
        Filepath file = file(filename);
        if (!file.exists()) {
            file.write(new byte[0]);
        }
    }

    /** Read a whole UTF-8 text file. */
    public static String readString(Filepath file) throws IOException {
        try (InputStream in = file.openInputStream()) {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }


    public static List<com.runeassist.flip.model.Transaction> loadUnackedTransactions(String displayName) {
        java.util.List<com.runeassist.flip.model.Transaction> transactions = new java.util.ArrayList<>();
        Filepath file = file(String.format(UNACKED_TRANSACTIONS_FILE_TEMPLATE, hashDisplayName(displayName)));
        if (!file.exists()) {
            return transactions;
        }
        java.util.Set<java.util.UUID> added = new java.util.HashSet<>();
        try (BufferedReader reader = file.openBufferedReader()) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isEmpty() || gson == null) {
                    continue;
                }
                try {
                    com.runeassist.flip.model.Transaction transaction = gson.fromJson(line, com.runeassist.flip.model.Transaction.class);
                    if (transaction != null && transaction.getId() != null && added.add(transaction.getId())) {
                        transactions.add(transaction);
                    }
                } catch (com.google.gson.JsonSyntaxException e) {
                    log.warn("error deserializing unacked transaction line in {}", file, e);
                }
            }
        } catch (java.io.IOException e) {
            log.warn("error loading unacked transactions {}", file, e);
        }
        log.debug("loaded {} unacked transactions for {}", transactions.size(), displayName);
        return transactions;
    }

    public static void storeUnackedTransactions(java.util.List<com.runeassist.flip.model.Transaction> transactions, String displayName) {
        Filepath file = file(String.format(UNACKED_TRANSACTIONS_FILE_TEMPLATE, hashDisplayName(displayName)));
        try (BufferedWriter w = file.openBufferedWriter()) {
            if (transactions != null && gson != null) {
                for (com.runeassist.flip.model.Transaction transaction : transactions) {
                    w.write(gson.toJson(transaction));
                    w.newLine();
                }
            }
        } catch (java.io.IOException e) {
            log.warn("error storing unacked transactions to {}", file, e);
        }
    }

    public static String hashDisplayName(String displayName) {
        if(displayName == null) {
            return "null";
        }
        // we hash the display name just to ensure that it's a valid file name
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] hashBytes = digest.digest(displayName.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.model.GEOfferScreenSetupOfferState;
import com.runeassist.flip.model.Suggestion;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;

import static net.runelite.api.VarPlayer.CURRENT_GE_ITEM;
import static net.runelite.api.Varbits.GE_OFFER_CREATION_TYPE;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GrandExchange {
    private final Client client;

    boolean isHomeScreenOpen() {
        return isOpen() && !isSlotOpen();
    }

    public boolean isSlotOpen() {
        return getOpenSlot() != -1;
    }

    String getOfferType() {
        return client.getVarbitValue(GE_OFFER_CREATION_TYPE) == 1 ? "sell" : "buy";
    }

    /** Item currently in the Set up offer editor; -1 when none. */
    public int getCurrentItemId() {
        return client.getVarpValue(CURRENT_GE_ITEM);
    }

    boolean isCollectButtonVisible() {
        Widget w = client.getWidget(InterfaceID.GE_OFFERS, 6);
        if (w == null) {
            return false;
        }
        Widget[] children = w.getChildren();
        if(children == null) {
            return false;
        }
        return Arrays.stream(children).anyMatch(c -> !c.isHidden() && "Collect".equals(c.getText()));
    }

    public int getOpenSlot() {
        return client.getVarbitValue(VarbitID.GE_SELECTEDSLOT) - 1;
    }

    Widget getSlotWidget(int slot) {
        return client.getWidget(InterfaceID.GE_OFFERS, 7 + slot);
    }

    /**
     * Slot to highlight / left-click-swap for a suggestion. Prefer the live filling
     * offer whose itemId matches the card, not a stale boxId (wrong-item editor).
     */
    int slotForSuggestion(Suggestion suggestion) {
        if (suggestion == null) {
            return -1;
        }
        return slotMatchingItem(suggestion.getItemId(), suggestion.getBoxId());
    }

    int slotMatchingItem(int itemId, int fallbackSlot) {
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null || itemId <= 0) {
            return fallbackSlot;
        }
        if (fallbackSlot >= 0 && fallbackSlot < offers.length && isFillingOffer(offers[fallbackSlot])
                && offers[fallbackSlot].getItemId() == itemId) {
            return fallbackSlot;
        }
        for (int i = 0; i < offers.length; i++) {
            GrandExchangeOffer o = offers[i];
            if (isFillingOffer(o) && o.getItemId() == itemId) {
                return i;
            }
        }
        return fallbackSlot;
    }

    boolean hasFillingOffer(int itemId) {
        return slotMatchingItem(itemId, -1) >= 0;
    }

    boolean hasFillingSellOffer(int itemId) {
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        return offers != null && Arrays.stream(offers).anyMatch(offer -> offer != null
                && offer.getItemId() == itemId && offer.getState() == GrandExchangeOfferState.SELLING);
    }

    private static boolean isFillingOffer(GrandExchangeOffer o) {
        if (o == null) {
            return false;
        }
        GrandExchangeOfferState st = o.getState();
        return st == GrandExchangeOfferState.BUYING || st == GrandExchangeOfferState.SELLING;
    }

    Widget getBuyButton(int slot) {
        Widget slotWidget = getSlotWidget(slot);
        if (slotWidget == null) {
            return null;
        }
        return slotWidget.getChild(0);
    }

    Widget getCollectButton() {
        Widget topBar = client.getWidget(InterfaceID.GE_OFFERS, 6);
        if (topBar == null) {
            return null;
        }
        return topBar.getChild(2);
    }

    Widget getOfferContainerWidget() {
        return client.getWidget(InterfaceID.GE_OFFERS, 26);
    }

    Widget getConfirmButton() {
        Widget offerContainer = getOfferContainerWidget();
        if (offerContainer == null) {
            return null;
        }
        return offerContainer.getChild(58);
    }

    int getOfferQuantity() {
        return client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY);
    }

    int getOfferPrice() {
        return client.getVarbitValue(VarbitID.GE_NEWOFFER_PRICE);
    }

    boolean isOfferTypeSell() {
        return client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) == 1;
    }

    public boolean isOpen() {
        Widget offers = client.getWidget(InterfaceID.GE_OFFERS, 7);
        Widget editor = getOfferContainerWidget();
        // Home slot widgets can be hidden while the offer editor is visible.
        return offers != null && !offers.isHidden() || editor != null && !editor.isHidden();
    }

    public boolean isPreviousSearchSet() {
        return client.getVarpValue(VarPlayerID.GE_LAST_SEARCHED) != -1;
    }

    public boolean showLastSearchEnabled() {
        return client.getVarbitValue(VarbitID.DISABLE_LAST_SEARCHED) == 0;
    }

    public Widget getSetQuantityButton() {
        Widget offerContainer = getOfferContainerWidget();
        if (offerContainer == null) {
            return null;
        }
        return offerContainer.getChild(51);
    }

    public Widget getSetPriceButton() {
        Widget offerContainer = getOfferContainerWidget();
        if (offerContainer == null) {
            return null;
        }
        return offerContainer.getChild(54);
    }

    public Widget getSetQuantityAllButton() {
        Widget offerContainer = getOfferContainerWidget();
        if (offerContainer == null) {
            return null;
        }
        return offerContainer.getChild(50);
    }

    public GEOfferScreenSetupOfferState getOfferScreenSetupOfferState() {
        if (!isSlotOpen() || !isSetupOfferOpen()) {
            return null;
        }
        return new GEOfferScreenSetupOfferState(
                getOfferType(),
                client.getVarpValue(CURRENT_GE_ITEM),
                getOfferPrice(),
                getOfferQuantity(),
                isSearchOpen());
    }

    Widget getBackButton() {
        return client.getWidget(InterfaceID.GE_OFFERS, 4);
    }

    public boolean isSetupOfferOpen() {
        Widget confirmButton = getConfirmButton();
        return confirmButton != null && !confirmButton.isHidden();
    }

    private boolean isSearchOpen() {
        Widget searchResults = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        return searchResults != null && !searchResults.isHidden();
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.config.RuneAssistConfig;
import com.runeassist.flip.model.SuggestionManager;
import com.runeassist.flip.ui.flipsdialog.FlipsDialogController;
import net.runelite.api.Client;
import net.runelite.api.VarClientInt;
import net.runelite.api.widgets.ComponentID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.event.KeyEvent;


@Singleton
public class KeybindHandler {

    private final KeyManager keyManager;
    private final RuneAssistConfig config;
    private final ClientThread clientThread;
    private final SuggestionManager suggestionManager;
    private final Client client;
    private final GrandExchange grandExchange;
    private final OfferHandler offerHandler;
    private final SuggestionController suggestionController;
    private final FlipsDialogController flipsDialogController;
    private final KeyListener keyListener;


    @Inject
    public KeybindHandler(KeyManager keyManager, RuneAssistConfig config, ClientThread clientThread, SuggestionManager suggestionManager, Client client, GrandExchange grandExchange, OfferHandler offerHandler, SuggestionController suggestionController, FlipsDialogController flipsDialogController) {
        this.keyManager = keyManager;
        this.config = config;
        this.clientThread = clientThread;
        this.suggestionManager = suggestionManager;
        this.client = client;
        this.grandExchange = grandExchange;
        this.offerHandler = offerHandler;
        this.suggestionController = suggestionController;
        this.flipsDialogController = flipsDialogController;
        this.keyListener = createKeyListener();
    }

    public void register() {
        keyManager.registerKeyListener(keyListener);
    }

    public void unregister() {
        keyManager.unregisterKeyListener(keyListener);
    }


    private KeyListener createKeyListener() {
        return new KeyListener() {
            @Override
            public void keyTyped(KeyEvent e) {

            }

            @Override
            public void keyPressed(KeyEvent e) {
                // Prevent enter as a keybind as that will also submit the value
                if (e.getKeyCode() == KeyEvent.VK_ENTER) return;

                boolean quickSetPressed = keybindMatches(config.quickSetKeybind(), e);
                boolean skipSuggestionPressed = keybindMatches(config.skipSuggestionKeybind(), e);
                boolean openGraphPressed = keybindMatches(config.openGraphKeybind(), e);
                if (!quickSetPressed && !skipSuggestionPressed && !openGraphPressed) {
                    return;
                }

                clientThread.invokeLater(() -> handleKeybind(quickSetPressed, skipSuggestionPressed, openGraphPressed));
            }

            @Override
            public void keyReleased(KeyEvent e) {

            }

            private void handleKeybind(boolean quickSetPressed, boolean skipSuggestionPressed, boolean openGraphPressed) {
                var suggestion = suggestionManager.getSuggestion();

                var inputType = client.getVarcIntValue(VarClientInt.INPUT_TYPE);

                var isPriceOrQuantityBoxOpen = client.getWidget(ComponentID.CHATBOX_TITLE) != null
                        && inputType == 7
                        && client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER) != null
                        && grandExchange.isSlotOpen();

                if (quickSetPressed && isPriceOrQuantityBoxOpen) {
                    offerHandler.setSuggestedAction(suggestion);
                    return;
                }

                if (skipSuggestionPressed && !isPriceOrQuantityBoxOpen) {
                    suggestionController.skipSuggestion();
                    return;
                }

                if (openGraphPressed && !isPriceOrQuantityBoxOpen) {
                    flipsDialogController.openSuggestionPriceGraph();
                }
            }
        };
    }

    private boolean keybindMatches(Keybind keybind, KeyEvent e) {
        return keybind != null && keybind.matches(e);
    }
}

package com.runeassist.flip.controller.history;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.runeassist.flip.controller.BugReportClient;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

/** Shared JSON HTTP + device-token helpers for account APIs. */
@Slf4j
@Singleton
public class AccountHttp {

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final String UA = "RuneAssist-flip/1.0";

    private final OkHttpClient http;
    private final Gson gson;
    private final ConfigManager config;

    @Inject
    public AccountHttp(OkHttpClient http, Gson gson, ConfigManager config) {
        this.http = http;
        this.gson = gson;
        this.config = config;
    }

    public Gson gson() {
        return gson;
    }

    public String origin() {
        return BugReportClient.DEFAULT_ORIGIN;
    }

    public String deviceToken() {
        String t = config.getConfiguration(BugReportClient.CONFIG_GROUP, BugReportClient.KEY_DEVICE_TOKEN);
        return t == null || t.isEmpty() ? null : t;
    }

    public String userId() {
        return config.getConfiguration(BugReportClient.CONFIG_GROUP, BugReportClient.KEY_USER_ID);
    }

    public void storeToken(String userId, String token) {
        config.setConfiguration(BugReportClient.CONFIG_GROUP, BugReportClient.KEY_USER_ID, userId);
        config.setConfiguration(BugReportClient.CONFIG_GROUP, BugReportClient.KEY_DEVICE_TOKEN, token);
    }

    public boolean isLinked() {
        return deviceToken() != null && userId() != null;
    }

    public JsonObject get(String path, boolean authed) {
        Request.Builder b = new Request.Builder().url(origin() + path).header("User-Agent", UA).get();
        return auth(b, authed) ? execute(b.build()) : null;
    }

    public JsonObject post(String path, JsonObject json, boolean authed) {
        Request.Builder b = new Request.Builder()
                .url(origin() + path)
                .header("User-Agent", UA)
                .header("Content-Type", "application/json")
                .post(RequestBody.create(JSON, gson.toJson(json)));
        return auth(b, authed) ? execute(b.build()) : null;
    }

    private boolean auth(Request.Builder b, boolean authed) {
        if (!authed) {
            return true;
        }
        String token = deviceToken();
        if (token == null) {
            return false;
        }
        b.header("Authorization", "Bearer " + token);
        return true;
    }

    private JsonObject execute(Request request) {
        try (Response response = http.newCall(request).execute()) {
            String raw = response.body() != null ? response.body().string() : "";
            if (!response.isSuccessful()) {
                log.warn("account http {} {} → {}", request.method(), request.url().encodedPath(), response.code());
                return null;
            }
            return raw.isEmpty() ? new JsonObject() : gson.fromJson(raw, JsonObject.class);
        } catch (Exception e) {
            log.debug("account http {} failed: {}", request.url().encodedPath(), e.getMessage());
            return null;
        }
    }

    public static String urlEnc(String s) {
        return URLEncoder.encode(s, StandardCharsets.UTF_8);
    }
}

package com.runeassist.flip.controller;

import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PlayerLocationController {
    private static final WorldPoint GRAND_EXCHANGE_CENTER = new WorldPoint(3165, 3484, 0);
    private static final int NEAR_GE_DISTANCE_TILES = 20;

    private final Client client;

    public boolean isNearGE() {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return false;
        }

        WorldPoint playerLocation = localPlayer.getWorldLocation();
        if (playerLocation == null || playerLocation.getPlane() != GRAND_EXCHANGE_CENTER.getPlane()) {
            return false;
        }

        return playerLocation.distanceTo2D(GRAND_EXCHANGE_CENTER) <= NEAR_GE_DISTANCE_TILES;
    }
}

