    public void start() {
        if (started) {
            return;
        }
        started = true;
        executor.scheduleAtFixedRate(() -> {
            try {
                flush();
            } catch (Exception e) {
                log.debug("flip history sync flush: {}", e.getMessage());
            }
        }, FLUSH_SEC, FLUSH_SEC, TimeUnit.SECONDS);
        if (!isLinked()) {
            async("register", this::ensureRegistered);
        } else {
            fireStatus();
        }
    }

