            clientThread.invokeLater(() -> {
                if (!suggestionManager.isSuggestionRequestInProgress()) {
                    getSuggestionAsync();
                }
            });
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
        }
    }

    public void togglePause() {
        // Account identity, GE widgets and suggestion mutations belong to the client thread.
        clientThread.invokeLater(() -> {
            pausedManager.setPaused(!pausedManager.isPaused());
            syncTradingContext();
            if (suggestionPanel != null) suggestionPanel.refresh();
        });
    }

    void onGameTick() {
        if (!syncTradingContext()) return;
        if (accountStatusManager.releaseStaleOwnedModify(
                client.getGrandExchangeOffers(), grandExchange.isSlotOpen())) {
            markGhostModifyActioned();
            suggestionManager.setSuggestionNeeded(true);
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
        }
        if(suggestionManager.isSuggestionRequestInProgress()) {
            return;
        }
        reconcileUncollected();
        if (osrsLoginManager.hasJustLoggedIn()) {
            return;
        }
        if (shouldFetchNewSuggestion()) {
            getSuggestionAsync();
        }
    }

    private boolean shouldFetchNewSuggestion() {
        if (client.getTickCount() < suggestionManager.suggestionsDelayedUntil) {
            return false;
        }
        Suggestion p = suggestionManager.getSuggestion();
        // Hold dump alerts until Confirm/Skip so backing out of sell setup can't overwrite them.
        if (p != null && p.isRecentUnActionedDumpAlert()) {
            return false;
        }
        if (isModifyInProgress(p)) {
            return false;
        }
        if (grandExchange.isSlotOpen()) {
            if (!suggestionActionedOrVeryOutOfDate(p)) {
                return false;
            }
            if (liveOfferItemId(grandExchange.getOpenSlot()) != -1) {
                // Live offer behind open slot: don't yank the card while the player is using it.
                return false;
            }
        }

        return suggestionManager.isSuggestionNeeded() || suggestionManager.suggestionOutOfDate();
    }

    /** Offer editor open for the current MODIFY card — do not fetch a replacement. */
    private boolean isModifyInProgress(Suggestion p) {
        if (p != null && p.actionedTick != -1 && p.actionedTick <= client.getTickCount()) {
            return false;
        }
        return isEditorOnModify(p);
    }

    private boolean isEditorOnModify(Suggestion p) {
        if (!grandExchange.isSlotOpen()) {
            return false;
        }
        int open = grandExchange.getOpenSlot();
        int currentItem = grandExchange.getCurrentItemId();
        AccountStatusManager.OwnedModify owned = accountStatusManager.getOwnedModify();
        if (owned != null && owned.itemId > 0 && slotMatchesModify(open, currentItem, owned.itemId, owned.slot)) {
            return true;
        }
        return p != null && p.isModifySuggestion()
                && slotMatchesModify(open, currentItem, p.getItemId(), p.getBoxId());
    }

    private boolean slotMatchesModify(int open, int currentItem, int itemId, int boxId) {
        if (open < 0 || itemId <= 0) {
            return false;
        }
        if (ModifyStep.editorMatches(open, currentItem, itemId, boxId)) {
            return true;
        }
        return liveOfferItemId(open) == itemId;
    }

    /** Filling BUYING/SELLING only — CANCELLED_* still reports itemId after modify cancel. */
    private int liveOfferItemId(int slot) {
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null || slot < 0 || slot >= offers.length || offers[slot] == null) {
            return -1;
        }
        GrandExchangeOfferState st = offers[slot].getState();
        if (st != GrandExchangeOfferState.BUYING && st != GrandExchangeOfferState.SELLING) {
            return -1;
        }
        int itemId = offers[slot].getItemId();
        return itemId > 0 ? itemId : -1;
    }

    private void markGhostModifyActioned() {
        Suggestion p = suggestionManager.getSuggestion();
        if (p != null && p.isModifySuggestion() && p.actionedTick == -1) {
            p.actionedTick = 0;
        }
    }

    private boolean suggestionActionedOrVeryOutOfDate(Suggestion p) {
        if (p == null || p.isWaitSuggestion()) {
            return true;
        }
        if (p.actionedTick != -1 && p.actionedTick < client.getTickCount()) {
            return true;
        }
        return suggestionManager.suggestionVeryOutOfDate();
    }

    void reconcileUncollected() {
        if (client.getTickCount() <= uncollectedManager.getLastUncollectedAddedTick() + 2) {
            return;
        }
        if(!grandExchange.isHomeScreenOpen() || grandExchange.isCollectButtonVisible()) {
            return;
        }
        Long accountHash = osrsLoginManager.getAccountHash();
        boolean staleItems = uncollectedManager.HasUncollected(accountHash);
        boolean staleCard = suggestionPanel != null && suggestionPanel.isCollectItemsSuggested();
        if (!staleItems && !staleCard) {
            return;
        }
        if (staleItems) {
            log.warn("Clearing stale uncollected state: GE home is open without a Collect button");
            uncollectedManager.clearAllUncollected(accountHash);
        }
        if (staleCard) {
            suggestionPanel.clearCollectSuggestion();
        }
        suggestionManager.setSuggestionNeeded(true);
    }

    public void getSuggestionAsync() {
        if (!syncTradingContext()) return;
        if (suggestionManager.isSuggestionRequestInProgress()) {
            suggestionManager.setSuggestionNeeded(true);
            return;
        }
        suggestionManager.setSuggestionNeeded(false);
        if (!osrsLoginManager.isValidLoginState()) {
            suggestionManager.setSuggestionRefreshPending(false);
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
            return;
        }
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (accountStatus == null) {
            suggestionManager.setSuggestionRefreshPending(false);
            suggestionManager.setSuggestionNeeded(true);
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
            return;
        }
        Suggestion oldSuggestion = suggestionManager.getSuggestion();
        if (oldSuggestion != null && oldSuggestion.isRecentUnActionedDumpAlert()) {
            suggestionManager.setSuggestionRefreshPending(false);
            return;
        }
        suggestionManager.setSuggestionRequestInProgress(true);
        suggestionManager.setSuggestionRefreshPending(false);
        boolean skipGraphData = config.lowDataMode();
        final long requestGeneration = tradingContext.generation();
        Consumer<Suggestion> suggestionConsumer = (newSuggestion) ->
                receiveForContext(requestGeneration, oldSuggestion, newSuggestion, accountStatus, !skipGraphData);
        suggestionPanel.refresh();
        log.debug("tick {} getting suggestion", client.getTickCount());
        // Graphs are optional UI enrichment, never part of the compose critical path.
        runeAssistSource.getSuggestionAsync(suggestionConsumer, false);
    }

    void handleDumpSuggestion(Suggestion suggestion) {
        if (!syncTradingContext()) return;
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (accountStatus == null) {
            log.info("discarding dump suggestion as account status null");
            return;
        }
        Suggestion s = suggestionManager.getSuggestion();
        if(s != null && s.isDumpAlert && s.actionedTick == -1) {
            log.info("discarding dump suggestion as already processing dump suggestion");
            return;
        }
        if (accountStatus.emptySlotExists()) {
            handleSuggestionReceived(suggestionManager.getSuggestion(), suggestion, accountStatus,
                    !config.lowDataMode());
        } else {
            log.info("discarding dump suggestion as no free slot");
        }
    }

    void handleDumpSuggestion(Suggestion suggestion, long streamGeneration) {
        syncTradingContext();
        if (tradingContext.accepts(streamGeneration)) handleDumpSuggestion(suggestion);
    }

    /** Invalidate only suggestion/UI work; offer observation and history sync keep running. */
    boolean syncTradingContext() {
        boolean valid = osrsLoginManager.isValidLoginState();
        Suggestion current = suggestionManager.getSuggestion();
        boolean preserveDecantGuidance = valid && !pausedManager.isPaused()
                && tradingContext.sameAccount(osrsLoginManager.getAccountHash())
                && !grandExchange.isOpen() && current != null && current.isDecantSuggestion();
        boolean changed = tradingContext.update(osrsLoginManager.getAccountHash(), valid,
                valid && grandExchange.isOpen(), valid && pausedManager.isPaused());
        if (changed) {
            clearContextSuggestion();
            // Decanting itself requires leaving the GE. Keep only the already
            // issued local instruction; do not poll or announce new trades.
            if (preserveDecantGuidance) suggestionManager.setSuggestion(current);
            suggestionManager.setSuggestionNeeded(tradingContext.canRequest());
            if (suggestionPanel != null) suggestionPanel.refresh();
        }
        return tradingContext.canRequest();
    }

    void onSessionEnded() {
        tradingContext.invalidate();
        clearContextSuggestion();
    }

    private void clearContextSuggestion() {
        cancelSuggestionGraph();
        lastSuggestionGraph = null;
        suggestionManager.setSuggestion(null);
        suggestionManager.setSuggestionRequestInProgress(false);
        suggestionManager.setGraphDataReadingInProgress(false);
        suggestionManager.setSuggestionRefreshPending(false);
        suggestionManager.setSuggestionNeeded(false);
        suggestionManager.suggestionsDelayedUntil = 0;
        suggestionManager.setLastFailureAt(null);
        highlightController.removeAll();
    }

    void receiveForContext(long generation, Suggestion oldSuggestion, Suggestion newSuggestion,
                           AccountStatus accountStatus, boolean loadGraph) {
        syncTradingContext();
        // A stale reply must not release a newer request, change another account's
        // skip/protection state, display a card or emit a notification.
        if (!tradingContext.accepts(generation)) return;
        handleSuggestionReceived(oldSuggestion, newSuggestion, accountStatus, loadGraph);
    }

    private synchronized void handleSuggestionReceived(Suggestion oldSuggestion, Suggestion newSuggestion,
                                                       AccountStatus accountStatus, boolean loadGraph) {
        if (!newSuggestion.isDumpAlert && !suggestionManager.isSuggestionRequestInProgress()) {
            log.info("discarding suggestion as not dump alert and no request in progress {}", newSuggestion);
            return;
        }
        if (isGhostModify(newSuggestion)) {
            log.info("discarding ghost MODIFY item {} — no live offer, editor closed",
                    newSuggestion.getItemId());
            accountStatusManager.clearOwnedModify();
            markGhostModifyActioned();
            Suggestion current = suggestionManager.getSuggestion();
            if (current != null && current.isModifySuggestion()) {
                suggestionManager.setSuggestion(null);
            }
            suggestionManager.setSuggestionRequestInProgress(false);
            suggestionManager.setGraphDataReadingInProgress(false);
            suggestionManager.setSuggestionNeeded(true);
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
            getSuggestionAsync();
            return;
        }
        if (shouldKeepOwnedModify(oldSuggestion, newSuggestion)) {
            log.info("keeping in-progress MODIFY item {} slot {}; discarding {}",
                    oldSuggestion.getItemId(), oldSuggestion.getBoxId(), newSuggestion);
            suggestionManager.setSuggestionRequestInProgress(false);
            suggestionManager.setGraphDataReadingInProgress(false);
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
            return;
        }
        if (!isSellAvailableNow(newSuggestion)) {
            Suggestion wait = new Suggestion();
            wait.setType(SuggestionType.WAIT);
            wait.setMessage("Waiting for inventory update");
            suggestionManager.setSuggestion(wait);
            suggestionManager.setSuggestionRequestInProgress(false);
            suggestionManager.setGraphDataReadingInProgress(false);
            suggestionManager.setSuggestionNeeded(false);
            if (suggestionPanel != null) suggestionPanel.refresh();
            return;
        }
        if (newSuggestion.isBuySuggestion() || newSuggestion.isSellSuggestion()) {
            accountStatusManager.protectListing(newSuggestion.getItemId());
        }
        if (newSuggestion.isAbortSuggestion() && newSuggestion.getItemId() > 0) {
            accountStatusManager.skipItem(newSuggestion.getItemId());
        }
        if (newSuggestion.isBuyDumpSuggestion() && config.dumpAlertSound()) {
            playDumpAlertSound();
        }
        if (oldSuggestion != null && oldSuggestion.actionedTick == -1
                && oldSuggestion.getServerSuggestionId() != null
                && !oldSuggestion.getServerSuggestionId().isEmpty()
                && !Objects.equals(oldSuggestion.getServerSuggestionId(), newSuggestion.getServerSuggestionId()))
        {
            flipHistorySyncService.reportSuggestionOutcome(oldSuggestion, "superseded");
        }
        suggestionManager.setSuggestion(newSuggestion);
        suggestionManager.setLastFailureAt(com.runeassist.flip.RuneAssistSuggestionSource.isUnavailableWait(newSuggestion)
                ? Instant.now() : null);
        final long acceptedGeneration = tradingContext.generation();
        if (newSuggestion.getPortfolioItems() != null) portfolioStateRS.updatePortfolioState(
                newSuggestion.getBankItems(),
                newSuggestion.getPortfolioItems(),
                accountStatus.getOffers(),
                accountStatus.getUncollected(),
                newSuggestion.getTimeIssued(),
                () -> tradingContext.accepts(acceptedGeneration) && suggestionManager.getSuggestion() == newSuggestion
        );
        suggestionManager.setSuggestionRequestInProgress(false);
        log.debug("Received suggestion: {}", newSuggestion.toString());
        accountStatusManager.resetSkipSuggestion();
        offerManager.setOfferJustPlaced(false);
        suggestionPanel.refresh();
        showNotifications(oldSuggestion, newSuggestion, accountStatus);
        SwingUtilities.invokeLater(() -> {
            if (!tradingContext.accepts(acceptedGeneration) || suggestionManager.getSuggestion() != newSuggestion) return;
            if (flipDialogController.priceGraphPanel == null) {
                return;
            }
            if (!newSuggestion.isWaitSuggestion()) {
                flipDialogController.priceGraphPanel.newSuggestedItemId(
                        newSuggestion.getItemId(),
                        buildPriceLine(newSuggestion)
                );
            } else {
                flipDialogController.priceGraphPanel.suggestedPriceLine = null;
            }
        });
        if (client.getVarcIntValue(VarClientInt.INPUT_TYPE) == 14) {
            clientThread.invokeLater(() -> {
                if (syncTradingContext() && tradingContext.accepts(acceptedGeneration)
                        && suggestionManager.getSuggestion() == newSuggestion) gePreviousSearch.showSuggestedItemInSearch();
            });
        }
        feedSuggestionGraph(newSuggestion, loadGraph);
        runeAssistSource.getPortfolioItemsAsync((items, snapshotAt) -> receivePortfolioForContext(
                acceptedGeneration, newSuggestion, items, snapshotAt));
    }

    void receivePortfolioForContext(long generation, Suggestion suggestion, List<Suggestion.PortfolioItem> items, Instant snapshotAt) {
        syncTradingContext();
        // The source separately verifies unchanged held/offer snapshots. A newer
        // routine card alone must not starve a slow portfolio quote forever.
        if (!tradingContext.accepts(generation)) return;
        AccountStatus status = accountStatusManager.getAccountStatus();
        if (status == null) return;
        final long sequence = ++portfolioUpdateSequence;
        portfolioStateRS.updatePortfolioState(suggestion.getBankItems(), items,
                status.getOffers(), status.getUncollected(), snapshotAt,
                () -> tradingContext.accepts(generation) && sequence == portfolioUpdateSequence);
    }

    /** Bundled compose graph and/or GET /v1/graph. */
    void feedSuggestionGraph(Suggestion suggestion, boolean loadGraph) {
        if (!loadGraph) {
            cancelSuggestionGraph();
            return;
        }
        if (suggestion == null || suggestion.isWaitSuggestion() || suggestion.getItemId() <= 0) {
            cancelSuggestionGraph();
            Data d = new Data();
            if (suggestion != null && suggestion.isWaitSuggestion()) {
                d.fromWaitSuggestion = true;
            } else {
                d.loadingErrorMessage = "No graph data loaded for this item.";
            }
            displaySuggestionGraph(d, tradingContext.generation(), suggestion == null ? 0 : suggestion.getItemId());
            return;
        }
        if (suggestion.getGraphData() != null) {
            cancelSuggestionGraph();
            displaySuggestionGraph(suggestion.getGraphData(), tradingContext.generation(), suggestion.getItemId());
            return;
        }
        final int itemId = suggestion.getItemId();
        // A routine refresh of the same item must not cancel/restart a slow graph.
        if (suggestionGraphCall != null && suggestionGraphItemId == itemId) return;
        cancelSuggestionGraph();
        if (lastSuggestionGraph != null && lastSuggestionGraph.itemId == itemId
                && System.currentTimeMillis() - lastSuggestionGraphAt < 60_000L) {
            displaySuggestionGraph(lastSuggestionGraph, tradingContext.generation(), itemId);
            return;
        }
        suggestionGraphItemId = itemId;
        suggestionManager.setGraphDataReadingInProgress(true);
        final long graphGeneration = tradingContext.generation();
        final long sequence = graphRequestSequence;
        final long startedAt = System.nanoTime();
        Consumer<Data> graphDataConsumer = d -> clientThread.invokeLater(() -> {
            if (sequence != graphRequestSequence || !tradingContext.accepts(graphGeneration)) return;
            suggestionGraphCall = null;
            suggestionManager.setGraphDataReadingInProgress(false);
            d.itemId = itemId;
            lastSuggestionGraph = d;
            lastSuggestionGraphAt = System.currentTimeMillis();
            log.debug("suggestion graph enrichment elapsedMs={}", (System.nanoTime() - startedAt) / 1_000_000L);
            displaySuggestionGraph(d, graphGeneration, itemId);
        });
        suggestionGraphCall = apiRequestHandler.asyncGetRuneAssistGraph(itemId,
                graphDataConsumer,
                (Throwable err) -> {
                    log.debug("suggestion graph fetch failed for item {}: {}", itemId, err.toString());
                    Data d = new Data();
                    d.itemId = itemId;
                    d.loadingErrorMessage = "No graph data loaded for this item.";
                    graphDataConsumer.accept(d);
                });
    }

    private void displaySuggestionGraph(Data data, long generation, int itemId) {
        SwingUtilities.invokeLater(() -> {
            Suggestion current = suggestionManager.getSuggestion();
            if (!tradingContext.accepts(generation) || current == null || current.getItemId() != itemId) return;
            if (flipDialogController.priceGraphPanel != null) flipDialogController.priceGraphPanel.setSuggestionPriceData(data);
        });
    }

    private void cancelSuggestionGraph() {
        graphRequestSequence++;
        if (suggestionGraphCall != null) suggestionGraphCall.cancel();
        suggestionGraphCall = null;
        suggestionManager.setGraphDataReadingInProgress(false);
    }

    /** Drop refreshes that would switch away from an in-progress MODIFY of a different item. */
    private boolean shouldKeepOwnedModify(Suggestion oldSuggestion, Suggestion newSuggestion) {
        if (oldSuggestion == null || !oldSuggestion.isModifySuggestion()) {
            return false;
        }
        if (oldSuggestion.actionedTick != -1 || !isModifyInProgress(oldSuggestion)) {
            return false;
        }
        if (newSuggestion == null) {
            return true;
        }
        return !(newSuggestion.isModifySuggestion()
                && newSuggestion.getItemId() == oldSuggestion.getItemId());
    }

    /** MODIFY with no filling offer and editor closed — leftover lock after logout/collect. */
    public boolean isGhostModify(Suggestion s) {
        if (s == null || !s.isModifySuggestion() || s.getItemId() <= 0) {
            return false;
        }
        if (isEditorOnModify(s)) {
            return false;
        }
        return ModifyStep.isGhost(true, s.getItemId(), false,
                grandExchange.hasFillingOffer(s.getItemId()));
    }

    /** Direct sales need current physical stock, not only historical purchases. */
    public boolean isSellAvailableNow(Suggestion suggestion) {
        if (suggestion == null || !suggestion.isSellSuggestion()) return true;
        if (suggestion.getType() == SuggestionType.MODIFY_SELL) {
            if (grandExchange.hasFillingSellOffer(suggestion.getItemId())) return true;
            // Cancel/collect guidance is allowed before the relist editor. Once
            // preparing a new offer, only physical inventory can back its quantity.
            if (!grandExchange.isSetupOfferOpen() && uncollectedManager.loadAllUncollected(
                    osrsLoginManager.getAccountHash()).getOrDefault(suggestion.getItemId(), 0L) > 0) return true;
        }
        return runeAssistSource.hasInventoryForSale(suggestion);
    }

    private void playDumpAlertSound() {
        try {
            audioPlayer.play(SuggestionController.class, DUMP_ALERT_SOUND, 0);
        } catch (Exception e) {
            log.warn("failed to play dump alert sound", e);
        }
    }

    private PriceLine buildPriceLine(Suggestion suggestion) {
        if (suggestion.isBuySuggestion()) {
            return new PriceLine(suggestion.getPrice(), "Suggested buy price", false);
        }
        if (suggestion.isSellSuggestion()) {
            return new PriceLine(suggestion.getPrice(), "Suggested sell price", true);
        }
        return null;
    }

    void showNotifications(Suggestion oldSuggestion, Suggestion newSuggestion, AccountStatus accountStatus) {
        if (!tradingContext.canRequest()) return;
        if (shouldNotify(newSuggestion, oldSuggestion)) {
            String msg = newSuggestion.toMessage();
            if (config.enableTrayNotifications()) {
                notifier.notify(msg);
            }
            if (!runeAssistPanel.isShowing() && config.enableChatNotifications()) {
                showChatNotifications(newSuggestion, accountStatus);
            }
        }
    }

    static boolean shouldNotify(Suggestion newSuggestion, Suggestion oldSuggestion) {
        if (newSuggestion.isWaitSuggestion()) {
            return false;
        }
        return oldSuggestion == null || !newSuggestion.equals(oldSuggestion);
    }

    private void showChatNotifications(Suggestion newSuggestion, AccountStatus accountStatus) {
        final long notificationGeneration = tradingContext.generation();
        final boolean collectNeeded = accountStatus.isCollectNeeded(newSuggestion, grandExchange.isSetupOfferOpen());
        clientThread.invokeLater(() -> {
            if (!syncTradingContext() || !tradingContext.accepts(notificationGeneration)
                    || suggestionManager.getSuggestion() != newSuggestion) return;
            if (collectNeeded) showChatNotification("RuneAssist: Collect items");
            showChatNotification(newSuggestion.toMessage());
        });
    }

    private void showChatNotification(String message) {
        String chatMessage = new ChatMessageBuilder()
                .append(config.chatTextColor(), message)
                .build();
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", chatMessage, "");
    }

}

package com.runeassist.flip.controller;

import com.google.inject.Singleton;
import com.runeassist.flip.model.AccountStatus;
import com.runeassist.flip.model.AccountStatusManager;
import com.runeassist.flip.model.Suggestion;
import com.runeassist.flip.model.SuggestionPreferencesManager;
import com.runeassist.flip.rs.AccountSuggestionPreferencesRS;
import com.runeassist.flip.rs.GrandExchangeOpenRS;
import com.runeassist.flip.rs.OsrsLoginRS;
import com.runeassist.flip.rs.ReactiveState;
import com.runeassist.flip.rs.ReactiveStateUtil;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Response;
import okio.BufferedSource;

import javax.inject.Inject;
import java.io.IOException;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Subscribes to Ares {@code POST /v1/dump-alerts} when dump prefs are on, the
 * player is logged in, and the GE is open — same gating Flipping Copilot used,
 * without a Copilot login. Frames are uvarint-length JSON suggestion DTOs
 * (keepalive = zero-length frame).
 */
@Slf4j
@Singleton
public class DumpsStreamController {

    private static final long MAX_FRAME_BYTES = 1 << 20;

    private final ClientThread clientThread;
    private final ApiRequestHandler apiRequestHandler;
    private final SuggestionController suggestionController;
    private final SuggestionPreferencesManager preferencesManager;
    private final AccountStatusManager accountStatusManager;
    private final AtomicReference<Call> activeCall = new AtomicReference<>();
    private final ReactiveState<Boolean> shouldSubscribe;
    private long subscribedGeneration = -1;

    @Inject
    public DumpsStreamController(
            ClientThread clientThread,
            ApiRequestHandler apiRequestHandler,
            SuggestionController suggestionController,
            SuggestionPreferencesManager preferencesManager,
            AccountStatusManager accountStatusManager,
            AccountSuggestionPreferencesRS accountSuggestionPreferencesRS,
            OsrsLoginRS osrsLoginRS,
            GrandExchangeOpenRS grandExchangeOpenRS) {
        this.clientThread = clientThread;
        this.apiRequestHandler = apiRequestHandler;
        this.suggestionController = suggestionController;
        this.preferencesManager = preferencesManager;
        this.accountStatusManager = accountStatusManager;
        this.shouldSubscribe = ReactiveStateUtil.derive(
                osrsLoginRS,
                accountSuggestionPreferencesRS,
                grandExchangeOpenRS,
                (loginState, preferences, isGrandExchangeOpen) ->
                        loginState != null
                                && loginState.loggedIn
                                && preferences != null
                                && preferences.isReceiveDumpSuggestions()
                                && Boolean.TRUE.equals(isGrandExchangeOpen));
        shouldSubscribe.registerListener(active -> {
            if (Boolean.TRUE.equals(active)) {
                clientThread.invokeLater(this::onGameTick);
            } else {
                ensureUnsubscribed();
            }
        });
    }

    public void ensureUnsubscribed() {
        Call call = activeCall.getAndSet(null);
        if (call != null) {
            call.cancel();
        }
    }

    /** Keep the optional stream bound to the same local account/trading session. */
    void onGameTick() {
        long generation = suggestionController.getTradingContext().generation();
        boolean active = Boolean.TRUE.equals(shouldSubscribe.get())
                && suggestionController.getTradingContext().canRequest();
        if (!active || generation != subscribedGeneration || activeCall.get() == null) {
            ensureUnsubscribed();
            subscribedGeneration = generation;
            if (active) consumeDumps();
        }
    }

    private void consumeDumps() {
        if (!Boolean.TRUE.equals(shouldSubscribe.get())
                || !suggestionController.getTradingContext().canRequest()) {
            return;
        }
        final long streamGeneration = suggestionController.getTradingContext().generation();
        Call previous = activeCall.get();
        Map<String, Object> filters = buildFilters();
        Call call = apiRequestHandler.asyncConsumeDumpAlerts(
                filters,
                response -> consumeDumpStream(response, streamGeneration),
                error -> {
                    log.warn("dump alerts connection failed, re-connecting: {}", error.getMessage());
                    retryIfCurrent(streamGeneration);
                });
        log.info("subscribing to dump alerts");
        if (activeCall.getAndSet(call) != previous || !Boolean.TRUE.equals(shouldSubscribe.get())) {
            ensureUnsubscribed();
        }
    }

    private void retryIfCurrent(long generation) {
        clientThread.invokeLater(() -> {
            if (Boolean.TRUE.equals(shouldSubscribe.get())
                    && suggestionController.getTradingContext().accepts(generation)) consumeDumps();
        });
    }

    private Map<String, Object> buildFilters() {
        Map<String, Object> body = new HashMap<>();
        Long minProfit = preferencesManager.getEffectiveDumpMinPredictedProfit();
        if (minProfit != null) {
            body.put("dumpMinPredictedProfit", minProfit);
        }
        body.put("f2pOnly", preferencesManager.isF2pOnlyMode());
        List<Integer> blocked = preferencesManager.blockedItems();
        if (blocked != null && !blocked.isEmpty()) {
            body.put("blockedIds", blocked);
        }
        try {
            AccountStatus status = accountStatusManager.getAccountStatus();
            if (status != null) {
                long cash = status.currentCashStack();
                if (cash > 0) {
                    body.put("capital", cash);
                }
                if (status.emptySlotExists()) {
                    body.put("remainingSlots", 1);
                }
            }
        } catch (Exception e) {
            log.debug("dump filter account snapshot failed: {}", e.getMessage());
        }
        return body;
    }

    /** Each frame is a uvarint byte length followed by that many bytes of JSON; zero-length = keepalive. */
    private void consumeDumpStream(Response response, long streamGeneration) {
        try (Response resp = response) {
            BufferedSource source = resp.body().source();
            while (activeCall.get() != null && suggestionController.getTradingContext().accepts(streamGeneration)) {
                long length = readUvarint(source);
                if (length == 0) {
                    continue;
                }
                if (length < 0 || length > MAX_FRAME_BYTES) {
                    throw new IOException("invalid dump frame length: " + length);
                }
                handleDumpMessage(source.readByteArray(length), streamGeneration);
            }
        } catch (IOException e) {
            if (Boolean.TRUE.equals(shouldSubscribe.get())) {
                log.warn("dump alerts stream error", e);
                retryIfCurrent(streamGeneration);
            } else {
                log.info("consumeDumpStream ended gracefully");
            }
        }
    }

    private static long readUvarint(BufferedSource source) throws IOException {
        long value = 0;
        for (int shift = 0; shift < 64; shift += 7) {
            int b = source.readByte() & 0xFF;
            value |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return value;
            }
        }
        throw new IOException("dump frame length is not a valid uvarint");
    }

    private void handleDumpMessage(byte[] data, long streamGeneration) {
        Suggestion suggestion = apiRequestHandler.decodeDumpSuggestionFrame(data);
        if (suggestion == null) {
            log.warn("dump suggestion decode failed");
            return;
        }
        suggestion.setDumpAlert(true);
        suggestion.setDumpAlertReceived(Instant.now());
        if (suggestion.getMessage() == null || suggestion.getMessage().isEmpty()) {
            suggestion.setMessage("<html><b><font color=#FA4A4B>Dump alert!!</font></b></html>");
        }
        clientThread.invoke(() -> suggestionController.handleDumpSuggestion(suggestion, streamGeneration));
        log.info("received dump suggestion {} {}", suggestion.getName(), suggestion.getType());
    }
}

package com.runeassist.flip.controller;

import com.runeassist.flip.ui.PatchNotesPopup;
import com.runeassist.flip.ui.UIUtilities;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.io.IOException;
import net.runelite.client.util.Filepath;

@Singleton
@Slf4j
public class PatchNotesController {

    static final String PATCH_NOTES_VERSION_FILE = "patch-notes-version.txt";

    public void maybeShowOnStartup(Component parent, boolean hadExistingInstallation) {
        if (!UIUtilities.ensureEdt(() -> maybeShowOnStartup(parent, hadExistingInstallation))) return;

        int latestVersion = PatchNotesPopup.LATEST_VERSION;
        Integer lastSeenVersion = loadLastSeenVersion();
        boolean shouldShow = shouldShowPatchNotes(latestVersion, lastSeenVersion, hadExistingInstallation);
        persistSeenVersion(lastSeenVersion == null ? latestVersion : Math.max(lastSeenVersion, latestVersion));

        if (!shouldShow || GraphicsEnvironment.isHeadless()) {
            return;
        }

        Window owner = parent == null ? null : SwingUtilities.getWindowAncestor(parent);
        PatchNotesPopup.show(owner != null ? owner : parent);
    }

    static boolean shouldShowPatchNotes(int currentVersion, Integer lastSeenVersion, boolean hadExistingInstallation) {
        if (lastSeenVersion != null) {
            return currentVersion > lastSeenVersion;
        }
        return hadExistingInstallation;
    }

    private Integer loadLastSeenVersion() {
        Filepath patchNotesVersionPath = patchNotesVersionPath();
        if (!patchNotesVersionPath.exists()) {
            return null;
        }

        try {
            String rawVersion = Persistance.readString(patchNotesVersionPath).trim();
            return rawVersion.isEmpty() ? null : Integer.parseInt(rawVersion);
        } catch (IOException | NumberFormatException e) {
            log.warn("error loading patch notes version from {}", patchNotesVersionPath, e);
            return null;
        }
    }

    private void persistSeenVersion(int version) {
        Filepath patchNotesVersionPath = patchNotesVersionPath();

        try {
            patchNotesVersionPath.write(Integer.toString(version));
        } catch (IOException e) {
            log.warn("error saving patch notes version to {}", patchNotesVersionPath, e);
        }
    }

    private Filepath patchNotesVersionPath() {
        return Persistance.file(PATCH_NOTES_VERSION_FILE);
    }
}

package com.runeassist.flip.controller;
import com.runeassist.flip.model.*;
import com.runeassist.flip.ui.GpDropOverlay;

import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.ui.overlay.OverlayManager;

import static com.runeassist.flip.model.OsrsLoginManager.GE_LOGIN_BURST_WINDOW;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GrandExchangeOfferEventHandler {

    // dependencies
    private final Client client;
    private final OfferManager offerPersistence;
    private final GrandExchange grandExchange;
    private final TransactionManager transactionManager;
    private final OsrsLoginManager osrsLoginManager;
    private final OverlayManager overlayManager;
    private final GrandExchangeUncollectedManager grandExchangeUncollectedManager;
    private final SuggestionManager suggestionManager;
    private final AccountStatusManager accountStatusManager;
    private final FlipHistorySyncService flipHistorySyncService;

    // state
    private final Queue<Transaction> transactionsToProcess = new ConcurrentLinkedQueue<>();
    private final OfferObservationTracker observationTracker = new OfferObservationTracker();

    public void resetObservationSession() {
        observationTracker.reset();
    }

    public void onGameTick() {
        if(!transactionsToProcess.isEmpty()) {
            processTransactions();
        }
    }

    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged offerEvent) {
        final int slot = offerEvent.getSlot();
        final GrandExchangeOffer offer = offerEvent.getOffer();
        Long accountHash = client.getAccountHash();

        if (offer.getState() == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN) {
            // Trades are cleared by the client during LOGIN_SCREEN/HOPPING/LOGGING_IN, ignore those
            return;
        }
        if (osrsLoginManager.isUnsupportedWorldType()) {
            log.debug("ignoring GE offer update on unsupported world type(s): {}", client.getWorldType());
            return;
        }

        log.debug("tick {} GE offer updated: state: {}, slot: {}, item: {}, qty: {}, lastLoginTick: {}", client.getTickCount(), offer.getState(), slot, offer.getItemId(), offer.getQuantitySold(), osrsLoginManager.getLastLoginTick());

        SavedOffer o = SavedOffer.fromGrandExchangeOffer(offer);

        SavedOffer prev = offerPersistence.loadOffer(accountHash, slot);
        boolean loginBurst = client.getGameState() != GameState.LOGGED_IN
                || client.getTickCount() <= osrsLoginManager.getLastLoginTick() + GE_LOGIN_BURST_WINDOW;
        boolean firstObservation = observationTracker.observe(accountHash, slot, o, loginBurst,
                Instant.now().toEpochMilli());

        if(Objects.equals(o, prev)) {
            // Persisted equality does not mean this session observed the placement.
            if (firstObservation) flipHistorySyncService.reportOfferEvent(slot, o, prev);
            log.debug("skipping duplicate offer event {}", o);
            return;
        }

        if (isNewOffer(prev, o)) {
            String suggestionId = suggestionManager.matchingSubmittedSuggestion(
                    o.getItemId(), o.getOfferStatus(), client.getTickCount());
            o.setSuggestionId(suggestionId);
            o.setRuneAssistSuggestion(suggestionId != null);
        } else if (prev != null) {
            o.setSuggestionId(prev.getSuggestionId());
            o.setRuneAssistSuggestion(prev.isRuneAssistSuggestion());
        }

        boolean consistent = isConsistent(prev, o);
        if(!consistent) {
            log.warn("offer on slot {} is inconsistent with previous saved offer", slot);
        }

        Transaction t = inferTransaction(slot, o, prev, consistent);
        if(t != null) {
            transactionsToProcess.add(t);
            processTransactions();
            log.debug("inferred transaction {}", t);
        }
        flipHistorySyncService.reportOfferEvent(slot, o, prev);
        updateUncollected(accountHash, slot, o, prev, consistent);
        offerPersistence.saveOffer(accountHash, slot, o);

        // Own a freshly listed or modified offer for ~10 min (leftover qty after
        // cancel-relist looks like sold==0 and must not abort the same tick).
        if (!loginBurst && isNewOffer(prev, o)) {
            GrandExchangeOfferState st = o.getState();
            if ((st == GrandExchangeOfferState.BUYING || st == GrandExchangeOfferState.SELLING)
                    && o.getItemId() > 0) {
                accountStatusManager.protectListing(o.getItemId());
            }
        }

        boolean editorOpen = grandExchange.isSlotOpen();
        if (o.getState() == GrandExchangeOfferState.EMPTY) {
            accountStatusManager.releaseOwnedModifyIfSlotEmpty(slot, editorOpen);
        }
        accountStatusManager.releaseStaleOwnedModify(client.getGrandExchangeOffers(), editorOpen);

        // Always fetch suggestion to ensure fast response for better UX — except while
        // a MODIFY is in progress: cancel-then-relist empties the slot and would emit BUY.
        if (!accountStatusManager.isOwnedModifyActive() || !editorOpen) {
            suggestionManager.setSuggestionNeeded(true);
        }
    }


    private void updateUncollected(Long accountHash, int slot, SavedOffer o, SavedOffer prev, boolean consistent) {
        if(!consistent) {
            return;
        }
        long uncollectedGp = 0;
        int uncollectedItems = 0;
        switch (o.getState()) {
            case BUYING:
            case BOUGHT:
                uncollectedItems = isNewOffer(prev, o) ? o.getQuantitySold() : o.getQuantitySold() - prev.getQuantitySold();
                break;
            case SOLD:
            case SELLING:
                uncollectedGp = (isNewOffer(prev, o) ? o.getQuantitySold() : o.getQuantitySold() - prev.getQuantitySold()) * o.getPrice();
                break;
            case CANCELLED_BUY:
                uncollectedGp = (o.getTotalQuantity() - o.getQuantitySold()) * o.getPrice();
                break;
            case CANCELLED_SELL:
                uncollectedItems = o.getTotalQuantity() - o.getQuantitySold();
                break;
            case EMPTY:
                // if the slot is empty we want to ensure that the un collected manager doesn't think there is something to collect
                // this can happen due to race conditions between the collection and offer fills timing
                grandExchangeUncollectedManager.ensureSlotClear(accountHash, slot);
                if (!accountStatusManager.isOwnedModifyActive() || !grandExchange.isSlotOpen()) {
                    suggestionManager.setSuggestionNeeded(true);
                }
                return;
        }
        grandExchangeUncollectedManager.addUncollected(accountHash, slot, o.getItemId(), uncollectedItems, uncollectedGp);

    }

    private void processTransactions() {
        if (osrsLoginManager.isUnsupportedWorldType()) {
            return;
        }
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if(displayName != null) {
            Transaction transaction;
            while ((transaction = transactionsToProcess.poll()) != null) {
                long profit = transactionManager.addTransaction(transaction, displayName);
                // Only a sale realises profit or loss. A buy that adds to an open position
                // used to be valued as if it had closed it, flashing a red "-x gp" on fills.
                if (grandExchange.isHomeScreenOpen() && profit != 0
                        && transaction.getType() == OfferStatus.SELL) {
                    new GpDropOverlay(overlayManager, client, profit, transaction.getBoxId());
                }
            }
        }
    }

    public Transaction inferTransaction(int slot, SavedOffer offer, SavedOffer prev, boolean consistent) {
        boolean login = client.getTickCount() <= osrsLoginManager.getLastLoginTick() + GE_LOGIN_BURST_WINDOW;
        return inferFill(slot, offer, prev, consistent, login);
    }

    /** Infer a fill from consecutive offer snapshots; fall back to price*qty when spent lags. */
    static Transaction inferFill(int slot, SavedOffer offer, SavedOffer prev, boolean consistent, boolean login) {
        boolean newOffer = isNewOffer(prev, offer);
        int prevSold = (newOffer || prev == null) ? 0 : prev.getQuantitySold();
        long prevSpent = (newOffer || prev == null) ? 0L : prev.getSpent();
        int quantityDiff = offer.getQuantitySold() - prevSold;
        long amountSpentDiff = offer.getSpent() - prevSpent;
        if (quantityDiff <= 0) {
            return null;
        }
        if (amountSpentDiff <= 0) {
            amountSpentDiff = offer.getPrice() * (long) quantityDiff;
        }
        if (amountSpentDiff <= 0) {
            return null;
        }
        Transaction t = new Transaction();
        t.setId(UUID.randomUUID());
        t.setType(offer.getOfferStatus());
        t.setItemId(offer.getItemId());
        t.setPrice(offer.getPrice());
        t.setQuantity(quantityDiff);
        t.setBoxId(slot);
        t.setAmountSpent(amountSpentDiff);
        t.setTimestamp(Instant.now());
        t.setLogin(login);
        t.setConsistent(consistent);
        t.setRuneAssistSuggestion(offer.isRuneAssistSuggestion());
        t.setSuggestionId(offer.getSuggestionId());
        return t;
    }

    private boolean isConsistent(SavedOffer prev, SavedOffer updated) {
        if(prev == null) {
            return false;
        }
        if(updated.getState() == GrandExchangeOfferState.EMPTY) {
            return true;
        }
        if(prev.getState() == GrandExchangeOfferState.EMPTY && !(updated.getState() == GrandExchangeOfferState.CANCELLED_BUY || updated.getState() == GrandExchangeOfferState.CANCELLED_SELL)) {
            return true;
        }
        return prev.getOfferStatus() == updated.getOfferStatus() ||
                prev.getItemId() == updated.getItemId()
                || prev.getPrice() == updated.getPrice()
                || prev.getTotalQuantity() == updated.getTotalQuantity();
    }

    static boolean isNewOffer(SavedOffer prev, SavedOffer updated) {
        if (prev == null) {
            return true;
        }
        return prev.getOfferStatus() != updated.getOfferStatus() ||
                prev.getItemId() != updated.getItemId()
                || prev.getPrice() != updated.getPrice()
                || prev.getTotalQuantity() != updated.getTotalQuantity()
                || prev.getQuantitySold() > updated.getQuantitySold()
                || prev.getSpent() > updated.getSpent();
    }
}

package com.runeassist.flip.manager;

import com.runeassist.flip.controller.Persistance;
import com.runeassist.flip.ui.graph.model.Config;
import com.google.gson.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.NoSuchFileException;
import net.runelite.client.util.Filepath;
import java.util.concurrent.ScheduledExecutorService;


@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PriceGraphConfigManager {

    public static final String JSON_FILE = "price_graph_config.json";

    private final Object fileLock = new Object();

    // dependencies
    private final Gson gson;
    private final ScheduledExecutorService executorService;

    // state
    private Config cachedConfig;

    public synchronized Config getConfig() {
        if(cachedConfig != null) {
            return cachedConfig;
        }
        cachedConfig = load();
        return cachedConfig;
    }

    public synchronized void setConfig(Config config) {
        if (config == null) {
            return;
        }
        cachedConfig = config;
        saveAsync();
    }

    public void saveAsync() {
        executorService.submit(() -> {
            synchronized (fileLock) {
                Config config = getConfig();
                try {
                    Persistance.file(JSON_FILE).write(gson.toJson(config));
                } catch (IOException e) {
                    log.warn("error saving graph config {}", e.getMessage(), e);
                }
            }
        });
    }

    public Config load() {
        Filepath file = Persistance.file(JSON_FILE);
        try (BufferedReader reader = file.openBufferedReader()) {
            return gson.fromJson(reader, Config.class);
        } catch (NoSuchFileException ignored) {
            return new Config();
        } catch (JsonSyntaxException | JsonIOException | IOException e) {
            log.warn("error loading saved graph config json file {}", file, e);
            return new Config();
        }
    }
}

package com.runeassist.flip.rs;

import com.runeassist.flip.model.AccountLoginState;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;


@Singleton
@Slf4j
public class AccountLoginRS extends ReactiveStateImpl<AccountLoginState> {

    @Inject
    public AccountLoginRS() {
        super(new AccountLoginState());
        registerListener((s) -> log.debug("AccountLoginRS to {}", s));
    }

    public void removeAccount(Integer accountId) {
        update((s) -> {
            AccountLoginState updated = s.copy();
            String displayName = updated.accountIdToDisplayName.get(accountId);
            updated.accountIdToDisplayName.remove(accountId);
            if(displayName != null){
                updated.displayNameToAccountId.remove(displayName);
            }
            return updated;
        });
    }

    public void addAccountIfMissing(Integer accountId, String displayName) {
        update((s) -> {
            if (accountId == null || displayName == null || s.accountIdToDisplayName.containsKey(accountId)) {
                return s;
            }
            AccountLoginState updated = s.copy();
            updated.displayNameToAccountId.put(displayName, accountId);
            updated.accountIdToDisplayName.put(accountId, displayName);
            return updated;
        });
    }
}

