package com.runeassist.flip.rs;

import java.util.function.BiConsumer;
import java.util.function.Function;

public final class ReactiveStateUtil {

    private ReactiveStateUtil() {
    }

    public static <A, B> void registerJointListener(
            ReactiveState<A> first,
            ReactiveState<B> second,
            BiConsumer<A, B> listener) {
        first.registerListener(value -> listener.accept(value, second.get()));
        second.registerListener(value -> listener.accept(first.get(), value));
    }

    public static <A, B> ReactiveState<B> derive(ReactiveState<A> source, Function<A, B> transform) {
        ReactiveStateImpl<B> derived = new ReactiveStateImpl<>(transform.apply(source.get()));
        source.registerListener(value -> derived.set(transform.apply(value)));
        return derived;
    }

    public static <A, B, C, D> ReactiveState<D> derive(
            ReactiveState<A> first,
            ReactiveState<B> second,
            ReactiveState<C> third,
            TriFunction<A, B, C, D> transform) {
        ReactiveStateImpl<D> derived = new ReactiveStateImpl<>(transform.apply(first.get(), second.get(), third.get()));
        registerJointListener(first, second, third, (value1, value2, value3) ->
                derived.set(transform.apply(value1, value2, value3)));
        return derived;
    }

    public static <A, B, C, D, E> ReactiveState<E> derive(
            ReactiveState<A> first,
            ReactiveState<B> second,
            ReactiveState<C> third,
            ReactiveState<D> fourth,
            QuadFunction<A, B, C, D, E> transform) {
        ReactiveStateImpl<E> derived = new ReactiveStateImpl<>(transform.apply(first.get(), second.get(), third.get(), fourth.get()));
        registerJointListener(first, second, third, fourth, (value1, value2, value3, value4) ->
                derived.set(transform.apply(value1, value2, value3, value4)));
        return derived;
    }

    public static <A, B, C> void registerJointListener(
            ReactiveState<A> first,
            ReactiveState<B> second,
            ReactiveState<C> third,
            TriConsumer<A, B, C> listener) {
        first.registerListener(value -> listener.accept(value, second.get(), third.get()));
        second.registerListener(value -> listener.accept(first.get(), value, third.get()));
        third.registerListener(value -> listener.accept(first.get(), second.get(), value));
    }

    public static <A, B, C, D> void registerJointListener(
            ReactiveState<A> first,
            ReactiveState<B> second,
            ReactiveState<C> third,
            ReactiveState<D> fourth,
            QuadConsumer<A, B, C, D> listener) {
        first.registerListener(value -> listener.accept(value, second.get(), third.get(), fourth.get()));
        second.registerListener(value -> listener.accept(first.get(), value, third.get(), fourth.get()));
        third.registerListener(value -> listener.accept(first.get(), second.get(), value, fourth.get()));
        fourth.registerListener(value -> listener.accept(first.get(), second.get(), third.get(), value));
    }

    @FunctionalInterface
    public interface TriConsumer<A, B, C> {
        void accept(A first, B second, C third);
    }

    @FunctionalInterface
    public interface QuadConsumer<A, B, C, D> {
        void accept(A first, B second, C third, D fourth);
    }

    @FunctionalInterface
    public interface TriFunction<A, B, C, D> {
        D apply(A first, B second, C third);
    }

    @FunctionalInterface
    public interface QuadFunction<A, B, C, D, E> {
        E apply(A first, B second, C third, D fourth);
    }
}

package com.runeassist.flip.rs;

import com.runeassist.flip.controller.Persistance;
import com.runeassist.flip.model.AccountSuggestionPreferences;
import com.google.gson.Gson;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import com.google.inject.name.Named;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.nio.file.StandardCopyOption;
import net.runelite.client.util.Filepath;
import java.util.concurrent.ScheduledExecutorService;

@Singleton
@Slf4j
public class AccountSuggestionPreferencesRS extends ReactiveStateImpl<AccountSuggestionPreferences> {

    private final Gson gson;
    private final ScheduledExecutorService executorService;
    private final ReactiveState<Long> accountHashState;
    private final Filepath dataDir;

    @Inject
    public AccountSuggestionPreferencesRS(Gson gson,
                                          @Named("runeAssistExecutor") ScheduledExecutorService executorService,
                                          OsrsLoginRS osrsLoginRS,
                                          @Named("runeAssistDataDir") Filepath dataDir) {
        super(new AccountSuggestionPreferences());
        this.gson = gson;
        this.dataDir = dataDir;
        this.executorService = executorService;
        this.accountHashState = ReactiveStateUtil.derive(osrsLoginRS, s -> s == null ? null : s.accountHash);
        this.accountHashState.registerListener(ah -> this.executorService.submit(() -> loadAccountPreferences(ah)));
        Long accountHash = accountHashState.get();
        this.executorService.submit(() -> loadAccountPreferences(accountHash));
    }

    /**
     * True once an OSRS account hash is known. The hash is retained after logout, so preferences
     * remain editable and persistable for the last account seen in this client run.
     */
    public boolean hasAccount() {
        return accountHashState.get() != null;
    }

    public void updateAndPersist(AccountSuggestionPreferences preferences) {
        Long osrsAccountHash = accountHashState.get();
        if (osrsAccountHash == null) {
            // Callers must gate on hasAccount(); reaching here drops the change on the floor.
            log.error("updateAndPersist called before any OSRS account hash is known, discarding {}", preferences);
        } else {
            forceSet(preferences);
            executorService.submit(() -> persist(preferences, osrsAccountHash));
        }
    }

    private synchronized void persist(AccountSuggestionPreferences preferences, Long ah) {
        Filepath file = accountPreferencesPath(ah, "");
        Filepath tmpFile = accountPreferencesPath(ah, ".tmp");
        try {
            String toWrite = gson.toJson(preferences);
            try {
                tmpFile.write(toWrite);
                tmpFile.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            } finally {
                tmpFile.deleteIfExists();
            }
        } catch (IOException e) {
            log.warn("error saving account preferences json file {}", file, e);
        }
    }

    private void loadAccountPreferences(Long accountHash) {
        AccountSuggestionPreferences preferences = new AccountSuggestionPreferences();
        if (accountHash != null) {
            Filepath file = accountPreferencesPath(accountHash, "");
            try {
                if (file.exists()) {
                    preferences = gson.fromJson(Persistance.readString(file), AccountSuggestionPreferences.class);
                }
            } catch (IOException e) {
                log.warn("error loading account preferences json file {}", file, e);
            }
        }
        set(preferences);
    }

    private Filepath accountPreferencesPath(Long accountHash, String suffix) {
        return dataDir.joinSegment("acc_" + accountHash + "_prefs.json" + suffix);
    }
}

package com.runeassist.flip.rs;

import java.util.function.Consumer;
import java.util.function.Function;

public interface ReactiveState<T> {
    Runnable registerListener(Consumer<T> onUpdate);
    void update(Function<T, T> update);
    T get();
    void set(T newValue);
}

package com.runeassist.flip.rs;

import com.runeassist.flip.controller.ItemController;
import com.runeassist.flip.model.BankState;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

import java.util.Map;
import java.util.Objects;

@Singleton
@Slf4j
public class BankStateRS extends ReactiveStateImpl<BankState> {
    private final ItemController itemController;
    private final OsrsLoginRS osrsLoginRS;

    @Inject
    public BankStateRS(ItemController itemController, OsrsLoginRS osrsLoginRS) {
        super(BankState.empty());
        this.itemController = itemController;
        this.osrsLoginRS = osrsLoginRS;
        osrsLoginRS.registerListener(state -> {
            if (state == null) {
                set(BankState.empty());
                return;
            }

            if (!state.loggedIn) {
                return;
            }

            Long accountHash = state.accountHash;
            Long loadedAccountHash = get().getLoadedAccountHash();
            if (loadedAccountHash != null && !Objects.equals(loadedAccountHash, accountHash)) {
                set(BankState.empty());
            }
        });
    }

    public void onGameTick() {
        if (!osrsLoginRS.get().loggedIn) {
            return;
        }
        Map<Integer, Integer> bankInventory = itemController.getRunliteBankInventory();
        if (bankInventory == null) {
            return;
        }
        set(new BankState(true, bankInventory, osrsLoginRS.get().accountHash));
    }
}

package com.runeassist.flip.rs;

import lombok.AllArgsConstructor;

import java.util.Objects;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import java.util.function.Function;

@AllArgsConstructor
public class ReactiveStateImpl<T> implements ReactiveState<T> {

    private final CopyOnWriteArrayList<Consumer<T>> listeners = new CopyOnWriteArrayList<>();
    private volatile T state;

    @Override
    public Runnable registerListener(Consumer<T> onUpdate) {
        listeners.add(onUpdate);
        return () -> listeners.remove(onUpdate);
    }

    @Override
    public void update(Function<T, T> updateFunc) {
        setAndPublish(updateFunc.apply(get()));
    }

    @Override
    public void set(T newState) {
        if (!Objects.equals(newState, get())) {
            setAndPublish(newState);
        }
    }

    public void forceSet(T newState) {
        setAndPublish(newState);
    }

    @Override
    public T get() {
        return state;
    }

    private void setAndPublish(T value) {
        synchronized (this) {
            state = value;
        }
        listeners.forEach(i -> i.accept(value));
    }
}

